window.IA = {"lang": "fr", "ui": {"app_title": "Académie des interprètes ClayArena", "tagline": "Le tir sur cibles d'argile pour les interprètes, en partant de zéro", "hero_p": "Douze missions pour apprendre la langue du Parcours de Chasse – Sporting™ et du Compak® Sporting : les plateaux et leurs trajectoires, le fusil, l'avance et la technique de tir, les règlements FITASC, les annonces de l'arbitre et l'étiquette du sport. Ensuite, entraînez-vous comme sur un vrai poste : traduisez le moniteur, reconnaissez le plateau, trouvez l'avance et prenez la décision de l'arbitre.", "missions": "Missions", "practice": "Pratique", "start": "Commencer", "continue": "Continuer", "lessons_n": "leçons", "min": "min", "back": "Retour", "back_mission": "Vers la mission", "home": "Accueil", "key_points": "L'essentiel", "coach_says": "Le moniteur dit", "listen": "Écouter", "reveal": "Afficher le sens", "meaning": "Sens", "say_it": "Comment le dire", "terms": "Termes", "rules_refs": "Dans les règlements FITASC", "sources": "Sources", "quiz": "Testez-vous", "correct": "Exact !", "wrong": "Pas tout à fait.", "next": "Suivant", "next_lesson": "Leçon suivante", "finish_lesson": "Leçon terminée", "xp": "XP", "level": "Niveau", "levels": ["Débutant", "Auditeur", "Interprète au stand", "Interprète au poste", "Interprète confirmé"], "done_of": "terminées", "game_coach": "Traduisez le moniteur", "game_coach_d": "Écoutez une phrase du moniteur en anglais et choisissez ce qu'elle veut vraiment dire.", "game_flight": "Nommez la trajectoire", "game_flight_d": "Regardez voler un plateau et nommez sa présentation.", "game_lead": "Labo de l'avance", "game_lead_d": "Voyez comment fonctionne l'avance avec chaque méthode, puis appuyez vous-même sur la détente.", "game_call": "Décision de l'arbitre", "game_call_d": "Des situations réelles sur le poste : que décide l'arbitre ?", "game_terms": "Cartes de termes", "game_terms_d": "Associez le terme anglais au mot qu'emploient les tireurs dans votre langue.", "game_exam": "Examen final", "game_exam_d": "30 questions tirées de toutes les missions. Obtenez 80 % et recevez votre certificat.", "which_flight": "Quelle est cette présentation ?", "which_meaning": "Que veut dire le moniteur ?", "which_term": "Comment les tireurs le disent-ils dans votre langue ?", "which_def": "Que signifie ce terme ?", "launch": "Lancer", "again": "Encore", "score": "Score", "play_again": "Rejouer", "method": "Méthode", "m_maintained": "Avance maintenue (maintained lead)", "m_swing": "Swing (swing-through)", "m_pullaway": "Départ sur le plateau (pull-away)", "m_ambush": "Embuscade (ambush)", "speed": "Vitesse du plateau", "distance": "Distance", "demo": "Voir la méthode", "try": "À vous : appuyez au moment où vous tireriez", "shoot": "Tirer", "hit": "Touché ! Le plateau est cassé.", "behind": "Derrière : la gerbe est passée derrière le plateau", "ahead": "Devant : la gerbe est passée devant le plateau", "perceived": "Avance perçue au moment de la décision", "actual": "Avance réelle au moment du tir", "lab_note": "Ralenti et physique simplifiée pour l'apprentissage : vitesse moyenne des plombs d'environ 330 m/s, 0,15 s entre la décision et le coup, rayon de la gerbe d'environ 10 cm + 1,5 cm par mètre de distance, bouche du canon à environ 1 m de l'œil. L'avance réelle dépend de la vitesse, de la distance, de l'angle et de la cartouche ; l'avance perçue dépend aussi de la méthode et du tireur.", "exam_pass": "Réussi ! Vous pouvez maintenant obtenir votre certificat.", "exam_fail": "Pas encore : il faut 80 %. Revoyez les missions et réessayez.", "cert_name": "Votre nom pour le certificat", "cert_print": "Imprimer ou enregistrer en PDF", "cert_title": "Certificat", "cert_text": "a suivi le cours de l'Académie des interprètes ClayArena sur la terminologie, la technique, les règlements FITASC et l'étiquette du Parcours de Chasse – Sporting™ et du Compak® Sporting.", "cert_note": "Certificat d'autoformation ClayArena ; il ne constitue pas une qualification FITASC.", "question": "Question", "of": "sur", "term_all": "Dans toutes les langues de ClayArena", "term_note_anglicism": "Les tireurs emploient souvent simplement le mot anglais.", "confidence_low": "à confirmer", "reset": "Réinitialiser la progression", "reset_confirm": "Supprimer toute la progression et les XP sur cet appareil ?", "saved_local": "La progression est enregistrée sur cet appareil.", "disclaimer": "Cours ClayArena. Les règlements FITASC sont présentés dans notre propre reformulation, avec des liens vers les pages des règlements ; seul le texte officiel de la FITASC fait foi. Parcours de Chasse – Sporting™ et Compak® Sporting sont des marques de la FITASC.", "language": "Langue", "all_missions_done": "Toutes les missions sont terminées : place à l'examen final !", "decision": "décision", "shot_moment": "tir", "lead_word": "avance", "unit_m": "m", "unit_ft": "ft", "unit_ms": "m/s", "glossary_page": "Page du glossaire", "pair_report": "Doublé coup de fusil (on report) : le 2e plateau part au bruit du 1er coup", "pair_sim": "Doublé simultané : les deux plateaux partent ensemble", "pair_rafale": "Rafale (following pair) : le 2e plateau part du même lanceur dès que celui-ci est réarmé", "no_shot": "Aucun tir.", "at_muzzle": "vu à la bouche du canon", "compare": "Même plateau, quatre méthodes : l'avance réelle est la même, l'avance perçue non", "how_maintained": "Les canons attendent devant le plateau, qui se rapproche. Appuyez sur « Tirer » quand l'écart paraît juste : le fusil suit alors à la vitesse du plateau et garde cette avance.", "how_swing": "Les canons partent derrière le plateau et vont plus vite que lui. Appuyez sur « Tirer » quand les canons passent l'avant du plateau : pendant le délai, le fusil gagne encore du terrain, donc l'avance réelle est plus grande.", "how_pullaway": "Les canons suivent d'abord le plateau, puis accélèrent devant lui. Appuyez sur « Tirer » pendant que le fusil accélère encore : l'avance perçue est plus petite que l'avance réelle.", "how_ambush": "Les canons attendent immobiles en un point devant le plateau. Appuyez sur « Tirer » avant que le plateau n'atteigne ce point : les plombs ont besoin de temps, un tir au moment où le plateau arrive passe derrière.", "stop_gun": "Arrêter le fusil au départ du coup (erreur)", "clay_widths": "largeurs de plateau", "unit_cm": "cm", "unit_in": "po"}, "missions": [{"id": "sport", "icon": "flag", "title": "Le sport en dix minutes", "intro": "Avant de traduire le moindre conseil de moniteur, il vous faut une vue d'ensemble : sur quoi l'on tire vraiment, qui écrit le règlement, à quoi ressemblent un parcours de Parcours de Chasse – Sporting™ et un terrain de Compak® Sporting, et comment se déroule une journée de compétition. Cinq courtes leçons vous donnent la carte ; chaque mission suivante complète les détails.", "lessons": [{"id": "sport-what-is-clay", "minutes": 5, "title": "Des plateaux, pas des oiseaux : en quoi consiste ce sport", "body": ["Le tir sur plateaux d'argile (ball-trap) est un sport dans lequel un tireur casse de petits disques volants avec un fusil. Le disque s'appelle un plateau (target, clay) ; les tireurs anglophones l'appellent souvent « bird » (oiseau), mais personne ne tire sur des animaux vivants. Le règlement FITASC dit clairement que le tir sur des animaux vivants est interdit, et que la sécurité et le respect de l'environnement passent avant tout.", "Une machine appelée lanceur (trap) lance chaque plateau. Son chemin dans l'air (ou au sol) est la trajectoire. Le fusil est un fusil à canon lisse : il tire une cartouche remplie de petits grains appelés plombs, qui s'écartent en un petit nuage, la gerbe. C'est pourquoi le tireur pointe le fusil là où va le plateau, et non là où il se trouve.", "Ce cours porte sur deux disciplines de la fédération internationale FITASC. Le Parcours de Chasse – Sporting™ (en abrégé Sporting™) imite la chasse : les lanceurs sont cachés dans les champs et les bois, et les plateaux volent comme une perdrix, un canard ou un faisan, ou roulent comme un lièvre. Le Compak® Sporting en est la version compacte : la même variété de plateaux, mais sur un seul petit terrain avec cinq pas de tir alignés et six lanceurs.", "Vous entendrez aussi parler de la fosse (Trap) et du Skeet. Ce sont d'autres disciplines, aux trajectoires fixes et répétées ; la fosse olympique et le skeet olympique relèvent d'une autre fédération. Ne mélangez pas leurs règles avec celles du Sporting™ ou du Compak® Sporting.", "Un plateau touché se voit tout de suite : il casse ou au moins un morceau visible s'en détache. Cette clarté rend le sport facile à regarder et, pour vous, facile à suivre dès le premier jour."], "key_points": ["On tire sur des plateaux lancés par des lanceurs, jamais sur des animaux vivants.", "Un fusil tire un nuage de petits plombs (la gerbe), donc le tireur pointe devant le plateau.", "Le Sporting™ imite la chasse en terrain naturel ; le Compak® Sporting en est la version compacte sur un seul terrain.", "La fosse et le skeet sont d'autres disciplines, avec leurs propres règles."], "terms": ["target", "trap", "trajectory", "shotgun", "cartridge", "sporting", "compak-sporting"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Clay pigeon shooting", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch1-definition", "label": "1 · What Sporting™ is"}, {"book": "sporting", "id": "ch1-safety-environment", "label": "1 · Safety, environment and no live animals"}, {"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak® Sporting is"}], "coach_says": [{"en": "Watch this bird off trap B.", "meaning": "« Bird » désigne un plateau, pas un vrai oiseau ; le lanceur B est la machine marquée B.", "say": "Regardez ce plateau du lanceur B."}, {"en": "Today we walk the Sporting course, tomorrow it's Compak.", "meaning": "Deux disciplines différentes, deux jours différents.", "say": "Aujourd'hui, on fait le parcours de Sporting, demain c'est Compak."}, {"en": "Point it, don't aim it.", "meaning": "Un fusil se swingue et se pointe, les deux yeux sur le plateau ; on ne vise pas comme avec une carabine.", "say": "Pointez, ne visez pas."}], "quiz": [{"q": "Un moniteur dit « Watch the next bird. » Qu'allez-vous voir ?", "options": ["Un pigeon vivant lâché d'une boîte", "Un plateau d'argile lancé par un lanceur", "Une cible en papier en forme d'oiseau sur un panneau", "Un drone"], "answer": 1, "why": "« Bird » est l'argot des tireurs pour un plateau ; le règlement FITASC interdit de tirer sur des animaux vivants."}, {"q": "Que tire un fusil de chasse ?", "options": ["Une seule balle", "Une petite fléchette", "Un nuage de petits plombs (la gerbe)", "Une bille remplie de peinture"], "answer": 2, "why": "Les plombs sortent du canon en un petit nuage : le tireur pointe donc devant le plateau en mouvement."}, {"q": "Quelle affirmation sur le Compak® Sporting est exacte ?", "options": ["Une version compacte sur un seul terrain, pas de tir alignés", "C'est la version olympique du skeet", "Il se tire uniquement sur du gibier vivant dans les champs", "Il utilise un seul lanceur et un seul pas de tir"], "answer": 0, "why": "Le Compak® Sporting réunit des plateaux de type Sporting™ sur un petit terrain avec cinq pas de tir et six lanceurs."}]}, {"id": "sport-fitasc", "minutes": 5, "title": "La FITASC, les fédérations et ClayArena", "body": ["La FITASC est la fédération internationale du tir sur plateaux de type chasse. Elle écrit et met à jour les règlements du Parcours de Chasse – Sporting™ et du Compak® Sporting ; les éditions que nous suivons sont datées du 01/01/2025. Compak® Sporting est aussi une marque protégée par la FITASC, c'est pourquoi le nom s'écrit toujours avec ®.", "Le sport est construit comme une pyramide. À la base, les clubs et les stands de tir ; au-dessus, les fédérations nationales, qui sont membres de la FITASC. Les parcours des compétitions nationales sont homologués par la fédération nationale, ceux des compétitions internationales par la FITASC. Une fédération peut confier une épreuve à un club, mais elle reste responsable de l'application du règlement.", "Sur le terrain, le règlement est appliqué par les arbitres. Chaque arbitre détient un diplôme délivré par une fédération nationale, et le chef arbitre doit avoir un diplôme international FITASC. Un jury traite les réclamations, les pénalités et les problèmes techniques lors des épreuves internationales. Vous traduirez pour tous : apprenez donc les titres, arbitre, chef arbitre, jury.", "Il existe aussi d'autres organismes. En Grande-Bretagne et aux États-Unis, des associations nationales gèrent leurs propres versions du sport, comme l'English Sporting, avec d'autres règles et d'autres mots. Un moniteur britannique ou américain peut employer ces mots lors d'une épreuve FITASC ; les missions suivantes vous montrent comment faire.", "ClayArena est la plateforme derrière ce cours. Elle publie des calendriers de compétitions, un glossaire et un résumé en langage clair du règlement FITASC et, avec ClayAway, elle organise des tours d'entraînement. Retenez : seul le texte officiel de la FITASC fait foi ; un résumé est un guide, pas la règle elle-même."], "key_points": ["La FITASC écrit les règlements du Sporting™ et du Compak® Sporting (éditions du 01/01/2025).", "Club, fédération nationale, FITASC : les parcours nationaux sont homologués par la fédération, les internationaux par la FITASC.", "Les arbitres ont un diplôme national ; le chef arbitre a un diplôme international FITASC ; le jury examine les réclamations.", "Seul le texte officiel de la FITASC fait foi ; ClayArena en propose un résumé."], "terms": ["fitasc", "national-federation", "referee", "chief-referee", "jury"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak® Sporting is"}, {"book": "sporting", "id": "ch15-layout-approval", "label": "15 · Who approves layouts"}, {"book": "sporting", "id": "ch15-delegation", "label": "15 · Delegating to a club"}, {"book": "sporting", "id": "ch5-referee-certificate", "label": "5 · Referee certificates"}, {"book": "sporting", "id": "ch15-jury-role", "label": "15 · Duties of the jury"}, {"book": "compak", "id": "ch19-referee-qualification", "label": "19 · Referee approval and qualifications"}], "coach_says": [{"en": "That's a CPSA term — under FITASC it's a simultaneous double.", "meaning": "Le moniteur passe du vocabulaire britannique au nom FITASC.", "say": "C'est un terme de la CPSA : à la FITASC, c'est un doublé simultané."}, {"en": "Ask the chief referee, not the stand referee.", "meaning": "La question s'adresse au responsable principal de la compétition.", "say": "Demandez au chef arbitre, pas à l'arbitre du poste."}, {"en": "The jury will decide this one.", "meaning": "L'affaire dépasse l'arbitre du poste et va devant le jury de la compétition.", "say": "C'est le jury qui tranchera."}], "quiz": [{"q": "Qui homologue les parcours d'une compétition internationale de Sporting™ ?", "options": ["Le club local", "La fédération nationale", "L'arbitre du jour", "La FITASC"], "answer": 3, "why": "Les parcours nationaux sont homologués par la fédération nationale, les internationaux par la FITASC."}, {"q": "Quel diplôme le chef arbitre doit-il détenir ?", "options": ["Un diplôme international FITASC", "Une carte de membre du club, rien de plus", "Un diplôme national de moniteur délivré par son club", "Aucun : n'importe quel tireur expérimenté peut le faire"], "answer": 0, "why": "Les arbitres de poste ont besoin d'un diplôme national ; le chef arbitre a besoin d'un diplôme international de la FITASC."}, {"q": "Lors d'un litige, un client vous montre le résumé du règlement de ClayArena. Quelle est sa valeur ?", "options": ["Il prime sur le texte officiel de la FITASC", "C'est seulement un guide ; c'est le texte FITASC qui fait foi", "Il fait foi, mais seulement en Compak® Sporting", "Il remplace la décision de l'arbitre sur le poste"], "answer": 1, "why": "Un résumé aide à comprendre le règlement, mais l'arbitre et le jury appliquent le texte officiel de la FITASC."}]}, {"id": "sport-sporting-layout", "minutes": 5, "title": "Un terrain de Sporting™ : parcours, postes et lanceurs", "body": ["En Parcours de Chasse – Sporting™, le terrain est divisé en parcours (layouts). Un parcours est un groupe de postes de tir qui donnent ensemble 25 plateaux : 15 simples et 5 doublés. Selon le système, un parcours compte trois, quatre ou cinq postes, chacun avec ses propres lanceurs.", "Le poste de tir (stand) est l'endroit où se tient le tireur : un carré de 1 m ou un cercle de 1 m de diamètre, plan et non glissant. Attention au mot français « stand » : il désigne en général tout le terrain de tir (le stand de tir) ; traduisez donc l'anglais stand par « poste ». Le reste de la planche attend à proximité, assez près pour suivre, mais sans jamais déranger le tireur.", "Les lanceurs sont placés en fonction du terrain, souvent en partie cachés par des buissons ou des arbres, pour que les plateaux ressemblent à du vrai gibier : traversards, rentrants, fuyants, en biais, hauts ou bas, à découvert ou à travers les arbres. Les lanceurs d'un poste sont désignés par les lettres A, B, C, D, lues de gauche à droite depuis le poste.", "Devant chaque poste se trouve un menu : il énumère les lanceurs dans l'ordre de tir et signale les plateaux spéciaux, comme un plateau de 90 mm, 70 mm ou 60 mm, une battue ou un rabbit. Le tireur le lit avant de monter sur le poste, et vous devriez le faire aussi.", "Les trajectoires sont classées par difficulté. Une trajectoire de catégorie A est cassée par un tireur moyen plus de 80 % du temps, la catégorie B de 60 à 80 %, la catégorie C de 40 à 60 %. Un plateau de catégorie C est donc censé être difficile ; un manqué n'y est pas un drame."], "key_points": ["Un parcours donne 25 plateaux : 15 simples et 5 doublés.", "Un poste est un carré de 1 m ou un cercle de 1 m ; traduisez stand par « poste », pas par « stand ».", "Les lanceurs sont désignés A, B, C, D de gauche à droite, vus depuis le poste.", "Le menu indique l'ordre des lanceurs et les éventuels plateaux spéciaux.", "Catégories de difficulté : A plus de 80 %, B 60–80 %, C 40–60 %."], "terms": ["layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "difficulty-class"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}], "coach_says": [{"en": "Layout three is the hard one today — lots of minis in the trees.", "meaning": "Sur le troisième parcours, il y a beaucoup de petits plateaux qui volent à travers les arbres.", "say": "Le parcours trois est le plus dur aujourd'hui : beaucoup de minis dans les arbres."}, {"en": "On this stand, read the menu before you step in.", "meaning": "Vérifiez d'abord l'ordre des lanceurs et les plateaux spéciaux.", "say": "Sur ce poste, lisez le menu avant de monter."}, {"en": "Stand two is a class C target, don't worry about it.", "meaning": "Le plateau est classé difficile ; un manqué est attendu.", "say": "Le poste deux est un plateau de catégorie C, ne vous en faites pas."}], "quiz": [{"q": "Combien de plateaux donne un parcours de Sporting™ ?", "options": ["10", "20", "25", "50"], "answer": 2, "why": "Tous les types de parcours donnent 25 plateaux : 15 simples et 5 doublés."}, {"q": "Un moniteur dit « Go to stand two. » Comment traduisez-vous « stand » ?", "options": ["« stand » (le terrain de tir)", "« poste »", "« tribune »", "« râtelier »"], "answer": 1, "why": "En Sporting™, un stand est la position de tir de 1 m ; le français « stand » désigne en général tout le terrain de tir."}, {"q": "Comment les lanceurs d'un poste de Sporting™ sont-ils identifiés ?", "options": ["Par des numéros de 1 à 6, comptés depuis la droite", "Par des couleurs peintes sur chaque machine", "Par les lettres A, B, C, D de gauche à droite", "Par le nom de la personne qui les déclenche"], "answer": 2, "why": "Les lettres A, B, C, D se lisent de gauche à droite depuis le poste, et le menu comme la feuille de marque les utilisent."}]}, {"id": "sport-compak-layout", "minutes": 5, "title": "Un terrain de Compak® Sporting : cinq pas de tir, six lanceurs", "body": ["Le Compak® Sporting tient sur un seul terrain. Devant les tireurs se trouve un rectangle obligatoire de 35 à 40 m de large et de 25 m de profondeur, délimité par quatre piquets d'angle munis de drapeaux. Par air calme, chaque plateau doit le survoler à un moment donné.", "Cinq pas de tir, chacun un carré de 1 m, sont alignés avec 2 à 5 m entre leurs centres. Ils sont numérotés de 1 à 5 de gauche à droite. Chaque pas de tir a un limiteur d'angle de tir, un cadre en tubes qui empêche le fusil de pivoter trop loin sur le côté ou vers le haut, et empêche le tireur d'avancer.", "Six lanceurs, de A à F de gauche à droite, portent chacun un panneau avec leur lettre. Ils peuvent être devant, sur les côtés, derrière les tireurs ou sur une tour ; un lanceur placé derrière la ligne doit être à au moins 4 m au-dessus d'elle. Chaque Compak comporte trois plateaux obligatoires : un traversard de gauche à droite, un traversard de droite à gauche et un fuyant.", "Une série compte 25 plateaux, cinq à chaque pas de tir. Quand une planche de six tire, cinq tireurs sont sur les pas de tir et le sixième attend derrière le pas de tir 1. Chaque tireur tire à son tour les cinq plateaux du menu de son pas de tir, en commençant par le pas de tir 1. Quand le pas de tir 5 a terminé, ce tireur va attendre derrière le pas de tir 1, tous les autres se décalent d'un pas vers la droite, et le tireur en attente entre au pas de tir 1.", "Certaines épreuves tirent plutôt le Compak® Sporting en ligne : chaque tireur commence au pas de tir 1 et termine au pas de tir 5. Demandez à l'organisateur quel système est utilisé, car la procédure diffère."], "key_points": ["Un rectangle de 35–40 m × 25 m que chaque plateau doit survoler.", "Cinq pas de tir de 1 m alignés, espacés de 2–5 m, chacun avec un limiteur d'angle de tir.", "Six lanceurs désignés de A à F de gauche à droite ; un lanceur derrière la ligne est sur une tour d'au moins 4 m.", "25 plateaux par série, cinq par pas de tir ; la planche se décale d'un pas vers la droite.", "Le Compak® Sporting peut se tirer par planches ou en ligne."], "terms": ["fly-over-rectangle", "firing-angle-limiter", "shooting-stand", "trap", "tower", "rotation", "waiting-position", "line"], "sources": [{"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Everybody move one to the right. Number five, to the waiting position.", "meaning": "La planche tourne ; le tireur du pas de tir 5 passe derrière le pas de tir 1.", "say": "Tout le monde se décale d'un pas vers la droite. Le numéro cinq, en position d'attente."}, {"en": "Trap E is the tower — it comes over your head.", "meaning": "Le plateau du lanceur E est lancé depuis une haute tour et passe au-dessus de la tête.", "say": "Le lanceur E, c'est la tour : il passe au-dessus de votre tête."}, {"en": "Mind the frame — don't swing past the post.", "meaning": "Respectez le limiteur d'angle de tir ; ne faites pas pivoter le fusil au-delà.", "say": "Attention au cadre, ne dépassez pas le montant."}], "quiz": [{"q": "Combien de lanceurs et de pas de tir compte un terrain de Compak® Sporting ?", "options": ["4 lanceurs, 3 pas de tir", "6 lanceurs, 5 pas de tir", "5 lanceurs, 6 pas de tir", "8 lanceurs, 8 pas de tir"], "answer": 1, "why": "Les lanceurs A à F et les pas de tir 1 à 5."}, {"q": "Dans une planche de six, où se trouve le sixième tireur pendant que les autres tirent ?", "options": ["Au club-house", "À côté de l'arbitre au pas de tir 5", "Derrière le lanceur F", "En attente derrière le pas de tir 1"], "answer": 3, "why": "Le tireur en attente se tient derrière le pas de tir 1 et y entre après chaque rotation."}, {"q": "À quoi sert le limiteur d'angle de tir ?", "options": ["Il limite le swing et empêche d'avancer", "Il mesure la vitesse de chaque plateau lancé", "Il contient les cartouches de toute la série", "Il déclenche les plateaux à l'appel du tireur"], "answer": 0, "why": "C'est un cadre de sécurité à chaque pas de tir, qui limite le swing latéral et vertical."}]}, {"id": "sport-competition-day", "minutes": 5, "title": "Une journée de compétition du début à la fin", "body": ["La journée commence à l'inscription : le tireur confirme son engagement, reçoit un dossard et l'épingle en haut du dos, entièrement visible. Ensuite, chacun consulte les listes des planches et les horaires de tir. Respecter l'horaire relève de la responsabilité du tireur lui-même.", "Une planche (squad) est un groupe de six tireurs au maximum, tirés au sort, qui tirent ensemble. Dans ClayAway, le mot anglais squad désigne aussi un sous-groupe d'un tour : précisez donc duquel vous parlez. En Parcours de Chasse – Sporting™, la planche tire d'abord tous les plateaux simples d'un poste, puis les doublés, et l'ordre de tir tourne d'un poste à l'autre. Le premier tireur de la planche voit la présentation des plateaux avant que quiconque ne tire.", "Une série compte 25 plateaux : un parcours en Sporting™, un terrain en Compak® Sporting. Une compétition internationale se tire sur 200 plateaux, soit huit séries sur plusieurs jours. L'arbitre note chaque plateau sur la feuille de marque, généralement X pour un plateau touché et O pour un manqué. Les tireurs vérifient leur score en quittant un poste en Sporting™ et signent la feuille à la fin d'une série de Compak® Sporting.", "Le retard coûte cher. En Sporting™, l'arbitre appelle le nom trois fois en l'espace d'une minute ; un tireur qui manque son tour reçoit des zéros pour les plateaux non tirés. En Compak® Sporting, un tireur qui arrive après que le premier tireur de la planche a appelé reçoit 25 zéros pour la série.", "Si des tireurs sont à égalité pour les trois premières places, il y a un barrage : 25 plateaux, puis la mort subite. Les égalités plus bas sont départagées en remontant les séries, en comparant d'abord la dernière. La journée se termine par le tableau des résultats et la remise des prix."], "key_points": ["Inscription, dossard dans le dos, listes des planches et horaires.", "Une planche compte six tireurs au maximum, tirés au sort ; en Sporting™, d'abord les simples, puis les doublés, avec un ordre qui tourne.", "Une série compte 25 plateaux ; les épreuves internationales, 200 plateaux.", "Le retard coûte des zéros ; en Compak® Sporting, 25 zéros pour la série.", "Égalité pour les trois premières places : barrage de 25, puis mort subite ; égalités plus bas : départage."], "terms": ["entry", "competitor-number", "squad", "round", "rotation", "score-sheet", "shoot-off", "countback", "prize-giving"], "sources": [{"title": "Let's Go Shooting — NSCA beginner's guide to sporting clays", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}], "coach_says": [{"en": "You're in squad twelve, starting on layout five at nine-thirty.", "meaning": "Numéro de planche, parcours de départ et heure de départ.", "say": "Vous êtes dans la planche douze, départ sur le parcours cinq à neuf heures et demie."}, {"en": "Check your card before you leave the stand.", "meaning": "Assurez-vous maintenant que l'arbitre a bien noté votre score ; plus tard, ce sera trop tard.", "say": "Vérifiez votre feuille avant de quitter le poste."}, {"en": "Twenty-two in the first round is fine — seven more to go.", "meaning": "22 sur 25 à la première série ; il reste sept séries dans une épreuve de 200 plateaux.", "say": "Vingt-deux à la première série, c'est bien : encore sept à faire."}, {"en": "Stay close — if it's a tie, you shoot within fifteen minutes of the call.", "meaning": "Un tireur qui risque d'aller en barrage doit être prêt peu après son appel.", "say": "Restez à proximité : en cas d'égalité, vous tirez dans les quinze minutes suivant l'appel."}], "quiz": [{"q": "Sur combien de plateaux se tire une compétition internationale FITASC ?", "options": ["50", "100", "150", "200"], "answer": 3, "why": "200 plateaux, en séries de 25."}, {"q": "En Compak® Sporting par planches, un tireur arrive après que le premier tireur a appelé le premier plateau. Que se passe-t-il ?", "options": ["Rien, il rejoint la planche", "Il reçoit 25 zéros pour cette série", "Il tire la série seul plus tard, sans pénalité", "Il perd un plateau"], "answer": 1, "why": "En Compak® Sporting par planches, une arrivée après le premier appel est sanctionnée de 25 zéros ; un recours auprès du jury est possible pour un motif valable."}, {"q": "Deux tireurs sont à égalité pour la 5e place. Comment sont-ils départagés ?", "options": ["Par un barrage de 25 plateaux", "Par tirage au sort après l'épreuve", "En remontant les séries depuis la dernière", "Par l'âge, le plus jeune en premier"], "answer": 2, "why": "Les barrages ne concernent que les trois premiers ; en dessous, le départage compare la 8e série, puis la 7e, et ainsi de suite."}]}]}, {"id": "gear", "icon": "tool", "title": "Le fusil et l'équipement", "intro": "Les moniteurs parlent du fusil toute la journée : « raise the comb », « check your selector », « change chokes », « nines in the bottom ». Cette mission vous donne les mots pour le fusil, ses pièces, les chokes, les cartouches et les équipements de protection, ainsi que les quelques règles sur le matériel que tout interprète doit connaître.", "lessons": [{"id": "gear-gun-types", "minutes": 5, "title": "Les types de fusil et ce qu'autorise le règlement", "body": ["Tous les fusils que vous verrez sur le poste sont des fusils à canon lisse. Sur presque tous les postes de compétition, il s'agit d'un superposé (over-and-under, O/U) : deux canons l'un au-dessus de l'autre, que l'on ouvre en « cassant » le fusil sur sa charnière. Chaque canon peut recevoir son propre choke, ce qui compte pour les doublés.", "Un juxtaposé (side-by-side) a deux canons côte à côte. C'est le fusil de chasse classique ; il est autorisé, mais rare en compétition. Ne traduisez pas over-and-under simplement par « fusil à deux coups » : ce terme couvre les deux types.", "Un semi-automatique (semi-auto) a un seul canon et se recharge tout seul après chaque coup, en éjectant la douille vide sur le côté. La FITASC l'autorise, sous conditions : pas plus de deux cartouches dans l'arme, la culasse ouverte chaque fois qu'il est porté et, en Compak® Sporting, un dispositif qui empêche les douilles éjectées de toucher le voisin.", "Les fusils à pompe, que l'on recharge en faisant coulisser le devant à la main, sont interdits en Parcours de Chasse – Sporting™ comme en Compak® Sporting. Les règlements énoncent simplement l'interdiction sans en donner la raison : n'en inventez donc pas une quand un client pose la question ; dites simplement que c'est la règle. Le Compak® Sporting interdit aussi les drillings, armes qui combinent canons lisses et canon rayé.", "Deux autres limites s'appliquent dans les deux disciplines : le calibre ne peut pas être supérieur au 12 (le calibre 20 convient donc), et les canons doivent mesurer au moins 66 cm. Les bretelles, les caméras fixées sur l'arme et tout dispositif de visée artificiel sont interdits."], "key_points": ["La plupart des concurrents tirent avec un superposé.", "Semi-automatiques autorisés : deux cartouches au maximum, culasse ouverte pendant le transport, récupérateur de douilles en Compak® Sporting.", "Fusils à pompe interdits dans les deux disciplines ; le règlement ne donne pas de raison.", "Calibre pas supérieur au 12, canons d'au moins 66 cm, ni bretelle ni dispositif de visée."], "terms": ["shotgun", "over-and-under", "side-by-side", "semi-automatic", "pump-action", "gauge", "barrel-length", "shell-catcher"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-semi-auto", "label": "18 · Semi-automatics: shell catcher and two cartridges"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}], "coach_says": [{"en": "Bring your over-and-under and a spare set of chokes.", "meaning": "Le fusil de compétition à deux canons, plus des chokes de rechange.", "say": "Apportez votre superposé et un jeu de chokes de rechange."}, {"en": "With a semi-auto, keep the bolt open until you're on the stand.", "meaning": "Règle de sécurité : un semi-automatique se porte culasse ouverte.", "say": "Avec un semi-auto, gardez la culasse ouverte jusqu'à ce que vous soyez sur le poste."}, {"en": "No pumps on this ground.", "meaning": "Les fusils à pompe ne sont pas acceptés.", "say": "Pas de fusil à pompe sur ce stand."}], "quiz": [{"q": "Quel fusil n'est PAS autorisé en Sporting™ et en Compak® Sporting FITASC ?", "options": ["Un superposé calibre 20", "Un juxtaposé", "Un fusil à pompe", "Un semi-automatique à deux cartouches"], "answer": 2, "why": "Les fusils à pompe sont interdits ; les autres sont autorisés s'ils respectent les limites de calibre et de longueur de canon."}, {"q": "Combien de cartouches un semi-automatique peut-il contenir ?", "options": ["Une", "Deux", "Trois", "Autant que le magasin en contient"], "answer": 1, "why": "Les deux règlements limitent un semi-automatique à deux cartouches."}, {"q": "Un client demande pourquoi les fusils à pompe sont interdits. Quelle est la réponse honnête ?", "options": ["Le règlement énonce l'interdiction sans l'expliquer", "Le règlement dit qu'ils sont trop lents pour les doublés", "Le règlement dit qu'ils sont moins sûrs", "En fait, ils sont autorisés en Compak® Sporting"], "answer": 0, "why": "Les règlements ne donnent aucune raison ; en tant qu'interprète, rapportez la règle et n'inventez pas d'explication."}]}, {"id": "gear-gun-parts", "minutes": 5, "title": "Les pièces du fusil, de l'épaule à la bouche", "body": ["Les moniteurs nomment sans cesse les pièces du fusil : apprenez-les donc d'arrière en avant. La crosse (stock) se place dans l'épaule. Son bord supérieur, où repose la joue, est le busc (comb) ; « raise the comb » ou « drop the comb » (monter ou baisser le busc) concerne la conformation. La partie étroite que tient la main de détente est la poignée (grip), et le tampon en caoutchouc à l'extrémité est la plaque de couche (recoil pad).", "Le centre métallique du fusil est la bascule (receiver, action). Dessus se trouve la clé d'ouverture (top lever) : on la pousse sur le côté et le fusil s'ouvre. Derrière elle se trouve la sûreté (safety catch), souvent combinée au sélecteur (barrel selector, « selector »), qui détermine quel canon part en premier. En dessous se trouve la détente (trigger), dans son pontet.", "Une détente à relâche (release trigger) fait partir le coup quand on la relâche, et non quand on l'appuie. Un tel fusil doit porter, en avertissement, un autocollant avec un grand « R » sur fond fluorescent, sur la face extérieure de la crosse.", "Sous les canons, l'autre main tient le devant (fore-end). Les canons (barrels) ont à l'arrière les chambres pour les cartouches et à l'avant les bouches (muzzles), où se vissent les chokes. Sur le dessus court la bande de visée (rib), avec un guidon (bead) au bout. Le guidon est un repère, pas un organe de visée : « look at the target, not the bead » (regardez le plateau, pas le guidon).", "Deux faux amis : rib ne veut pas dire « côte », et « break the gun » veut dire ouvrir le fusil, pas l'abîmer (comme « casser le fusil » en français). Et une règle de sécurité liée aux pièces : après un raté ou tout autre mauvais fonctionnement de l'arme ou des cartouches, le tireur ne doit pas ouvrir le fusil ni toucher à la sûreté tant que l'arbitre ne l'a pas examiné."], "key_points": ["Crosse, busc, poignée, plaque de couche ; bascule avec clé d'ouverture, sûreté et sélecteur ; détente.", "Devant, canons avec chambres et bouches, bande de visée avec guidon.", "Une détente à relâche impose un autocollant « R » sur la crosse.", "Rib ≠ « côte » ; break the gun = ouvrir (casser) le fusil.", "Après un raté : ne pas ouvrir le fusil ni toucher à la sûreté avant la vérification par l'arbitre."], "terms": ["stock", "comb", "grip", "recoil-pad", "receiver", "top-lever", "safety-catch", "barrel-selector", "trigger", "release-trigger", "fore-end", "barrel", "chamber", "muzzle", "rib", "bead"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-release-trigger-marking", "label": "7 · Release trigger: mandatory 'R' sticker"}, {"book": "compak", "id": "ch18-release-trigger-marking", "label": "18 · Release trigger: the 'R' sticker"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}], "coach_says": [{"en": "You're seeing too much rib — your head is up.", "meaning": "L'œil est trop haut au-dessus de la bande de visée, généralement parce que la tête décolle du busc.", "say": "Vous voyez trop de bande : votre tête est levée."}, {"en": "Check your selector — you fired the top barrel first.", "meaning": "Le sélecteur est réglé à l'envers.", "say": "Vérifiez votre sélecteur : vous avez tiré le canon du dessus en premier."}, {"en": "Break your gun and show me it's clear.", "meaning": "Ouvrez le fusil et montrez les chambres vides.", "say": "Cassez votre fusil et montrez-moi qu'il est vide."}, {"en": "Forget the bead — look at the target.", "meaning": "Concentrez-vous sur le plateau, pas sur le bout du canon.", "say": "Oubliez le guidon, regardez le plateau."}], "quiz": [{"q": "Un moniteur dit « Raise the comb ». De quelle pièce parle-t-il ?", "options": ["Le dessus de la crosse, où repose la joue", "Le petit guidon au bout de la bande de visée", "Le pontet autour de la détente", "Le choke à la bouche du canon"], "answer": 0, "why": "Le busc est le dessus de la crosse ; le monter place l'œil plus haut au-dessus de la bande de visée."}, {"q": "Que doit porter un fusil équipé d'une détente à relâche ?", "options": ["Un canon peint en rouge pour avertir les autres", "Un autocollant avec un grand « R » sur la crosse", "Une seconde sûreté séparée", "Rien : aucun marquage n'est exigé"], "answer": 1, "why": "Les deux règlements exigent l'autocollant d'avertissement « R », sur fond fluorescent, sur la face extérieure de la crosse."}, {"q": "Comment traduisez-vous « Break your gun » ?", "options": ["« Brisez votre fusil »", "« Démontez votre fusil »", "« Ouvrez (cassez) votre fusil »", "« Nettoyez les canons de votre fusil »"], "answer": 2, "why": "Sur un stand de tir, « break » signifie ouvrir le fusil sur sa charnière pour qu'il ne puisse pas tirer."}]}, {"id": "gear-chokes", "minutes": 5, "title": "Les chokes : leur rôle et comment les moniteurs en parlent", "body": ["Un choke (forage, rétreint) est un léger rétrécissement du canon à sa bouche. Il règle la vitesse à laquelle la gerbe s'ouvre. Plus d'étranglement maintient les plombs groupés plus longtemps, ce qui donne une gerbe plus serrée pour les plateaux lointains ; moins d'étranglement l'ouvre plus tôt, ce qui donne une gerbe plus large et plus tolérante pour les plateaux proches.", "La plupart des fusils de compétition ont des chokes interchangeables : de courts tubes vissés dans la bouche avec une clé à choke. Les fusils plus anciens peuvent avoir des chokes fixes, usinés dans le canon. Les chokes de fabricants différents ne sont souvent pas compatibles entre eux, et les fabricants préviennent qu'il ne faut jamais tirer avec un fusil multichoke sans ses chokes.", "Les noms viennent de l'anglais, du plus ouvert au plus serré : cylinder, skeet, improved cylinder, light modified, modified, improved modified, full. En Europe, on les dit souvent en fractions : quart de choke (improved cylinder), demi-choke (modified), trois-quarts de choke (improved modified) et full choke. Beaucoup de fusils italiens marquent les chokes par des étoiles, et là, la règle est inversée : plus il y a d'étoiles, plus le choke est ouvert.", "Les moniteurs disent par exemple « quarter and half » (quart et demi), « open up the bottom barrel » (ouvrez le canon du dessous), « go tighter in the top » (plus serré en haut) ou « change chokes for this stand » (changez de chokes pour ce poste). Gardez les noms exactement comme le moniteur les dit ; ne les convertissez pas en millimètres, qui varient d'un fabricant à l'autre.", "Les règles diffèrent selon les disciplines. En Parcours de Chasse – Sporting™, on peut changer de chokes entre les postes, ou entre les plateaux simples et les doublés, si cela ne cause aucun retard, mais jamais une fois que le tireur est monté sur le poste. En Compak® Sporting, le fusil, les canons et les chokes ne peuvent pas du tout être changés au cours d'une série, seulement entre les séries, sauf après une panne."], "key_points": ["Un choke rétrécit la bouche : plus serré pour les plateaux lointains, plus ouvert pour les proches.", "Les chokes interchangeables se vissent avec une clé à choke ; les fabricants préviennent de ne jamais tirer sans eux.", "Fractions : quart = improved cylinder, demi = modified, trois-quarts = improved modified, full.", "Gardez les noms des chokes tels qu'ils sont dits ; ne les convertissez pas en millimètres.", "Sporting™ : changement entre les postes, jamais sur le poste ; Compak® : aucun changement au cours d'une série."], "terms": ["choke", "multichoke", "fixed-choke", "choke-key", "cylinder", "skeet-choke", "improved-cylinder", "modified", "improved-modified", "full-choke", "pattern"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Beretta — Choke tubes identification", "url": "https://estore.beretta.com/en-gb/utility/choke-tubes-identification"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}], "coach_says": [{"en": "What chokes are you using? — Quarter and half.", "meaning": "Quart de choke dans un canon, demi-choke dans l'autre.", "say": "Quels chokes utilisez-vous ? — Quart et demi."}, {"en": "Put quarter in the bottom and half in the top — the second bird is longer.", "meaning": "Choke plus ouvert pour le premier plateau, plus proche ; plus serré pour le second, plus lointain.", "say": "Mettez le quart en bas et le demi en haut : le second plateau est plus loin."}, {"en": "Open up — these are all close.", "meaning": "Montez des chokes plus ouverts, car les plateaux sont proches.", "say": "Ouvrez : ils sont tous proches."}, {"en": "Check your tubes are tight before the round.", "meaning": "Vérifiez que les chokes ne se sont pas desserrés.", "say": "Vérifiez que vos chokes sont bien serrés avant la série."}], "quiz": [{"q": "Quel choke donne la gerbe la plus large ?", "options": ["Full", "Improved modified", "Modified", "Cylinder"], "answer": 3, "why": "Le cylinder (lisse) n'a aucun étranglement : la gerbe s'ouvre donc le plus tôt."}, {"q": "En Sporting™, un tireur déjà monté sur le poste veut changer un choke. Est-ce autorisé ?", "options": ["Oui, à condition que cela ne cause aucun retard", "Non, plus une fois qu'il est sur le poste", "Oui, mais seulement avant les doublés", "Seulement avec l'autorisation du jury"], "answer": 1, "why": "Les changements sont autorisés entre les postes ou entre simples et doublés, sans retard, mais jamais une fois que le tireur est monté sur le poste."}, {"q": "Sur un fusil italien, un choke à cinq étoiles est…", "options": ["le plus ouvert", "le plus serré", "un choke cassé", "un canon rayé"], "answer": 0, "why": "Avec le marquage par étoiles, plus d'étoiles signifie un choke plus ouvert."}]}, {"id": "gear-cartridges", "minutes": 5, "title": "Les cartouches : calibre, numéro de plomb et limites", "body": ["Une cartouche (cartridge) contient tout ce qu'il faut pour un coup : la douille (hull) avec son culot métallique, l'amorce (primer), la poudre (powder), la bourre (wad) et les plombs (shot). Les tireurs anglophones disent aussi « shell ». Les « empties » sont les douilles tirées.", "Le calibre (gauge) se compte à l'ancienne : plus le nombre est petit, plus l'âme est large, donc le calibre 12 est plus large que le 20. La FITASC autorise des fusils d'un calibre au plus égal à 12, et la plupart des tireurs utilisent le 12. Ne traduisez jamais « 12 gauge » par « 12 mm ».", "Le numéro de plomb fonctionne aussi à l'envers : plus le numéro est grand, plus le plomb est petit, donc le n° 9 est plus fin que le n° 7½. Le même numéro peut désigner des tailles légèrement différentes en Grande-Bretagne, en Europe continentale et aux États-Unis : dites le numéro tel qu'il est donné et vérifiez les millimètres sur la boîte. « Nines » (du 9) et « seven-and-a-halfs » (du 7,5) sont des mots courants chez les moniteurs.", "Les règles du Parcours de Chasse – Sporting™ et du Compak® Sporting sont les mêmes : au maximum 28 g de plombs, avec une tolérance de +2 % ; des plombs ronds de 2,0 à 2,5 mm (±0,1 mm). Les cartouches rechargées, les dispersantes, les mélanges de numéros de plomb, la poudre noire et les traceuses sont interdits. En Sporting™, l'arbitre peut prélever deux cartouches pour contrôle, une dans chaque poche du gilet ; en Compak® Sporting, les coups tirés avec des cartouches non conformes avant un contrôle sont comptés zéro.", "Certains stands ajoutent leurs propres règles environnementales pour l'entraînement, par exemple bourres grasses uniquement ou billes d'acier uniquement : vérifiez le règlement du stand avant le tour. Les douilles vides vont dans la poubelle du poste, et les tireurs au semi-automatique ramassent leurs douilles éjectées en partant."], "key_points": ["Cartouche = douille, amorce, poudre, bourre, plombs.", "Calibre : plus le nombre est petit, plus l'âme est large ; maximum FITASC : calibre 12.", "Numéro de plomb : plus le numéro est grand, plus le plomb est petit ; la numérotation varie selon les pays, vérifiez les millimètres.", "Limites : 28 g de plomb (+2 %), plombs de 2,0–2,5 mm ; ni rechargées, ni mélange de plombs, ni poudre noire, ni traceuses.", "Les douilles vides vont à la poubelle ; les tireurs au semi-auto ramassent leurs douilles."], "terms": ["cartridge", "hull", "primer", "powder", "wad", "shot-size", "load-weight", "gauge", "lead-shot", "steel-shot", "empties"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}, {"book": "compak", "id": "ch18-cartridge-bans", "label": "18 · Prohibited ammunition"}, {"book": "sporting", "id": "ch7-cartridge-check", "label": "7 · Cartridge checks by the referee"}, {"book": "compak", "id": "ch23-noncompliant-equipment", "label": "23 · Shots with non-compliant guns or ammunition"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "compak", "id": "ch18-empty-cases", "label": "18 · Disposing of empty cases"}], "coach_says": [{"en": "Nines for the close stuff, seven-and-a-halfs for the long crossers.", "meaning": "Du plomb fin n° 9 pour les plateaux proches, du n° 7½ plus gros pour les traversards lointains.", "say": "Du 9 pour les plateaux proches, du 7,5 pour les traversards longs."}, {"en": "Maximum twenty-eight grams on this shoot.", "meaning": "La limite de charge de la compétition, comme dans le règlement FITASC.", "say": "Vingt-huit grammes maximum sur ce concours."}, {"en": "Empties in the bin, please, not on the grass.", "meaning": "Mettez les douilles tirées dans le conteneur.", "say": "Les douilles vides à la poubelle, s'il vous plaît, pas dans l'herbe."}, {"en": "Steel only on this ground.", "meaning": "Le plomb n'est pas autorisé sur ce stand (règle locale, pas une règle FITASC).", "say": "Acier uniquement sur ce stand."}], "quiz": [{"q": "Lequel est le plomb le plus fin ?", "options": ["N° 7", "N° 7½", "N° 8", "N° 9"], "answer": 3, "why": "Plus le numéro de plomb est grand, plus le plomb est petit."}, {"q": "Quelle est la charge de plombs maximale selon le règlement FITASC ?", "options": ["24 g, sans tolérance", "28 g, avec une tolérance de +2 %", "32 g pour les plateaux lointains seulement", "Aucune limite, toute charge est autorisée"], "answer": 1, "why": "Les deux disciplines autorisent au maximum 28 g de plombs, +2 %."}, {"q": "Un client dit que son fusil est « 12 gauge ». Qu'est-ce que cela signifie ?", "options": ["Le calibre de l'âme : plus large que le calibre 20", "L'âme mesure 12 millimètres de diamètre", "Douze cartouches tiennent dans le magasin", "Les canons mesurent 12 pouces"], "answer": 0, "why": "Le calibre est une unité ancienne : plus le nombre est petit, plus l'âme est large. Ce ne sont pas des millimètres."}]}, {"id": "gear-protection-clothes", "minutes": 5, "title": "Protections, gilet et code vestimentaire", "body": ["Les protections auditives sont obligatoires pour toute personne sur un parcours ou à proximité : tireurs, arbitres, personnel et spectateurs, et cela vous inclut. Les bouchons d'oreilles (earplugs) comme les casques anti-bruit (ear muffs) conviennent ; un casque électronique amplifie les voix et coupe la détonation, ce qui vous aide à entendre le moniteur et l'arbitre. Un tireur qui se présente au poste sans protection est considéré comme absent.", "Les lunettes de protection (safety glasses) sont obligatoires elles aussi, pour les tireurs, les arbitres et le personnel, et en Parcours de Chasse – Sporting™ pour toute personne proche d'un poste. Les verres existent en différentes teintes (jaune, orange, violet, fumé) pour mieux voir les plateaux selon la lumière.", "Le gilet de tir (shooting vest) contient les cartouches dans deux poches avant et possède une épaulière. Pour le Sporting™, il porte une ligne horizontale de couleur contrastée 25 cm sous l'axe des épaules : avant l'appel, le haut de la crosse doit rester en dessous, et l'arbitre le vérifie. Le Compak® Sporting n'a pas cette ligne, puisque la position du fusil à l'appel est libre.", "Les règles de tenue sont les mêmes dans les deux disciplines : pas de shorts courts (seulement des shorts longs qui s'arrêtent au plus 5 cm au-dessus du genou), des hauts avec au moins des manches courtes, pas de gilet sur un torse nu, et pas de sandales, pour des raisons de sécurité. Le dossard se porte dans le dos, entièrement visible. Un manquement vaut d'abord un avertissement, puis d'autres pénalités.", "Beaucoup de tireurs portent aussi une casquette à visière contre le soleil et la pluie, des gants, et emportent un sac à cartouches pour la provision de la journée. Ce sont des usages, pas des règles."], "key_points": ["Protections auditives obligatoires pour tous près d'un parcours, interprètes compris.", "Lunettes de protection obligatoires ; sans protections, un tireur est considéré comme absent.", "Gilet en Sporting™ : ligne contrastée 25 cm sous l'axe des épaules ; le Compak® n'en a pas.", "Tenue : shorts pas plus haut que 5 cm au-dessus du genou, manches, pas de torse nu sous le gilet, pas de sandales.", "Dossard dans le dos, entièrement visible."], "terms": ["hearing-protection", "earplugs", "electronic-ear-muffs", "safety-glasses", "shooting-vest", "jacket-line", "dress-code", "competitor-number", "cartridge-bag"], "sources": [], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}], "coach_says": [{"en": "Ears and eyes on before you walk up.", "meaning": "Mettez les protections auditives et les lunettes avant de vous approcher du poste.", "say": "Casque et lunettes avant de monter."}, {"en": "Butt under the tape until you see the target.", "meaning": "Règle du fusil bas en Sporting™ : la crosse reste sous la ligne du gilet jusqu'à l'apparition du plateau.", "say": "La crosse sous la bande jusqu'à ce que vous voyiez le plateau."}, {"en": "No marker needed here — it's Compak.", "meaning": "Le Compak® n'impose pas de ligne sur le gilet.", "say": "Pas besoin de repère ici, c'est du Compak."}], "quiz": [{"q": "Vous êtes interprète et vous vous tenez près du poste. Devez-vous porter des protections auditives ?", "options": ["Non, seulement les tireurs sur le poste", "Seulement pendant les finales et les barrages", "Oui, toute personne sur un parcours ou à proximité", "Seulement si l'arbitre vous le demande"], "answer": 2, "why": "Les protections auditives sont obligatoires pour les tireurs, les arbitres, le personnel et les spectateurs."}, {"q": "Où se trouve la ligne du gilet en Sporting™ ?", "options": ["25 cm sous l'axe des épaules", "À la taille, au niveau de la ceinture", "Sur la manche du bras de tir", "Il n'y en a pas en Sporting™"], "answer": 0, "why": "La ligne contrastée se trouve 25 cm sous l'axe des épaules, parallèlement à lui ; la crosse doit rester en dessous avant l'apparition du plateau."}, {"q": "Quelles chaussures sont interdites dans les deux disciplines ?", "options": ["Les chaussures de trail", "Les sandales", "Les bottes", "Les baskets"], "answer": 1, "why": "Les sandales sont interdites pour des raisons de sécurité."}]}]}, {"id": "targets", "icon": "target", "title": "Les plateaux", "intro": "Un moniteur qui dit « it's a midi off the tower, then a rabbit on report » suppose que vous voyez la scène. Cette mission vous apprend les types de plateaux, comment la couleur et la lumière changent ce que voit le tireur, comment les lanceurs libèrent les plateaux, comment lire un menu, et la seule question de comptage qui décide de tout : bon ou perdu.", "lessons": [{"id": "targets-types", "minutes": 5, "title": "Types de plateaux : normal, midi, mini, battue, rabbit, flash, ZZ", "body": ["La liste FITASC du Parcours de Chasse – Sporting™ cite sept types de plateaux : normal (standard), midi, super mini, battue, rabbit, flash et ZZ. Le Compak® Sporting autorise tout plateau normal ou spécial, et sa liste cite aussi le rocket. Chaque type vole différemment.", "Le plateau normal, le plus courant, est un dôme d'environ 108–110 mm de diamètre. Le midi fait 90 mm : il garde bien sa vitesse et paraît plus loin qu'il ne l'est. Le mini fait 60 mm : il sort vite du lanceur et ralentit rapidement, si bien que les tireurs ont tendance à lui donner trop d'avance. La liste du Sporting™ appelle le petit plateau « super mini », et la règle sur le menu cite à la fois les tailles de 70 mm et de 60 mm ; les noms ne sont pas employés de façon cohérente, fiez-vous donc toujours aux millimètres inscrits sur le menu.", "La battue est un plateau plat et mince de 110 mm. Elle vole par la tranche, presque invisible, puis se retourne pour montrer sa face et tombe rapidement. Le rabbit est un plateau de 110 mm au bord épais et résistant, lancé sur sa tranche le long du sol ; il rebondit et peut sauter sur les bosses. En français, on dit « rabbit », plus rarement « lapin » ; ce cours emploie « rabbit ».", "Un plateau flash est rempli de poudre colorée qui laisse un nuage vif quand il est touché ; il se compte comme n'importe quel autre plateau. Un plateau ZZ, aussi appelé hélice, est une hélice en plastique avec un témoin central blanc, qui vole de façon imprévisible. Le rocket est un plateau spécial cité uniquement dans la liste du Compak® Sporting ; nous n'en donnons pas les caractéristiques.", "En Sporting™, un plateau d'une couleur, d'une taille ou d'un type erroné est un No bird et il est répété."], "key_points": ["Liste du Sporting™ : normal, midi, super mini, battue, rabbit, flash, ZZ ; le Compak® autorise tout type, rocket compris.", "Normal environ 108–110 mm, midi 90 mm, mini 60 mm ; le menu peut aussi indiquer 70 mm : fiez-vous aux millimètres.", "Battue : plate, vole par la tranche, se retourne et tombe ; rabbit : bord épais, roule et saute.", "Le flash laisse un nuage de poudre ; le ZZ est un plateau hélice.", "Sporting™ : couleur, taille ou type erroné = No bird."], "terms": ["standard-target", "midi", "mini", "super-mini", "battue", "rabbit", "flash-target", "zz-target", "rocket-target", "no-bird"], "sources": [{"title": "Shooting UK — Clay pigeon sizes: knowing what they are will help you improve your score", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}, {"title": "Let's Go Shooting — Types of clay targets", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/types-of-clay-targets/"}, {"title": "GUNS Magazine — Helice", "url": "https://gunsmagazine.com/discover/helice/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}], "coach_says": [{"en": "The midi looks far but it isn't — don't give it too much.", "meaning": "Un plateau de 90 mm paraît plus loin qu'il ne l'est : il demande donc moins d'avance que ne le pense le tireur.", "say": "Le midi paraît loin, mais il ne l'est pas : ne lui en donnez pas trop."}, {"en": "The battue will turn and drop at the end — take it when it shows its belly.", "meaning": "Tirez la battue une fois qu'elle tourne sa face plate vers vous.", "say": "La battue va se retourner et tomber à la fin : prenez-la quand elle montre son ventre."}, {"en": "The mini is dying fast — shoot it early.", "meaning": "Le petit plateau perd vite sa vitesse ; n'attendez pas.", "say": "Le mini meurt vite : tirez-le tôt."}, {"en": "The rabbit will hop on that bump — stay under it.", "meaning": "Gardez les canons bas sur le plateau qui roule, pour qu'un saut rencontre quand même la gerbe.", "say": "Le rabbit va sauter sur cette bosse : restez dessous."}], "quiz": [{"q": "Quel plateau roule sur le sol ?", "options": ["Le midi", "La battue", "Le rabbit", "Le flash"], "answer": 2, "why": "Le rabbit a un bord épais et il est lancé sur sa tranche le long du sol."}, {"q": "Le menu indique « 70 mm ». Le moniteur l'appelle un mini. Que devez-vous traduire ?", "options": ["Corriger en 60 mm, puisqu'un mini fait 60 mm", "Garder le mot du moniteur et les 70 mm du menu", "L'appeler midi, puisqu'il dépasse 60 mm", "Demander au moniteur de dire plutôt « super mini »"], "answer": 1, "why": "Le règlement cite les tailles de 70 mm et 60 mm et le nom « super mini » ; fiez-vous aux millimètres du menu et ne corrigez pas le moniteur."}, {"q": "Sur un poste de Sporting™, un lanceur envoie un midi au lieu du plateau normal indiqué sur le menu. Que se passe-t-il ?", "options": ["No bird, le plateau est répété", "Il compte comme bon", "Le tireur perd le plateau", "La série est annulée"], "answer": 0, "why": "En Sporting™, un plateau d'une couleur, d'une taille ou d'un type erroné est un No bird et il est répété."}]}, {"id": "targets-colours-visibility", "minutes": 5, "title": "Couleurs, lumière et visibilité", "body": ["Les deux règlements demandent la même chose : la couleur d'un plateau doit se détacher nettement sur le fond. Les plateaux bicolores sont déconseillés. La couleur est donc un choix du traceur de parcours, fait pour chaque trajectoire, et non un type de plateau à part.", "Vous entendrez parler de plateaux noirs, orange, blancs, jaunes et roses. Beaucoup de traceurs utilisent le noir sur fond de ciel et l'orange devant les arbres et l'herbe. Un plateau « blazed » a un dôme peint en orange vif. Attention : quand un moniteur dit « the orange one » (l'orange), il parle d'une couleur, pas d'une taille. Un midi noir et un plateau normal orange peuvent venir du même poste.", "Si un plateau de la mauvaise couleur est lancé, l'arbitre annonce No bird et il est répété. En Compak® Sporting, le règlement ajoute que le mauvais temps n'est jamais un motif de No bird : un plateau cassé compte et un plateau manqué est perdu, quelles que soient les conditions. En Parcours de Chasse – Sporting™, l'arbitre peut interrompre le tir pour un orage ou une averse brefs et violents.", "La lumière change tout. Les moniteurs parlent de contre-jour (le soleil derrière le plateau), de lumière plate par temps gris, d'ombres sous les arbres et du fond derrière le plateau : ciel, lisière ou sol. Un plateau peut « disparaître » devant des arbres sombres et « ressortir » sur le ciel. C'est pourquoi les tireurs changent de teinte de verres au cours de la journée.", "Quand vous traduisez, gardez les mots de couleur et de lumière exacts et courts : « it's coming out of the dark trees » (il sort des arbres sombres), « you lose it in the sun » (vous le perdez dans le soleil). Ils expliquent pourquoi un tireur a manqué : ils comptent donc."], "key_points": ["La couleur d'un plateau doit se détacher sur le fond ; les plateaux bicolores sont déconseillés.", "La couleur n'est pas un type : « the orange one » est une couleur, pas une taille.", "Mauvaise couleur = No bird.", "Compak® : le mauvais temps ne justifie jamais un No bird ; en Sporting™, l'arbitre peut interrompre pour un bref orage.", "Contre-jour, lumière plate, fond : traduisez exactement les mots de la lumière."], "terms": ["target", "no-bird", "blazed-target", "background"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch20-bad-weather", "label": "20 · No NO BIRD for bad weather"}, {"book": "sporting", "id": "ch5-weather-interruption", "label": "5 · Interrupting shooting for bad weather"}], "coach_says": [{"en": "The black one is the midi, the orange one is the standard — don't mix them up.", "meaning": "Deux plateaux du poste diffèrent par la couleur et la taille.", "say": "Le noir, c'est le midi, l'orange, c'est le normal : ne les confondez pas."}, {"en": "You lose it against the trees — pick it up later, in the sky.", "meaning": "Le plateau est difficile à voir devant les arbres ; commencez à le regarder là où le ciel est derrière lui.", "say": "Vous le perdez devant les arbres : prenez-le plus tard, dans le ciel."}, {"en": "Flat light today — put the yellow lens in.", "meaning": "Lumière grise, sans contraste ; un verre jaune améliore le contraste.", "say": "Lumière plate aujourd'hui : mettez le verre jaune."}], "quiz": [{"q": "Qu'exige le règlement de la couleur d'un plateau ?", "options": ["Elle doit toujours être orange", "Elle doit se détacher nettement sur le fond", "Le plateau doit être bicolore", "N'importe quelle couleur : le règlement ne dit rien"], "answer": 1, "why": "L'exigence est la visibilité sur le fond ; les plateaux bicolores sont déconseillés."}, {"q": "En Compak® Sporting, il se met à pleuvoir fort et un tireur manque. Peut-il demander un No bird à cause du temps ?", "options": ["Oui, le temps justifie toujours un No bird", "Seulement pour le premier plateau d'un doublé", "Seulement si le jury est d'accord", "Non, le temps ne justifie jamais un No bird"], "answer": 3, "why": "Le règlement du Compak® Sporting précise que le temps n'est jamais un motif de No bird."}, {"q": "Un moniteur dit « Watch the orange one. » Que décrit-il ?", "options": ["La couleur d'un plateau", "Une taille de plateau de 90 mm", "Un rabbit", "Un plateau cassé"], "answer": 0, "why": "La couleur est choisie pour la visibilité et ne dit rien de la taille ni du type."}]}, {"id": "targets-traps", "minutes": 5, "title": "Les lanceurs, le déclenchement et le pulleur", "body": ["Un lanceur (trap) est la machine qui lance les plateaux. Les lanceurs peuvent être manuels ou automatiques (le règlement du Compak® Sporting cite aussi les semi-automatiques). En Parcours de Chasse – Sporting™, les lanceurs d'un poste sont désignés par les lettres A, B, C, D de gauche à droite, vus depuis le poste ; en Compak® Sporting, les six lanceurs vont de A à F, chacun avec un panneau portant sa lettre. Gardez les lettres latines en traduisant : le menu les utilise.", "Le tireur déclenche le plateau par un appel : le règlement cite « pull » ou « prêt », même si, dans la pratique, les mots d'appel des tireurs varient. En Sporting™, l'arbitre transmet l'ordre au pulleur (la personne qui actionne le déclenchement) par un signal sonore, et le plateau doit partir dans les trois secondes. Ne traduisez pas l'appel lui-même : c'est un ordre pour la machine, pas une phrase.", "En Compak® Sporting, les plateaux peuvent être déclenchés à la main, par télécommande ou par un sonopull à commande vocale. En déclenchement manuel, le plateau part de 0 à 3 secondes après l'appel ; un sonopull a un délai fixe de 0,5 seconde. Le Compak® Sporting international en ligne utilise uniquement le sonopull, avec arbitrage électronique.", "Un déclenchement à la voix comporte un microphone au pas de tir. Votre propre voix peut le déclencher. Sur un tel poste, ne parlez jamais à voix haute pendant que le tireur est prêt : chuchotez entre les plateaux ou reculez.", "Les erreurs de lancer sont des No bird : un plateau lancé plus de trois secondes après l'appel, un plateau venant du mauvais lanceur, un plateau lancé sans appel, deux plateaux venant de lanceurs du même poste en Sporting™, ou un plateau lancé par erreur par une machine du même Compak."], "key_points": ["Lanceurs : A–D par poste de Sporting™, A–F sur un terrain de Compak® ; gardez les lettres latines.", "L'appel (« pull », « prêt ») déclenche le plateau ; ne le traduisez pas.", "Sporting™ : l'arbitre fait signe au pulleur ; plateau dans les 3 secondes.", "Compak® : manuel 0–3 s, télécommande ou sonopull avec délai fixe de 0,5 s.", "Plateaux tardifs, du mauvais lanceur ou non appelés = No bird ; un microphone peut vous entendre."], "terms": ["trap", "trapper", "call", "sonopull", "manual-release", "tower", "no-bird"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch16-terms", "label": "16 · Other basic terms"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Trap B is throwing lower than in the showing — tell the referee.", "meaning": "La trajectoire de la machine a changé ; le tireur doit le signaler avant de tirer.", "say": "Le lanceur B lance plus bas qu'à la présentation : dites-le à l'arbitre."}, {"en": "It's voice release here — don't chat on the stand.", "meaning": "Un microphone déclenche les plateaux ; parler peut en lancer un.", "say": "Ici, c'est un déclenchement à la voix : on ne bavarde pas sur le poste."}, {"en": "The trapper was late on that one — that's a no bird.", "meaning": "Le plateau est parti plus de trois secondes après l'appel.", "say": "Le pulleur était en retard sur celui-là : c'est un No bird."}], "quiz": [{"q": "En Sporting™, combien de temps le plateau peut-il mettre à partir après le signal de l'arbitre ?", "options": ["Jusqu'à 1 seconde", "Jusqu'à 3 secondes", "Jusqu'à 10 secondes", "N'importe quand"], "answer": 1, "why": "Un plateau lancé plus de trois secondes après est un No bird."}, {"q": "Quel est le délai fixe d'un sonopull en Compak® ?", "options": ["0 seconde", "3 secondes", "0,5 seconde", "Il est réglé par chaque tireur"], "answer": 2, "why": "Le sonopull doit appliquer un délai fixe et non modifiable de 0,5 seconde."}, {"q": "Vous êtes sur un poste à déclenchement vocal et le tireur est prêt. Que faites-vous ?", "options": ["Je traduis fort pour qu'il m'entende", "Je demande au pulleur d'attendre un instant", "Je répète le mot d'appel pour lui", "Je reste silencieux ; je ne chuchote qu'entre les plateaux"], "answer": 3, "why": "Votre voix peut déclencher le microphone et lancer un plateau que personne n'a appelé."}]}, {"id": "targets-menu", "minutes": 5, "title": "Lire le menu du poste", "body": ["Le menu (target menu) est le panneau du poste qui indique au tireur ce qui l'attend. Les tireurs disent vraiment « menu » : gardez ce mot.", "En Parcours de Chasse – Sporting™, le menu énumère les lanceurs dans l'ordre de tir et doit indiquer les plateaux spéciaux : 90 mm, 70 mm, 60 mm, battue ou rabbit. Les arbitres vérifient au préalable que les machines correspondent au menu. Un parcours donne 15 simples et 5 doublés, et les doublés ne peuvent utiliser que des plateaux déjà présentés en simples depuis le même poste. La planche tire d'abord les simples, puis les doublés.", "Un doublé est indiqué avec son type : coup de fusil (le second plateau part au bruit du premier coup), simultané (les deux ensemble) ou rafale (deux plateaux du même lanceur, l'un après l'autre ; uniquement en Sporting™). Les menus diffèrent d'un stand à l'autre : lisez donc les mots, pas seulement les lettres. Exemple pour un poste à trois lanceurs : simples A, B, C ; doublés A + B simultané et C + C rafale (sur un tel poste, deux doublés coup de fusil ne sont pas autorisés).", "En Compak® Sporting, un menu est affiché à chacun des cinq pas de tir. Chaque pas de tir compte cinq plateaux : cinq simples, trois simples et un doublé, ou un simple et deux doublés. Le type de doublé est le même aux cinq pas de tir d'un Compak, et le premier plateau de chaque doublé est le dernier plateau du pas de tir précédent. La FITASC propose 40 menus prêts à l'emploi pour les compétitions.", "Avant que votre tireur ne monte, lisez-lui le menu à voix haute dans sa langue, lettre par lettre : « A, puis F, puis B, puis le doublé C et E au coup de fusil. »"], "key_points": ["Gardez le mot « menu ».", "Menu du Sporting™ : lanceurs dans l'ordre plus plateaux spéciaux (90, 70, 60 mm, battue, rabbit).", "15 simples + 5 doublés ; les doublés utilisent des plateaux déjà présentés en simples ; les simples d'abord.", "Doublés : coup de fusil, simultané, rafale (uniquement en Sporting™).", "Compak® : cinq plateaux par pas de tir, même type de doublé partout, chaque doublé commence par le dernier plateau du pas de tir précédent."], "terms": ["target-menu", "single-target", "double", "double-on-report", "simultaneous-double", "rafale-double"], "sources": [{"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch2-doubles-three-traps", "label": "2 · Doubles at a position with 3 machines"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-annex3-tables", "label": "17 · The 40 pre-established trajectory setting tables"}], "coach_says": [{"en": "Read the menu: on station three you have A, then F, then B, then the pair C and E on report.", "meaning": "Pas de tir 3 : trois plateaux simples, puis un doublé au coup de fusil ; cinq plateaux en tout.", "say": "Lisez le menu : au pas de tir trois, vous avez A, puis F, puis B, puis le doublé C et E au coup de fusil."}, {"en": "Same traps, new menu — don't shoot from memory.", "meaning": "L'ordre a changé depuis la dernière série.", "say": "Mêmes lanceurs, nouveau menu : ne tirez pas de mémoire."}, {"en": "Three singles, then a simo pair.", "meaning": "« Simo » est l'abréviation de doublé simultané.", "say": "Trois simples, puis un doublé simultané."}], "quiz": [{"q": "Quels plateaux spéciaux un menu de Sporting™ doit-il indiquer ?", "options": ["Seulement les couleurs des plateaux", "90 mm, 70 mm, 60 mm, battue ou rabbit", "Seulement les rabbits et les battues", "Aucun ; l'arbitre les annonce"], "answer": 1, "why": "Le menu doit énumérer les lanceurs dans l'ordre et tous les types de plateaux spéciaux."}, {"q": "En Compak® Sporting, par quel plateau commence chaque doublé ?", "options": ["Toujours le lanceur A", "Un plateau jamais vu auparavant", "Le dernier plateau tiré au pas de tir précédent", "N'importe quel plateau choisi par le tireur"], "answer": 2, "why": "Les doublés s'enchaînent d'un pas de tir à l'autre : chacun commence par le dernier plateau du pas de tir précédent."}, {"q": "Quel type de doublé n'existe qu'en Sporting™ ?", "options": ["La rafale", "Le coup de fusil", "Le simultané", "Aucun"], "answer": 0, "why": "Les doublés de Compak® sont coup de fusil ou simultanés ; la rafale est un doublé du Sporting™."}]}, {"id": "targets-hit-or-lost", "minutes": 5, "title": "Bon ou perdu : le morceau visible et le piège de la « fumée »", "body": ["Un plateau est compté « bon » (one, touché) quand il a été lancé régulièrement, que le tireur a tiré conformément au règlement, et qu'au moins un morceau visible s'en est détaché, ou que le plateau a été totalement ou partiellement détruit. Les plateaux flash suivent la même règle. Un plateau est « zéro » (perdu) quand aucun morceau visible ne s'en détache et qu'il n'y a que de la poussière ou de la fumée.", "La règle repose donc sur une seule image : un morceau visible. Un petit éclat qui s'envole compte comme bon. Un nuage de poussière avec un plateau qui continue sa course entier est perdu. Sur la feuille de marque, un plateau touché est généralement noté X et un manqué O.", "Seul l'arbitre décide. Les membres de la planche ne peuvent pas donner leur avis, et personne ne peut ramasser un plateau pour le vérifier. En Compak® Sporting, l'arbitre annonce chaque zéro à voix haute ou par un signal sonore. En Parcours de Chasse – Sporting™, le tireur doit casser les plateaux là où l'arbitre peut les voir. En appelant le plateau suivant, le tireur accepte la décision sur le précédent : toute objection doit donc venir immédiatement.", "Voici maintenant le piège pour les interprètes. Les moniteurs félicitent un tir parfait par « smoked it », « inked it » ou « powdered it » (pulvérisé) : le plateau s'est transformé en nuage noir. C'est le meilleur tir possible, pas un zéro. Mais dans le règlement, « seulement de la poussière ou de la fumée » signifie perdu. « Dusted it » est risqué : cela veut généralement dire qu'il ne s'est dégagé que de la poussière, donc un plateau perdu, mais certains l'emploient comme compliment. En cas de doute, demandez, car les deux sens sont opposés.", "De plus : « dead » signifie un plateau touché (pas « mort »), « lost » un manqué (pas « égaré »)."], "key_points": ["Bon = au moins un morceau visible s'est détaché, ou le plateau a été totalement ou partiellement détruit.", "Zéro = aucun morceau visible, seulement de la poussière ou de la fumée.", "Seul l'arbitre décide ; on ne ramasse pas les plateaux ; appeler le plateau suivant vaut acceptation de la décision.", "Argot du moniteur « smoked it » = tir parfait ; formulation du règlement « seulement de la fumée » = perdu.", "« Dead » = bon, « lost » = manqué ; demandez si « dusted » n'est pas clair."], "terms": ["one", "zero", "visible-piece", "referee", "score-sheet", "smoked-it", "chip"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "Smoked it! That's the picture.", "meaning": "Un tir parfait : le plateau est réduit en poussière ; le tireur doit retenir cette image.", "say": "Pulvérisé ! C'est cette image-là."}, {"en": "Dead — only a chip, but it counts.", "meaning": "Un petit morceau visible s'est détaché : c'est donc bon.", "say": "Bon : juste un éclat, mais il compte."}, {"en": "Lost — you were just behind it.", "meaning": "Un manqué ; la gerbe est passée derrière le plateau.", "say": "Zéro : vous étiez juste derrière."}, {"en": "Don't argue with me later — say it now, before you call.", "meaning": "Une objection doit se faire immédiatement ; appeler le plateau suivant vaut acceptation de la décision.", "say": "Ne venez pas discuter plus tard : dites-le maintenant, avant d'appeler."}], "quiz": [{"q": "Le plateau continue sa course entier, mais un nuage de poussière apparaît. Quel est le résultat ?", "options": ["Zéro (perdu)", "Bon (touché)", "No bird", "Un demi-point"], "answer": 0, "why": "Seulement de la poussière ou de la fumée, sans morceau visible : le plateau est perdu."}, {"q": "Un moniteur crie « Smoked it! ». Comment en traduisez-vous le sens ?", "options": ["Il a seulement fumé, donc le plateau est perdu", "Les canons surchauffent", "Un tir parfait : le plateau a été réduit en poussière", "Le lanceur est en feu"], "answer": 2, "why": "Dans l'argot des moniteurs, « smoked it » félicite une casse totale ; la formulation du règlement « seulement de la fumée » signifie le contraire."}, {"q": "Un membre de la planche affirme que le dernier plateau était touché. Qui décide ?", "options": ["Un vote de la planche", "Le moniteur", "L'interprète", "L'arbitre seul"], "answer": 3, "why": "Les décisions sur les plateaux appartiennent à l'arbitre ; les membres de la planche ne peuvent pas intervenir."}]}]}, {"id": "flight", "icon": "trajectory", "title": "Comment volent les plateaux (présentations)", "intro": "Les moniteurs nomment chaque plateau d'après sa façon de voler : crosser, incomer, teal, looper, rabbit, report pair. En six courtes leçons, vous apprendrez ce que signifie chaque nom, ce que le tireur doit en faire et quels mots sont faciles à mal traduire.", "lessons": [{"id": "flight-crosser", "minutes": 5, "title": "Le traversard : un plateau qui traverse", "body": ["Un traversard (crosser) vole en travers devant le tireur, à peu près à angle droit par rapport à sa ligne de visée : de gauche à droite (noté G→D, en anglais L→R) ou de droite à gauche (D→G, R→L). Sur un parcours de Parcours de Chasse – Sporting™, le règlement demande un mélange de plateaux traversards, en biais, rentrants et fuyants. En Compak® Sporting, un traversard de gauche à droite et un traversard de droite à gauche font partie des trois trajectoires obligatoires : tout Compak en comporte donc.", "Un traversard vous montre toute sa vitesse latérale : c'est donc la présentation qui demande le plus d'avance, et plus il est loin, plus il en faut. Un « long crosser » est un traversard lointain, pas un plateau qui vole longtemps.", "Lisez sa ligne et sa vitesse : vole-t-il à plat, monte-t-il, ou descend-il déjà au point de casse ? Montre-t-il sa face (le dôme ou le dessous) ou seulement sa tranche ? Ralentit-il ? Un traversard qui ralentit demande moins d'avance qu'un traversard à pleine vitesse.", "Plan type : les pieds orientés vers le point de casse, les yeux qui le prennent tôt, puis pull-away ou avance maintenue, avec le fusil toujours en mouvement au moment du tir. Le verdict le plus courant d'un moniteur sur un traversard est « behind » (derrière) : pas assez d'avance, ou un fusil qui s'est arrêté.", "Les directions se donnent du point de vue du tireur. Si vous êtes face au tireur, sa « gauche à droite » est votre droite à gauche : n'inversez donc jamais les mots."], "key_points": ["Un traversard vole en travers, à environ 90° de la ligne de visée : G→D ou D→G.", "Il demande le plus d'avance ; plus de distance = plus d'avance.", "« Long crosser » = lointain, pas qui dure longtemps.", "Le Compak® Sporting a toujours un traversard G→D et un traversard D→G.", "Gauche et droite se disent toujours du point de vue du tireur."], "terms": ["crosser", "lead", "trajectory", "target-line", "break-point", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["crosser-rl"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}], "coach_says": [{"en": "Long crosser, right to left — trust the lead and keep the gun moving.", "meaning": "Le plateau est lointain et vole de la droite vers la gauche du tireur ; donnez-lui l'avance prévue et n'arrêtez pas le swing.", "say": "Traversard long, de droite à gauche : faites confiance à l'avance et gardez le fusil en mouvement."}, {"en": "You're behind it — give it more.", "meaning": "La gerbe est passée derrière le plateau : il faut plus d'avance.", "say": "Vous êtes derrière, donnez-lui plus."}, {"en": "It's dropping at your break point — stay under the line.", "meaning": "À l'endroit où le tireur le casse, le traversard descend déjà : le fusil doit passer légèrement sous sa trajectoire.", "say": "Il descend à votre point de casse : restez sous la ligne."}, {"en": "Pick it up early, it's quick off the trap.", "meaning": "Cherchez le plateau plus près du lanceur que d'habitude, car il sort vite du lanceur.", "say": "Prenez-le tôt, il sort vite du lanceur."}], "quiz": [{"q": "Quelle présentation demande en général le plus d'avance ?", "options": ["Un plateau qui s'éloigne tout droit", "Un rentrant qui vient droit sur le tireur", "Un traversard à la même distance", "Un rabbit qui roule tout droit en s'éloignant"], "answer": 2, "why": "Un traversard montre toute sa vitesse latérale : le fusil doit donc être le plus loin devant ; les plateaux en ligne droite demandent peu d'avance latérale."}, {"q": "Le moniteur dit « long crosser ». Que signifie « long » ?", "options": ["Le plateau est loin", "Le plateau vole longtemps", "Le plateau est long et ovale", "Le tireur doit attendre longtemps"], "answer": 0, "why": "Chez les moniteurs, « long » décrit la distance. Un long crosser est un traversard lointain, qui demande plus d'avance."}, {"q": "Qu'est-ce qui est vrai des traversards en Compak® Sporting ?", "options": ["Les traversards sont interdits sur un Compak", "Seuls les traversards de droite à gauche sont autorisés", "Les traversards ne peuvent être lancés qu'en rabbit", "Un traversard G→D et un traversard D→G sont obligatoires"], "answer": 3, "why": "Le règlement du Compak® Sporting rend trois trajectoires obligatoires : un traversard G→D, un traversard D→G et un fuyant."}]}, {"id": "flight-incomer-going-away", "minutes": 5, "title": "Rentrant, fuyant, plateau de tête et plateau par-dessus", "body": ["Un rentrant (incomer) vole vers le tireur, souvent depuis un lanceur éloigné ou une tour, et descend généralement en approchant. Il peut sembler ralentir et rester suspendu, ce qui pousse le tireur à viser. On le prend normalement devant, avant qu'il n'arrive au-dessus de la tête, et les canons peuvent masquer (« blot out ») le plateau au moment du tir. C'est voulu, ce n'est pas une faute.", "Un fuyant (going-away) part de près du tireur ou de derrière lui et s'éloigne. Il demande peu d'avance latérale, mais il rapetisse vite et monte ou descend souvent : l'avance est donc surtout verticale et le timing compte, il ne faut pas attendre. En Compak® Sporting, un fuyant au-dessus du côté BC est obligatoire ; il peut venir d'une fosse devant ou d'une tour derrière les pas de tir, à au moins 4 m au-dessus d'eux.", "Un plateau de tête (driven target) est un rentrant qui passe au-dessus de la tête du tireur, comme un faisan poussé par les rabatteurs. Prenez-le tôt, accompagnez-le, remontez depuis l'arrière en le traversant, tirez quand les canons le masquent et continuez le swing. Attention : en français, « en battue » (en italien « in battuta ») désigne le gibier rabattu, pas le plateau battue.", "Un plateau par-dessus venant de derrière (overhead from behind) passe au-dessus du dos du tireur et s'éloigne. On le voit tard : le tireur regarde donc tôt vers l'arrière, épaule avec lui, tire quand la bouche du canon touche son bord avant et accompagne.", "« Incoming » (rentrant) et « going away » (fuyant) décrivent toujours le plateau par rapport au tireur."], "key_points": ["Rentrant : vient vers le tireur, en général en descendant ; prenez-le devant.", "Fuyant : peu d'avance latérale, surtout verticale ; tirez sans tarder.", "Plateau de tête : un rentrant au-dessus de la tête ; traversez-le depuis l'arrière et masquez-le.", "Plateau par-dessus venant de derrière : regardez tôt vers l'arrière, épaulez avec lui, accompagnez.", "Le Compak® Sporting comporte toujours un fuyant."], "terms": ["incomer", "going-away", "driven-target", "overhead", "tower", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "ShotKam — Master incomers", "url": "https://shotkam.com/blogs/blog-collections/master-incomers"}, {"title": "Sporting Gun — How to shoot going-away targets", "url": "https://sporting-gun.com/shooting/how-to-shoot-going-away-targets/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "flight", "preset": "incomer", "also": ["going-away", "overhead"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}], "coach_says": [{"en": "Take it out in front, before it gets on top of you.", "meaning": "Cassez le rentrant pendant qu'il est encore devant, pas quand il est au-dessus de vous.", "say": "Prenez-le devant, avant qu'il soit sur vous."}, {"en": "Blot it out and keep swinging.", "meaning": "Laissez les canons masquer le plateau au moment du tir et n'arrêtez pas le fusil.", "say": "Masquez-le et continuez le swing."}, {"en": "Don't wait on the going-away — it's getting smaller.", "meaning": "Tirez le fuyant sans tarder, car il s'éloigne rapidement.", "say": "N'attendez pas sur le fuyant, il rapetisse."}, {"en": "It comes from behind you — look back for it early.", "meaning": "C'est un plateau qui vient de derrière par-dessus vous ; tournez les yeux vers lui avant d'appeler.", "say": "Il vient de derrière vous : regardez tôt vers l'arrière."}], "quiz": [{"q": "Le moniteur dit : « Blot it out. » Que doit faire le tireur ?", "options": ["Essuyer les verres de ses lunettes de protection", "Laisser les canons masquer le plateau au moment du tir", "Attendre que le plateau disparaisse de la vue", "Tirer seulement sur les morceaux qui tombent"], "answer": 1, "why": "Sur les rentrants, les plateaux de tête et les montants, le fusil masque souvent le plateau au moment du tir ; c'est exactement ce que demande le moniteur."}, {"q": "Pourquoi ne faut-il pas laisser trop longtemps un fuyant ?", "options": ["Il s'éloigne et rapetisse rapidement", "Le règlement n'accorde que trois secondes", "Il se transforme toujours en traversard", "L'arbitre annonce No bird après le sommet"], "answer": 0, "why": "Un fuyant prend vite de la distance : plus vous attendez, plus il devient difficile. Les trois secondes concernent le délai de lancement, pas une limite de tir."}, {"q": "Qu'est-ce qui distingue un plateau de tête d'un rentrant ordinaire ?", "options": ["C'est toujours un rabbit", "Il vient de derrière le tireur", "Il passe au-dessus de la tête du tireur", "Il n'est lancé qu'en Compak® Sporting"], "answer": 2, "why": "Driven désigne un rentrant qui passe au-dessus de la tête, comme le gibier rabattu. Un plateau qui vient de derrière est un overhead from behind."}]}, {"id": "flight-quartering", "minutes": 5, "title": "Les plateaux en biais : sortants et rentrants", "body": ["Un plateau en biais (quartering) vole en oblique : en partie traversant, en partie fuyant ou rentrant. Le quartering away (fuyant en biais, sortant) s'éloigne du tireur en oblique, par exemple vers l'avant droite. Le quartering towards (aussi « quartering in » : venant en biais, rentrant) vient vers le tireur en oblique et passe d'un côté ou tombe devant lui. L'angle est souvent d'environ 45°, mais tout est possible entre un plateau droit et un traversard pur.", "L'avance dépend de l'angle : plus que pour un fuyant droit, moins que pour un traversard pur. Un angle fermé demande peu d'avance, un plateau presque traversant presque autant qu'un traversard.", "Le fuyant en biais rapetisse et ralentit vite : prenez-le sans tarder. Le pull-away lui convient bien, car le fusil reste sur la ligne du plateau. Le venant en biais grossit et paraît lent, ce qui pousse le tireur à attendre ; il peut alors passer trop près ou disparaître de la vue.", "Le même lanceur donne des présentations différentes selon les postes : depuis un poste, le plateau est un traversard, depuis le suivant, il est en biais. C'est pourquoi les plateaux doivent se lire depuis le poste exact qu'utilisera le tireur.", "En français, dites « fuyant en biais » et « venant en biais » (on entend aussi « demi-traversier »). Un mot calqué sur l'anglais « quarter » ne dit rien à un tireur."], "key_points": ["En biais (quartering) = vol en oblique, entre plateau droit et traversard.", "Le fuyant en biais s'éloigne en oblique ; le venant en biais (quartering in) arrive en oblique.", "L'avance croît avec l'angle : moins qu'un traversard, plus qu'un plateau droit.", "Un même lanceur paraît différent de chaque poste : lisez-le depuis votre propre poste.", "En français : « fuyant en biais / venant en biais »."], "terms": ["quartering-away", "quartering-towards", "crosser", "going-away", "lead", "pull-away"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "flight", "preset": "quartering-away", "also": ["quartering-towards"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "The first one's quartering away to the left — take it quickly before it gets small.", "meaning": "Le premier plateau s'éloigne en oblique vers la gauche du tireur ; cassez-le tôt.", "say": "Le premier est un fuyant en biais vers la gauche : prenez-le vite, avant qu'il rapetisse."}, {"en": "Quartering in from the right — don't let it get too close.", "meaning": "Le plateau vient vers le tireur en oblique depuis la droite ; ne l'attendez pas.", "say": "Venant en biais depuis la droite : ne le laissez pas trop approcher."}, {"en": "Less lead than you think — it's only a slight angle.", "meaning": "Le plateau est presque droit, il ne demande donc qu'une petite avance.", "say": "Moins d'avance que vous ne pensez : l'angle est faible."}], "quiz": [{"q": "Un plateau vient vers le tireur en oblique et passe sur le côté. Comment s'appelle-t-il ?", "options": ["Fuyant", "Venant en biais", "Teal", "Rafale"], "answer": 1, "why": "Le quartering towards (ou quartering in) est un plateau oblique qui arrive ; le quartering away est le plateau oblique qui s'éloigne."}, {"q": "Comment l'avance sur un plateau en biais se compare-t-elle à celle d'un traversard pur à la même distance et à la même vitesse ?", "options": ["Elle est la même que pour le traversard", "Elle est toujours nulle", "Elle est plus grande que pour le traversard", "Elle est plus petite, selon l'angle"], "answer": 3, "why": "Seule la composante latérale du mouvement demande une avance latérale : plus l'angle est fermé, plus l'avance est petite."}, {"q": "Pourquoi faut-il lire un plateau depuis le poste exact d'où vous tirerez ?", "options": ["Un même lanceur peut donner un traversard depuis un poste et un plateau en biais depuis un autre", "Le règlement interdit de regarder depuis un autre endroit", "Les plateaux changent de couleur d'un poste à l'autre", "Seul l'arbitre peut se placer ailleurs"], "answer": 0, "why": "L'angle entre le tireur et la ligne du plateau change avec la position : la présentation change donc aussi."}]}, {"id": "flight-teal-chandelle-looper", "minutes": 6, "title": "Teal, chandelle, looper et plateaux descendants", "body": ["Ces présentations concernent la hauteur et la courbe plutôt que l'angle. Leurs noms appartiennent au vocabulaire des traceurs de parcours, pas au règlement : le règlement énumère les types de plateaux, et celui du Compak® Sporting demande des trajectoires variées, comme des plateaux montants, descendants et en cloche.", "Un teal (springing ou rising teal, d'après la sarcelle ; en français le plus souvent « chandelle ») est lancé presque à la verticale, ralentit, s'arrête au sommet et retombe. On le prend soit à la montée, en remontant à travers lui par-dessous, soit au sommet pendant qu'il marque l'arrêt. Le viser au sommet (poking) est la faute classique. Certains traceurs disent « springing » pour un plateau qui monte en oblique plutôt qu'à la verticale, comme un oiseau qui s'envole.", "Une chandelle au sens anglais (du français « chandelle ») monte fortement sur une légère courbe, bascule et retombe presque à la verticale. Elle est plus facile à la montée ; dans la bascule, l'avance va sur le côté et en dessous.", "Un looper (parabole, plateau en cloche) décrit un grand arc dans le ciel, comme un arc-en-ciel : il monte, bascule au sommet et tombe. C'est le plus souvent un plateau normal ; certains traceurs de parcours lancent aussi une battue sur une telle ligne, qui montre alors sa face en basculant. Le fusil suit la courbe, devant et en dessous.", "Un plateau descendant (dropping target) est tout plateau dans la partie descendante de son vol. L'avance est en partie verticale : en dessous et devant, avec le fusil en mouvement.", "Attention : les noms varient selon les pays. Beaucoup de francophones disent « chandelle » pour un plateau qui monte presque à la verticale, ce qu'un moniteur anglais appelle un teal, et les tireurs ukrainiens peuvent dire « свічка » pour l'un ou l'autre. Chaque fois que vous entendez chandelle, candle ou « свічка », demandez : à la verticale, ou en courbe qui bascule ?"], "key_points": ["Teal : monte presque à la verticale, s'arrête, retombe ; à prendre à la montée ou au sommet.", "Chandelle (sens anglais) : montée raide en courbe, bascule, retombe presque à la verticale.", "Looper : grand arc en arc-en-ciel, le plus souvent un plateau normal qui bascule au sommet et tombe.", "Descendant : avance en dessous et devant, ne jamais arrêter le fusil.", "Les noms varient : en français, « chandelle » désigne souvent le teal ; « свічка » est ambigu aussi, il faut donc préciser."], "terms": ["teal", "springing-target", "chandelle", "looper", "dropping-target", "battue"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "Shotgun Life — How to shoot a chandelle target", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}, {"title": "ShotgunWorld — Target terminology (forum)", "url": "https://www.shotgunworld.com/threads/target-terminology.477902/"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}], "sim": {"type": "flight", "preset": "teal", "also": ["chandelle", "looper", "dropping"]}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}], "coach_says": [{"en": "Take the teal on the way up — keep the barrels moving above it.", "meaning": "Cassez la chandelle (teal) à la montée, avant le sommet ; le fusil continue de monter au-delà.", "say": "Prenez la chandelle à la montée, les canons continuent au-dessus."}, {"en": "Don't poke at it on the top.", "meaning": "Ne vous arrêtez pas pour viser le plateau pendant qu'il marque l'arrêt au sommet.", "say": "Ne la visez pas au sommet."}, {"en": "The looper's turning over — underneath and in front.", "meaning": "Le plateau bascule au sommet de son arc et commence à tomber ; l'avance va en dessous et devant.", "say": "Le looper bascule : en dessous et devant."}, {"en": "Second bird's dropping — go under it and keep the gun moving.", "meaning": "Le second plateau du doublé tombe ; tirez en dessous avec le fusil en mouvement.", "say": "Le second descend : passez dessous et gardez le fusil en mouvement."}], "quiz": [{"q": "Quel plateau est lancé presque à la verticale, s'arrête au sommet et retombe ?", "options": ["Looper", "Fuyant en biais", "Rabbit", "Teal"], "answer": 3, "why": "C'est le teal (springing ou rising teal), en français le plus souvent « chandelle ». Un looper décrit un grand arc dans le ciel."}, {"q": "Où va généralement l'avance sur un plateau descendant ?", "options": ["Au-dessus et derrière", "En dessous et devant", "Droit sur le plateau", "Seulement sur le côté, jamais vers le bas"], "answer": 1, "why": "Un plateau qui tombe se déplace vers le bas autant que vers l'avant : une partie de l'avance est donc verticale, en dessous et devant."}, {"q": "Un moniteur francophone dit « chandelle ». Que faut-il faire, par prudence ?", "options": ["Vérifier : à la verticale, ou en arc qui bascule ?", "Toujours le traduire par le looper anglais", "Toujours le traduire par le teal anglais", "L'ignorer, puisque ce n'est pas un terme du règlement"], "answer": 0, "why": "Les francophones désignent souvent un plateau presque vertical (un teal anglais), alors que la chandelle d'un traceur anglais monte en courbe et bascule ; une vérification rapide évite un mauvais plan."}]}, {"id": "flight-rabbit", "minutes": 5, "title": "Le rabbit : il roule, il saute, il déboule", "body": ["Un rabbit est un plateau de 110 mm au bord épais et résistant, lancé sur sa tranche pour qu'il roule sur le sol comme un lièvre qui court. C'est un plateau spécial : en Parcours de Chasse – Sporting™, il doit donc figurer sur le menu du poste.", "Les moniteurs décrivent sa course : un rolling rabbit roule régulièrement ; un hopping (bouncing) rabbit saute sur les bosses et les pierres ; un bolting rabbit jaillit d'un couvert et file vite. Les rabbits peuvent traverser, venir vers le tireur ou s'en éloigner.", "Un rabbit est lourd et ralentit vite : les tireurs lui donnent donc souvent trop d'avance. Les moniteurs demandent de garder le canon bas et de tirer le bord avant inférieur, pour qu'un saut soudain rencontre quand même la gerbe. Souvent, il n'est visible que dans une courte trouée entre des buissons : le point de casse doit donc être prévu avec précision.", "Règlement : tout plateau, rabbit compris, se tire fusil à l'épaule ; tirer à la hanche est interdit dans les deux disciplines. Cas particulier : si le premier coup manque et que le rabbit casse ensuite tout seul, par exemple sur une pierre, avant le second coup, c'est un No bird. Lors de la répétition, seule une casse au second coup compte.", "« Fur and feather » (poil et plume) est l'argot du Sporting anglais pour un doublé composé d'un rabbit (« fur ») et d'un plateau aérien (« feather »). En français, on dit « rabbit », anglicisme officiel de la FITASC, plus rarement « lapin » ; ce cours emploie « rabbit »."], "key_points": ["Rabbit : 110 mm, bord épais, roule sur sa tranche au sol.", "Rolling, hopping (bouncing), bolting : décrivent sa course.", "Il ralentit vite : pas trop d'avance ; gardez le canon bas.", "Toujours tiré fusil à l'épaule ; un rabbit qui casse tout seul après un premier coup manqué = No bird.", "« Fur and feather » = doublé rabbit + plateau aérien."], "terms": ["rabbit", "bolting-rabbit", "fur-and-feather", "target-menu", "no-bird", "break-point"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Gun Tests — Rabbit target clay shooting", "url": "https://www.gun-tests.com/recreational/rabbit-target-clay-shooting/"}, {"title": "Shooting UK — Clay pigeon sizes", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}], "sim": {"type": "flight", "preset": "rabbit"}, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch6-nobird-target-single-rabbit", "label": "6 · Target No Bird on a single and on a rabbit"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}], "coach_says": [{"en": "It hops on that bump — stay under it and keep moving.", "meaning": "Le rabbit saute à un endroit connu ; gardez le fusil bas et en mouvement.", "say": "Il saute sur cette bosse : restez dessous et continuez à bouger."}, {"en": "Shoot its feet.", "meaning": "Placez la gerbe sur le bord inférieur du rabbit, pas au-dessus.", "say": "Tirez-lui dans les pattes."}, {"en": "It slows down a lot — less lead than you think.", "meaning": "Le rabbit perd vite de la vitesse, il demande donc moins d'avance.", "say": "Il ralentit beaucoup : moins d'avance que vous ne pensez."}, {"en": "Fur and feather: rabbit first, before it reaches the bushes.", "meaning": "Dans le doublé rabbit plus plateau aérien, tirez d'abord le rabbit, car il disparaît dans le couvert.", "say": "Poil et plume : le rabbit d'abord, avant qu'il atteigne les buissons."}], "quiz": [{"q": "Le premier coup manque un rabbit, puis il casse sur une pierre avant le second coup. Que se passe-t-il ?", "options": ["Il est compté bon, puisqu'il a cassé", "Il est compté zéro pour le premier manqué", "No bird : il est répété, seule une casse au second coup compte", "Le tireur passe simplement au plateau suivant"], "answer": 2, "why": "Les deux règlements traitent ce cas comme un No bird ; lors de la répétition, le tireur doit manquer volontairement au premier coup."}, {"q": "Pourquoi les moniteurs mettent-ils en garde contre trop d'avance sur un rabbit ?", "options": ["Le règlement limite l'avance", "Il est lourd et ralentit vite", "Il vole toujours vers le haut", "Il est plus petit qu'un mini"], "answer": 1, "why": "Un rabbit a un bord épais et roule au sol en perdant vite de la vitesse : l'avance habituelle d'un traversard place donc la gerbe devant."}, {"q": "Que signifie « fur and feather » ?", "options": ["Un doublé composé d'un rabbit et d'un plateau aérien", "Un code vestimentaire de chasse", "Un plateau avec des plumes collées", "Un doublé de deux rabbits"], "answer": 0, "why": "Dans l'argot du Sporting anglais, « fur » (poil) est le rabbit et « feather » (plume) le plateau volant."}]}, {"id": "flight-pairs", "minutes": 6, "title": "Simples et doublés : coup de fusil, rafale, simultané", "body": ["Un plateau simple (single) est un plateau issu d'un seul lanceur. Dans les deux disciplines, on peut le tirer de deux coups : un manqué peut donc être rattrapé avec le second coup. Un doublé (pair, double) se compose de deux plateaux tirés comme une seule unité après un seul appel.", "Doublé coup de fusil (report pair, double on report) : l'appel lance le premier plateau, et le coup tiré sur lui lance le second. En Parcours de Chasse – Sporting™, le second part de 0 à 3 secondes après ce coup. L'ordre est imposé. « Report » désigne le bruit du coup de feu, pas un rapport écrit.", "Le doublé que la FITASC appelle rafale (following pair) : deux plateaux du même lanceur sur la même trajectoire, le second aussi vite que le lanceur se recharge ; on peut tirer l'un ou l'autre en premier. Il n'existe qu'en Sporting™ : un doublé de Compak® Sporting est soit coup de fusil, soit simultané.", "Doublé simultané (« simo » ; en Sporting anglais « true pair ») : les deux plateaux partent au même instant, d'un ou deux lanceurs (en Compak® Sporting, toujours de deux lanceurs différents), et peuvent être tirés dans n'importe quel ordre.", "Cartouches : en Sporting™, il y en a deux pour le doublé et les deux peuvent être tirées sur un même plateau ; si un seul coup casse les deux, les deux comptent. En Compak® Sporting, une seule cartouche par plateau est autorisée, et deux coups sur un même plateau donnent zéro-zéro ; un seul coup qui casse les deux plateaux n'est pas non plus simplement compté deux fois (la mission Compak® l'explique).", "Sur un poste de Sporting™, la planche tire d'abord les plateaux simples, puis les doublés. Les doublés simultanés et les rafales sont montrés avant le tir ; les doublés coup de fusil ne le sont pas."], "key_points": ["Plateau simple : un plateau, deux coups autorisés.", "Doublé coup de fusil : le coup sur le premier lance le second ; ordre imposé.", "Rafale (following pair) : même lanceur, même trajectoire, en Sporting™ uniquement.", "Simultané (true pair) : les deux à la fois, dans n'importe quel ordre.", "Sporting™ : les deux cartouches peuvent aller sur un même plateau ; Compak® Sporting : une par plateau."], "terms": ["single-target", "double", "double-on-report", "rafale-double", "simultaneous-double", "true-pair", "target-presentation"], "sources": [{"title": "CPSA — English Sporting (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["teal"], "pairs": ["report", "simultaneous", "rafale"]}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}], "coach_says": [{"en": "It's on report — finish the first one properly, the second waits for your shot.", "meaning": "Le second plateau ne part que lorsque le tireur tire sur le premier : inutile donc de précipiter le premier.", "say": "C'est un coup de fusil : finissez bien le premier, le second attend votre coup."}, {"en": "Simo: take the rabbit first, the teal will wait for you.", "meaning": "Dans le doublé simultané, tirez d'abord le rabbit, car la chandelle (teal) reste plus longtemps en l'air.", "say": "Simultané : prenez d'abord le rabbit, la chandelle vous attendra."}, {"en": "Rafale — after the first, come straight back to the trap for the second.", "meaning": "Les deux plateaux viennent du même lanceur ; après le premier coup, ramenez les yeux et le fusil vers le lanceur pour prendre le second.", "say": "Rafale : après le premier, revenez tout de suite vers le lanceur pour le second."}, {"en": "True pair from the tower, five of them.", "meaning": "Cinq doublés simultanés lancés depuis la tour (formulation du Sporting anglais).", "say": "Doublés simultanés depuis la tour, cinq."}], "quiz": [{"q": "Dans un doublé coup de fusil, qu'est-ce qui lance le second plateau ?", "options": ["Un second appel", "Le signal de l'arbitre", "Le coup tiré sur le premier plateau", "Une minuterie d'exactement 5 secondes"], "answer": 2, "why": "« On report » signifie au bruit du coup de feu : tirer sur le premier plateau lance le second."}, {"q": "Un tireur tire ses deux cartouches sur le premier plateau d'un doublé simultané en Compak® Sporting. Résultat ?", "options": ["Autorisé, comme en Sporting™", "Zéro-zéro", "No bird et répétition", "Seul le second plateau est zéro"], "answer": 1, "why": "Le Compak® Sporting autorise une cartouche par plateau d'un doublé ; tirer volontairement les deux sur un même plateau donne zéro-zéro. En Sporting™, ce serait autorisé."}, {"q": "Un moniteur britannique dit « true pair ». Comment le traduisez-vous ?", "options": ["Un doublé correct, régulier", "Un doublé de vrais oiseaux", "Une rafale", "Un doublé simultané"], "answer": 3, "why": "« True pair » est le nom du doublé simultané dans le Sporting anglais ; « true » n'a rien à voir avec la régularité."}]}]}, {"id": "basics", "icon": "stance", "title": "Les fondamentaux du tir", "intro": "Avant de parler d'avance, le moniteur règle les bases : les pieds, l'épaulé, les yeux, un plan en trois points et un fusil qui ne s'arrête pas. Ces cinq leçons vous donnent les mots du moniteur pour chaque étape et les règles qui limitent ce que le tireur a le droit de faire.", "lessons": [{"id": "basics-stance", "minutes": 5, "title": "La position : les pieds vers le point de casse", "body": ["La position (stance) est la façon dont le tireur se tient avant le tir. L'espace est réduit : en Parcours de Chasse – Sporting™, le poste de tir est un carré ou un cercle de 1 m, et les deux pieds doivent s'y trouver avant que le tireur appelle le plateau. En Compak® Sporting, chaque pas de tir est un carré de 1 m équipé d'un limiteur d'angle de tir, un cadre qui empêche le tireur d'avancer et limite son swing.", "La base habituelle : les pieds écartés à peu près de la largeur des épaules ; pour un droitier, le pied gauche légèrement en avant (un gaucher fait l'inverse) ; les genoux souples, pas bloqués ; le poids légèrement vers l'avant, environ 60 % sur le pied avant. Les moniteurs anglophones disent « nose over toes » (le nez au-dessus des orteils).", "La consigne clé : orienter le pied avant vers le point de casse, l'endroit où le tireur prévoit de casser le plateau. Le corps est alors à l'aise, « déroulé », exactement là où le tir a lieu. Le tireur pivote depuis les hanches pour revenir vers le point d'attente des canons, puis se déroule dans le tir. Si les pieds font face au lanceur, préviennent les moniteurs, le corps arrive en bout de rotation : le fusil s'arrête ou la tête se lève.", "Le corps pivote depuis les hanches, pas avec les bras. Les pieds peuvent être placés un peu différemment pour chaque plateau.", "Traduisez « front foot » et « back foot » par pied avant et pied arrière, et non par gauche et droite : votre tireur est peut-être gaucher."], "key_points": ["Sporting™ : les deux pieds dans le poste de 1 m avant d'appeler le plateau.", "Compak® Sporting : pas de tir de 1 m avec limiteur d'angle de tir.", "Pieds à la largeur des épaules, genoux souples, poids légèrement vers l'avant.", "Le pied avant vise le point de casse ; on pivote depuis les hanches pour revenir au point d'attente.", "Traduisez pied avant / pied arrière, pas gauche / droite."], "terms": ["stance", "shooting-stand", "break-point", "hold-point", "firing-angle-limiter"], "sources": [{"title": "NSSA-NSCA — Stance and foot position (blog)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "Shotgun Life — Best foot position for clays shooting", "url": "https://www.shotgunlife.com/briefs/best-foot-position-for-clays-shooting.html"}, {"title": "Positive Shooting — Stance", "url": "http://www.positiveshooting.com/StanceMain.html"}], "sim": {"type": "flight", "preset": "crosser-lr", "focus": "stance"}, "rule_refs": [{"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}], "coach_says": [{"en": "Point your front foot at the break point.", "meaning": "Tournez la pointe du pied avant vers l'endroit où le plateau sera cassé.", "say": "Pointez votre pied avant vers le point de casse."}, {"en": "Set your feet for the break, then wind back to the hold.", "meaning": "Placez d'abord les pieds pour le point de casse, puis faites pivoter le haut du corps vers le point d'attente des canons.", "say": "Placez vos pieds pour la casse, puis revenez en arrière jusqu'au point d'attente."}, {"en": "Weight forward, soft knees.", "meaning": "Penchez-vous légèrement sur le pied avant et ne bloquez pas les genoux.", "say": "Le poids vers l'avant, les genoux souples."}, {"en": "Turn from the hips, not the arms.", "meaning": "Tout le haut du corps pivote ; les bras ne font pas bouger le fusil tout seuls.", "say": "Pivotez avec les hanches, pas avec les bras."}], "quiz": [{"q": "Vers où le moniteur veut-il généralement que le pied avant soit orienté ?", "options": ["Vers le lanceur", "Vers le point de prise", "Vers l'arbitre", "Vers le point de casse"], "answer": 3, "why": "Des pieds placés pour le point de casse laissent le corps à l'aise là où le tir a lieu ; des pieds tournés vers le lanceur font arriver le corps en bout de rotation."}, {"q": "Qu'exige le règlement du Parcours de Chasse – Sporting™ pour les pieds avant l'appel du plateau ?", "options": ["Les deux pieds à l'intérieur du poste", "Le pied avant sur la ligne du poste", "Les pieds joints", "Aucune exigence"], "answer": 0, "why": "La règle de la position d'attente demande que les deux pieds soient à l'intérieur du poste de tir de 1 m avant que le tireur appelle le plateau."}, {"q": "Un tireur gaucher. Le moniteur dit « Open your front foot ». De quel pied s'agit-il ?", "options": ["Toujours le gauche, quelle que soit la main", "Le droit : c'est le pied avant d'un gaucher", "Le pied arrière, plus proche du lanceur", "Les deux pieds ensemble"], "answer": 1, "why": "Pour un gaucher, le pied avant est le droit. Traduire « front foot » par « pied avant » évite l'erreur."}]}, {"id": "basics-mount", "minutes": 6, "title": "Position d'attente et épaulé", "body": ["En Parcours de Chasse – Sporting™, le départ se fait fusil bas. Avant d'appeler le plateau, le talon de la crosse touche le corps et le haut de l'arrière de la crosse reste sous une ligne tracée sur le gilet, 25 cm sous l'axe des épaules, d'une couleur contrastée. Le tireur garde cette position jusqu'à ce que le plateau soit lancé et visible. Épauler plus tôt vaut un avertissement verbal avec carton jaune ; une récidive sur le même parcours entraîne un carton rouge et le plateau est déclaré zéro.", "En Compak® Sporting, la position du fusil à l'appel est libre : le fusil peut donc déjà être épaulé. Dans les deux disciplines, chaque plateau se tire fusil à l'épaule, et en Sporting™ la position du fusil est libre entre les deux plateaux d'un doublé.", "L'épaulé (gun mount) amène le fusil à la joue et à l'épaule. Les moniteurs enseignent « muzzles first », les canons d'abord : la main avant met les canons en mouvement le long de la ligne du plateau, la crosse monte vers la joue et se loge dans le creux de l'épaule au moment où le fusil rejoint la ligne. « Move, mount, shoot » (bouger, épauler, tirer) est un seul mouvement fluide. Le fusil vient au visage, et non le visage au fusil ; la joue reste sur le busc, car l'œil fait office de hausse.", "Un moniteur britannique peut dire « gun up » ou « pre-mount this one » (épaule d'avance pour celui-ci). C'est interdit en compétition FITASC de Sporting™, normal en Compak® Sporting, et seulement un exercice à l'entraînement. Épauler et suivre une ligne imaginaire avant d'appeler le plateau (simulacre de tir) est interdit en Sporting™ : d'abord un avertissement, puis un zéro."], "key_points": ["Sporting™ : crosse sous la ligne du gilet (25 cm sous l'axe des épaules) jusqu'à ce que le plateau soit visible.", "Épaulé anticipé : carton jaune, puis carton rouge et plateau perdu sur le même parcours.", "Compak® Sporting : position du fusil libre à l'appel ; on tire toujours fusil à l'épaule.", "Les canons d'abord, le fusil au visage, la joue sur le busc : bouger, épauler, tirer.", "« Pre-mount » est un exercice d'entraînement, jamais en compétition FITASC de Sporting™."], "terms": ["ready-position", "jacket-line", "gun-mount", "move-mount-shoot", "comb", "yellow-card", "mock-shooting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-lr", "focus": "mount"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Gun to your face, not your face to the gun.", "meaning": "Montez la crosse jusqu'à la joue ; ne baissez pas la tête pour aller chercher le fusil.", "say": "Le fusil vient au visage, pas le visage au fusil."}, {"en": "Muzzles first — move, mount, shoot.", "meaning": "Mettez les canons en mouvement avec le plateau, épaulez pendant le mouvement et tirez quand l'épaulé est terminé.", "say": "Les canons d'abord : on bouge, on épaule, on tire."}, {"en": "Your mount's late and too fast — start it with the front hand.", "meaning": "Le fusil monte trop tard et par à-coup ; la main avant doit lancer le mouvement plus tôt.", "say": "Votre épaulé est trop tardif et trop brusque : lancez-le avec la main avant."}, {"en": "Low gun on this one, like in competition.", "meaning": "Partez avec la crosse sous la ligne du gilet, comme l'exige le règlement FITASC du Sporting™.", "say": "Fusil bas sur celui-ci, comme en compétition."}], "quiz": [{"q": "En Parcours de Chasse – Sporting™, jusqu'à quand la crosse doit-elle rester sous la ligne du gilet ?", "options": ["Jusqu'à ce que le tireur ait appelé le plateau", "Jusqu'à ce que l'arbitre fasse un signe de tête", "Jusqu'à ce que le plateau soit sorti et visible", "Jusqu'au premier coup de feu"], "answer": 2, "why": "La position d'attente est maintenue jusqu'à ce que le plateau soit lancé et visible ; ce n'est qu'alors que le fusil peut être épaulé."}, {"q": "En Compak® Sporting, un tireur peut-il appeler le plateau avec le fusil déjà épaulé ?", "options": ["Non : il reçoit un carton jaune", "Seulement pour les rabbits et autres plateaux bas", "Seulement entre les deux plateaux d'un doublé", "Oui : la position du fusil à l'appel est libre"], "answer": 3, "why": "Le Compak® Sporting n'a pas de règle du fusil bas : le fusil peut être épaulé ou non à l'appel, mais chaque plateau se tire fusil à l'épaule."}, {"q": "Pourquoi les moniteurs insistent-ils pour que la joue reste sur le busc ?", "options": ["L'œil fait office de hausse, il doit donc toujours être au même endroit", "Pour réduire le bruit qui arrive à l'oreille", "Parce que le règlement des deux disciplines l'exige", "Pour cacher son visage à l'arbitre"], "answer": 0, "why": "Un fusil n'a pas de hausse : c'est l'œil au-dessus de la bande de visée qui vise, donc une joue qui se lève envoie la gerbe trop haut."}]}, {"id": "basics-eyes", "minutes": 5, "title": "Les yeux : œil directeur, deux yeux ouverts, regard précis", "body": ["La plupart des gens ont un œil directeur (master eye), auquel le cerveau fait davantage confiance, en général du même côté que la main dominante. C'est l'œil directeur qui doit regarder le long de la bande de visée. La dominance croisée (cross-dominance) signifie que l'œil directeur est du côté opposé à l'épaule de tir ; la vision centrale signifie qu'aucun œil ne domine nettement. Dans les deux cas, le fusil pointe là où le tireur ne s'y attend pas, souvent sur le côté.", "Un test simple : les deux yeux ouverts, encadrez un objet lointain dans un petit triangle formé avec les mains, puis fermez chaque œil à tour de rôle ; l'œil qui garde l'objet dans le triangle est l'œil directeur. Le moniteur peut aussi se placer face au tireur et regarder à travers le triangle.", "Les solutions, choisies par le moniteur : fermer ou plisser l'autre œil pendant l'épaulé ; une petite pastille sur les lunettes de protection ; apprendre à tirer de l'autre épaule ; ou, plus rarement, une crosse croisée (cross-over). On préfère tirer les deux yeux ouverts quand c'est possible, car deux yeux évaluent mieux la vitesse, l'angle et la distance.", "Le regard : un regard souple et large en attendant au point de prise, puis un regard précis sur le plateau lui-même, idéalement sur son bord avant. Revenir regarder le canon ou le guidon pour vérifier l'avance arrête le fusil.", "Les lunettes de protection sont obligatoires pour les tireurs dans les deux disciplines : c'est donc sur elles que l'on colle la pastille."], "key_points": ["C'est l'œil directeur qui doit regarder le long de la bande de visée.", "La dominance croisée et la vision centrale font pointer le fusil à côté du plateau.", "Test avec un triangle formé par les mains ; le moniteur choisit la solution.", "Regard souple au point de prise, regard précis sur le bord avant ; ne jamais revenir sur le guidon.", "Lunettes de protection obligatoires dans les deux disciplines."], "terms": ["eye-dominance", "master-eye", "cross-dominance", "central-vision", "soft-focus", "hard-focus", "leading-edge", "safety-glasses"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "Paragon School — Eye dominance testing", "url": "https://www.paragonschool.com/blog-post/eye-dominance-testing-and-issues-in-sporting-clays-skeet-and-trap-go-slowly-please"}, {"title": "Shotgun Life — How to shoot a chandelle target (focus on the leading edge)", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}], "sim": {"type": "flight", "preset": "going-away", "focus": "eyes"}, "rule_refs": [{"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}], "coach_says": [{"en": "Close your left eye as the gun comes up.", "meaning": "Fermez l'œil gauche pendant l'épaulé, pas avant, pour que l'œil droit dirige le fusil.", "say": "Fermez l'œil gauche pendant que le fusil monte."}, {"en": "Eyes on the clay, not the barrel.", "meaning": "Continuez à regarder le plateau ; vérifier le canon arrête le fusil.", "say": "Les yeux sur le plateau, pas sur le canon."}, {"en": "Look at the leading edge.", "meaning": "Fixez le bord avant du plateau en mouvement, pas son centre.", "say": "Regardez le bord avant."}, {"en": "Don't look at the trap — look out to your pick-up point.", "meaning": "Attendez avec les yeux un peu plus loin sur la ligne, là où l'on voit le plateau nettement pour la première fois.", "say": "Ne regardez pas le lanceur : regardez plus loin, à votre point de prise."}], "quiz": [{"q": "Un tireur droitier a l'œil gauche directeur. Comment cela s'appelle-t-il ?", "options": ["Vision centrale", "Regard précis", "Dominance croisée", "Bord avant"], "answer": 2, "why": "La dominance croisée, c'est un œil directeur du côté opposé à l'épaule de tir."}, {"q": "Pourquoi est-ce une faute de revenir regarder le guidon pour vérifier l'avance ?", "options": ["C'est interdit par le règlement", "Cela arrête le fusil et la gerbe passe derrière", "Le guidon reflète le soleil", "Cela fait changer le plateau de couleur"], "answer": 1, "why": "Quand le regard passe sur le fusil, le swing s'arrête et le plateau passe en vision périphérique : la gerbe passe derrière."}, {"q": "Où place-t-on généralement la pastille contre la dominance ?", "options": ["Sur les lunettes de protection, devant l'œil à neutraliser", "Sur le guidon au bout de la bande de visée", "Sur la bande de visée, à mi-longueur", "Sur la ligne du gilet, sous l'épaule"], "answer": 0, "why": "Les lunettes de protection sont de toute façon obligatoires ; une petite pastille sur le verre devant l'œil non directeur est donc la solution la plus simple."}]}, {"id": "basics-three-points", "minutes": 5, "title": "Point de prise, point d'attente et point de casse : préparer un poste", "body": ["Avant chaque plateau, le tireur fixe trois points. Le point de prise (pick-up point) est l'endroit où les yeux voient le plateau nettement pour la première fois, un peu au-delà du lanceur plutôt qu'à sa sortie, où le plateau n'est qu'une traînée floue. Le point d'attente des canons (hold point) est l'endroit où les canons attendent au moment de l'appel, en général sur la ligne du plateau ou juste en dessous, entre le point de prise et le point de casse. Le point de casse (break point) est l'endroit où le tireur prévoit de casser le plateau.", "L'ordre de préparation : choisir d'abord le point de casse, y orienter les pieds, revenir en pivotant jusqu'au point d'attente, puis poser les yeux sur le point de prise. En Parcours de Chasse – Sporting™, la crosse reste basse jusqu'à l'apparition du plateau ; le point d'attente y désigne donc l'endroit où pointent les canons pendant que le fusil est bas.", "Les erreurs typiques : un point de casse trop lointain donne un swing rapide et mal contrôlé, ou un plateau qui retombe déjà ; trop proche, il y a trop peu de mouvement et le tireur « pique » (poke). Un point d'attente trop près du lanceur oblige le fusil à courir après le plateau ; trop loin, le plateau dépasse le fusil.", "On lit les plateaux pendant la présentation. En Sporting™, toutes les trajectoires sont montrées au premier tireur et, sur demande, l'arbitre répète la présentation, jusqu'à deux plateaux pour chaque plateau du menu ; en Compak® Sporting par planches, les plateaux simples sont montrés une seule fois le matin, pour la première planche. Le plateau doit être cassé là où l'arbitre peut le voir, à l'intérieur de la limite de tir.", "« Where are you taking it? » demande le point de casse ; « kill point » en est un synonyme neutre."], "key_points": ["Point de prise = les yeux ; point d'attente = les canons ; point de casse = là où le plateau est cassé.", "On prépare à rebours depuis le point de casse : pieds, point d'attente, yeux.", "Le point d'attente se situe en général entre prise et casse, sur la ligne ou juste en dessous.", "On lit les plateaux pendant la présentation ; on les casse là où l'arbitre peut les voir.", "« Where are you taking it? » = où est votre point de casse ?"], "terms": ["pick-up-point", "hold-point", "break-point", "target-presentation", "shooting-limit", "target-line"], "sources": [{"title": "Shotgun Life — The proper hold point for sporting clays", "url": "https://www.shotgunlife.com/briefs/what-is-the-proper-hold-point-for-shooting-sporting-clays.html"}, {"title": "Clay Target Instruction — Hold point", "url": "https://claytargetinstruction.com/articles/hold-point/"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "flight", "preset": "quartering-away", "focus": "points"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}], "coach_says": [{"en": "Where are you taking it?", "meaning": "Le moniteur demande où le tireur prévoit de casser le plateau.", "say": "Vous le prenez où ?"}, {"en": "Move your hold point halfway back to the trap.", "meaning": "Tenez les canons plus près du lanceur, à la moitié de la distance actuelle.", "say": "Ramenez votre point d'attente à mi-chemin du lanceur."}, {"en": "Look further out — pick it up where it's sharp.", "meaning": "Éloignez les yeux du lanceur, vers l'endroit où l'on voit le plateau nettement pour la première fois.", "say": "Regardez plus loin : prenez-le là où il est net."}, {"en": "Hold a little lower, just under the line.", "meaning": "Gardez les canons légèrement sous la trajectoire du plateau au moment de l'appel.", "say": "Attendez un peu plus bas, juste sous la ligne."}], "quiz": [{"q": "Quel point concerne les yeux et non le fusil ?", "options": ["Le point d'attente", "Le point de casse", "Le point de prise", "Le point d'insertion"], "answer": 2, "why": "Le point de prise est l'endroit où les yeux voient le plateau nettement pour la première fois ; le point d'attente concerne les canons."}, {"q": "Que se passe-t-il généralement si le point d'attente est trop près du lanceur ?", "options": ["Le plateau dépasse le fusil", "L'arbitre annonce No bird", "Le fusil doit courir après le plateau", "Le plateau ralentit"], "answer": 2, "why": "Trop près du lanceur, le plateau passe devant les canons à pleine vitesse et le tireur doit lui courir après."}, {"q": "En Parcours de Chasse – Sporting™, le tireur au poste demande à revoir la présentation. Quel est le maximum par plateau du menu ?", "options": ["Deux plateaux", "Aucun : la répétition n'est pas autorisée", "Autant qu'il le souhaite", "Exactement cinq"], "answer": 0, "why": "L'arbitre répète la présentation sur demande, jusqu'à un maximum de deux plateaux pour chaque plateau du menu."}]}, {"id": "basics-follow-through", "minutes": 5, "title": "Accompagnement, vitesse du fusil et tempo", "body": ["L'accompagnement (follow-through) signifie que le fusil continue de se déplacer le long de la ligne du plateau après l'appui sur la détente, comme un swing au golf ou au tennis. Il y a un petit délai entre la décision de tirer et la sortie de la gerbe des canons ; si le fusil s'arrête à la détente, la gerbe passe derrière. Les moniteurs regardent les canons après le tir : s'ils se figent ou tombent, l'accompagnement a manqué.", "La vitesse du fusil, c'est la vitesse des canons par rapport à celle du plateau, et elle définit la méthode d'avance : la même vitesse que le plateau, c'est l'avance maintenue (maintained lead) ; plus vite que le plateau, c'est le swing (swing-through) ; la même vitesse puis une courte accélération, c'est le pull-away (départ sur le plateau). Un fusil trop lent reste derrière ; un fusil trop rapide, disent les moniteurs, dépasse le plateau, et le tireur l'arrête alors souvent.", "Le tempo, c'est la vitesse d'exécution de tout le tir ; le rythme, c'est sa régularité. Un plateau rapide et proche demande un tempo vif, un long traversard lent un tempo plus calme, mais le rythme reste fluide. Beaucoup de moniteurs disent que les tireurs qui ont un seul tempo pour tout perdent les plateaux qui demandent le contraire.", "« Stay in the gun » (restez dans le fusil) : la joue sur la crosse et les yeux sur le plateau jusqu'à ce qu'il casse. Cela garde aussi le tireur prêt pour le deuxième coup, car on peut tirer deux coups sur un plateau simple.", "Traduisez « finish the shot » par la poursuite du mouvement, et non par un arrêt."], "key_points": ["Accompagnement : le fusil continue de bouger après la détente ; un arrêt envoie la gerbe derrière.", "La vitesse du fusil définit la méthode : égale (avance maintenue), plus rapide (swing), égale puis plus rapide (pull-away).", "Tempo = vitesse de tout le tir ; rythme = sa régularité.", "Restez dans le fusil : prêt pour le deuxième coup sur un plateau simple.", "« Finish the shot » = continuer le mouvement."], "terms": ["follow-through", "gun-speed", "tempo", "stopping-the-gun", "maintained-lead", "swing-through", "pull-away", "single-target"], "sources": [{"title": "Shooting UK — The overhead clay from behind (follow-through)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "focus": "follow-through"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "Follow through — the gun keeps moving after the bang.", "meaning": "N'arrêtez pas le swing au moment du coup de feu.", "say": "Accompagnez : le fusil continue de bouger après le coup."}, {"en": "You stopped the gun.", "meaning": "Les canons se sont arrêtés à la détente, donc la gerbe est passée derrière.", "say": "Vous avez arrêté le fusil."}, {"en": "Match the speed of the bird — you're racing it.", "meaning": "Le fusil va beaucoup plus vite que le plateau ; déplacez-vous à la vitesse du plateau.", "say": "Calez-vous sur la vitesse du plateau : là, vous faites la course avec lui."}, {"en": "Slow the tempo down, this one gives you lots of time.", "meaning": "Le plateau est lent ou long, donc tout le mouvement peut être plus calme.", "say": "Ralentissez le tempo, celui-ci vous laisse beaucoup de temps."}, {"en": "Stay in the gun until you see it break.", "meaning": "Gardez la joue sur la crosse et les yeux sur le plateau jusqu'à ce qu'il casse.", "say": "Restez dans le fusil jusqu'à ce que vous le voyiez casser."}], "quiz": [{"q": "Le moniteur dit « You stopped the gun ». Où la gerbe est-elle le plus probablement passée ?", "options": ["Devant", "Au-dessus", "Exactement sur le plateau", "Derrière"], "answer": 3, "why": "Le plateau continue d'avancer alors que le fusil arrêté ne bouge plus : la gerbe passe derrière."}, {"q": "Quelle vitesse du fusil correspond à l'avance maintenue ?", "options": ["Beaucoup plus rapide que le plateau", "La même que le plateau", "Nulle : le fusil attend", "Plus lente que le plateau"], "answer": 1, "why": "En avance maintenue, les canons se déplacent à la vitesse du plateau et l'écart reste constant. Un fusil qui attend, c'est l'embuscade (ambush) ; plus rapide, c'est le swing."}, {"q": "Quelle est la différence entre tempo et rythme ?", "options": ["Le tempo est la vitesse du tir, le rythme sa régularité", "Ce sont deux mots pour la même chose", "Le tempo est la musique diffusée sur le stand", "Le rythme est le temps imparti entre les plateaux"], "answer": 0, "why": "Les moniteurs changent de tempo pour chaque plateau tout en gardant un rythme fluide : traduisez donc les deux mots séparément."}]}]}, {"id": "lead", "icon": "lead", "title": "L'avance et les méthodes de tir", "intro": "L'avance est le sujet dont les moniteurs parlent le plus : pourquoi le fusil doit pointer devant un plateau en mouvement, les quatre façons d'y arriver, et les unités étranges qu'ils emploient pour la décrire. Cette mission montre chaque méthode étape par étape et vous apprend à traduire « four foot », « half a bird » ou « double it » sans en changer le sens.", "lessons": [{"id": "lead-why", "minutes": 6, "title": "Pourquoi l'avance existe : avance réelle et avance perçue", "body": ["La gerbe a besoin d'une fraction de seconde pour atteindre le plateau, et pendant ce temps le plateau continue d'avancer. Un fusil pointé droit sur un traversard tire donc derrière lui. Le fusil doit pointer devant, pour que la gerbe et le plateau se rencontrent. Cet écart, c'est l'avance (lead ; en anglais britannique aussi « forward allowance »).", "L'avance augmente avec la vitesse du plateau, sa distance et son angle. Un traversard pur en demande le plus ; un plateau qui vole droit vers le tireur ou s'éloigne de lui ne demande presque aucune avance latérale, mais les plateaux montants et descendants demandent une avance verticale (au-dessus ou en dessous).", "Les chiffres réels surprennent. Un site consacré au tir indique environ 3 à 4 pieds, soit à peu près un mètre, d'avance réelle pour un traversard à environ 21–25 yards (une vingtaine de mètres). Beaucoup de tireurs disent qu'elle croît à peu près proportionnellement à la distance : le même petit écart à la bouche du canon représente donc beaucoup plus d'avance réelle sur un plateau lointain.", "L'avance réelle est la distance réelle devant le plateau, dans l'air. L'avance perçue (le « lead picture » ou « sight picture », l'image d'avance) est l'écart que le tireur voit entre la bouche du canon et le plateau. Un mètre à 20 m ressemble à quelques centimètres à la bouche du canon. La méthode change l'image : parmi les méthodes où le fusil bouge, l'avance maintenue montre le plus grand écart et le swing peu ou pas d'écart, parce que la vitesse du fusil ajoute de l'avance. En embuscade, le fusil est immobile : le tireur doit donc voir un écart encore plus grand, car le plateau continue d'avancer pendant le temps de réaction.", "Un instructeur américain remarque qu'un tireur droitier a souvent l'impression qu'un traversard de gauche à droite demande plus d'avance qu'un traversard de droite à gauche ; l'avance réelle est la même, seule la perception diffère. Les « four feet » d'un moniteur décrivent donc son image, pas une mesure."], "key_points": ["L'avance existe parce que le plateau se déplace pendant le trajet de la gerbe.", "Plus de vitesse, de distance et d'angle = plus d'avance.", "L'avance réelle se compte en mètres dans l'air, au plateau ; à la bouche du canon, l'image ne fait que quelques centimètres, car le canon est près de l'œil.", "La méthode change l'image : fusil en mouvement, l'avance maintenue en montre le plus, le swing le moins ; en embuscade (fusil immobile), l'écart est encore plus grand.", "Le chiffre d'un moniteur est une image, pas une mesure."], "terms": ["lead", "perceived-lead", "crosser", "gun-speed", "maintained-lead", "swing-through"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "focus": "perceived-vs-actual"}, "rule_refs": [], "coach_says": [{"en": "Forget the real distance — what matters is your picture.", "meaning": "Ne pensez pas en mètres dans l'air ; souvenez-vous de l'écart que vous avez vu à la bouche du canon quand vous l'avez cassé.", "say": "Oubliez la distance réelle : ce qui compte, c'est votre image."}, {"en": "That's the picture — remember it.", "meaning": "L'avance était juste sur ce plateau cassé ; gardez la même image.", "say": "C'est cette image-là : retenez-la."}, {"en": "Same lead on the right-to-left, it only looks different.", "meaning": "L'avance réelle est la même dans les deux sens ; seule la perception change.", "say": "Même avance sur le droite-gauche, ça paraît seulement différent."}], "quiz": [{"q": "Qu'est-ce que l'avance perçue ?", "options": ["La distance réelle devant le plateau, dans l'air", "L'écart que le tireur voit entre la bouche du canon et le plateau", "L'avance inscrite sur le menu du poste", "La distance entre le poste et le lanceur"], "answer": 1, "why": "L'avance perçue est l'image à la bouche du canon ; l'avance réelle est la distance réelle dans l'air, beaucoup plus grande."}, {"q": "Quelle méthode donne généralement la plus grande avance perçue ?", "options": ["Le swing", "Le pull-away", "L'avance maintenue", "Elles sont toutes identiques"], "answer": 2, "why": "En avance maintenue, le fusil se déplace à la vitesse du plateau et sa vitesse n'ajoute rien : le tireur doit donc voir tout l'écart."}, {"q": "Quel plateau ne demande presque aucune avance latérale ?", "options": ["Un plateau qui s'éloigne tout droit", "Un traversard long", "Un fuyant en biais à 45°", "Un traversard à 40 m"], "answer": 0, "why": "Un fuyant droit n'a pas de mouvement latéral ; l'avance dont il a besoin est verticale."}]}, {"id": "lead-maintained", "minutes": 5, "title": "L'avance maintenue : se placer devant, rester devant", "body": ["L'avance maintenue (maintained lead ; aux États-Unis sustained lead) garde les canons devant le plateau du début jusqu'au tir.", "Comment cela se passe, étape par étape, sur un traversard. 1) Départ : les canons attendent à un point d'attente situé bien en avant sur la ligne, devant l'endroit où passera le plateau ; les yeux regardent en arrière vers le point de prise. 2) Insertion : quand le plateau arrive, le fusil bouge et les canons rejoignent la ligne devant lui, jamais derrière ; c'est le point d'insertion. 3) Suivi : les canons se déplacent à la vitesse du plateau, si bien que l'écart reste le même. 4) Tir : on appuie sur la détente pendant que l'écart est juste et que le fusil bouge encore. 5) Le fusil continue de bouger après le coup.", "Points forts : précise, peu de mouvement du fusil, rapide entre les plateaux, et l'avance est facile à ajuster. Elle convient aux plateaux réguliers et prévisibles : longs traversards, plateaux hauts et réguliers.", "Points faibles : c'est la méthode la plus difficile à apprendre ; le tireur doit connaître à l'avance la vitesse et la ligne du plateau ; et comme le fusil n'est pas plus rapide que le plateau, le tireur voit le plus grand écart et est tenté de le mesurer, de ralentir et de s'arrêter.", "Les moniteurs disent « insert the gun in front » (insérez le fusil devant), « stay ahead of it » (restez devant), « match its speed » (calez-vous sur sa vitesse)."], "key_points": ["Les canons partent devant et rejoignent la ligne devant le plateau.", "Vitesse du fusil = vitesse du plateau ; l'écart reste constant.", "Détente quand l'écart est juste et que le fusil bouge ; puis accompagnement.", "Idéale sur les plateaux longs et prévisibles.", "Risque principal : mesurer l'écart et arrêter le fusil."], "terms": ["maintained-lead", "insertion-point", "hold-point", "gun-speed", "follow-through", "crosser"], "sources": [{"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shotgun Sports USA — How to read sporting clays targets (insertion point)", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "muzzle_start": "ahead", "gun_speed": "equal", "trigger": "gap-held", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Get in front and stay in front.", "meaning": "Placez les canons devant le plateau et gardez-les là jusqu'après le tir.", "say": "Mettez-vous devant et restez devant."}, {"en": "Your insertion point is behind the bird — put the gun in front of it.", "meaning": "Les canons ont rejoint la ligne derrière le plateau ; ils doivent la rejoindre devant lui.", "say": "Votre point d'insertion est derrière le plateau : mettez le fusil devant lui."}, {"en": "Match its speed — don't let it catch you.", "meaning": "Déplacez le fusil à la vitesse du plateau pour que l'écart ne diminue pas.", "say": "Calez-vous sur sa vitesse, ne le laissez pas vous rattraper."}, {"en": "You're measuring it — trust the picture and pull.", "meaning": "Le tireur ralentit pour vérifier l'écart ; tirez dès que l'image est juste.", "say": "Vous le mesurez : faites confiance à l'image et tirez."}], "quiz": [{"q": "En avance maintenue, où les canons rejoignent-ils la ligne du plateau ?", "options": ["Derrière le plateau", "Sur le plateau", "Devant le plateau", "Sous le lanceur"], "answer": 2, "why": "Les canons s'insèrent devant le plateau et restent devant ; derrière, c'est le swing, sur le plateau, c'est le pull-away."}, {"q": "Quelle est la faute typique des tireurs en avance maintenue ?", "options": ["Partir trop loin derrière", "Mesurer l'écart et arrêter le fusil", "Épauler depuis la hanche", "Tirer trop tôt, près du lanceur"], "answer": 1, "why": "L'écart est grand et visible, donc les tireurs sont tentés de le vérifier ; le fusil ralentit ou s'arrête, et la gerbe passe derrière."}, {"q": "Pour quel plateau recommande-t-on souvent l'avance maintenue ?", "options": ["Un traversard long et prévisible", "Un rabbit sautillant dans une courte trouée", "Un plateau surprise venant de derrière", "Un plateau ZZ"], "answer": 0, "why": "La méthode demande une vitesse et une ligne connues, ce qu'offrent les longs traversards réguliers ; les plateaux irréguliers ou surprises conviennent mieux à d'autres méthodes."}]}, {"id": "lead-swing-through", "minutes": 5, "title": "Le swing : de l'arrière, à travers le plateau", "body": ["Dans le swing (swing-through), les canons partent derrière le plateau et le dépassent. En français, on dit généralement « swing », et l'on entend aussi simplement « swing-through ».", "Comment cela se passe, étape par étape. 1) Départ : les canons rejoignent la ligne du plateau derrière lui, sur sa queue. 2) Dépassement : le fusil se déplace plus vite que le plateau, le long de sa ligne, à travers son corps. 3) Tir : on appuie sur la détente quand les canons passent l'avant du plateau, juste devant lui. Comme il y a un petit délai entre la décision et le coup et que le fusil va plus vite que le plateau, les canons sont déjà plus loin devant quand la gerbe part : l'avance réelle au moment du tir est plus grande que l'avance que voit le tireur, qui ne voit que peu ou pas d'écart. 4) Le swing continue après le coup. Le moyen mnémotechnique est « butt, belly, beak, bang » : la queue, le corps, l'avant, le coup. En anglais britannique, on peut entendre « bum » au lieu de « butt » ; traduisez-le par « queue ».", "Points forts : naturel et rapide ; bon pour les débutants, pour les plateaux proches et rapides, pour les plateaux de tête et ceux qui passent par-dessus, et pour les plateaux irréguliers ou surprises.", "Points faibles : une fenêtre très courte pour la détente ; sur les longs traversards, le tireur peut manquer de temps, perdre la ligne ou dépasser le plateau ; ralentir quand les canons atteignent le plateau donne un manqué derrière.", "Les sources ne s'accordent pas sur le nom « CPSA method » : certaines la décrivent comme du swing, alors que l'enseignement actuel de la CPSA est décrit comme du pull-away. Si un moniteur dit « CPSA method », demandez-lui de quelle méthode il parle."], "key_points": ["Les canons partent derrière, sur la ligne du plateau.", "Fusil plus rapide que le plateau : la queue, le corps, l'avant, le coup.", "Détente quand les canons passent l'avant ; l'avance réelle est plus grande que l'avance vue.", "Bon pour les plateaux proches, rapides, de tête et surprises ; plus difficile sur les longs traversards.", "« CPSA method » est ambigu : demandez de quelle méthode il s'agit."], "terms": ["swing-through", "gun-speed", "perceived-lead", "driven-target", "overhead", "follow-through"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}], "sim": {"type": "lead", "method": "swing-through", "preset": "crosser-lr", "muzzle_start": "behind", "gun_speed": "faster", "trigger": "passing-front", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Come from behind, through the bird, and shoot as you see daylight.", "meaning": "Partez derrière le plateau, traversez-le et tirez quand un écart apparaît devant.", "say": "Venez de derrière, traversez le plateau et tirez quand vous voyez le jour."}, {"en": "Butt, belly, beak, bang.", "meaning": "Moyen mnémotechnique : la queue, le corps, l'avant du plateau, puis le coup.", "say": "La queue, le corps, le bec, pan !"}, {"en": "You slowed down as you got to it.", "meaning": "Le fusil a perdu de la vitesse en atteignant le plateau, donc la gerbe est passée derrière.", "say": "Vous avez ralenti en arrivant dessus."}, {"en": "Brush it out and keep going.", "meaning": "Traversez le plateau comme pour l'effacer du ciel, sans vous arrêter.", "say": "Effacez-le et continuez."}], "quiz": [{"q": "D'où partent les canons dans le swing ?", "options": ["Devant le plateau", "Sur le bord avant du plateau", "D'un point fixe au point de casse", "Derrière le plateau, sur sa ligne"], "answer": 3, "why": "Le swing part de derrière et dépasse le plateau ; partir devant, c'est l'avance maintenue, un point fixe, c'est l'embuscade."}, {"q": "Pourquoi un tireur en swing voit-il peu ou pas d'avance ?", "options": ["Les plateaux sont toujours plus lents", "La vitesse du fusil crée l'avance", "Le règlement interdit un écart visible", "Le tireur ferme les deux yeux"], "answer": 1, "why": "Le fusil va plus vite que le plateau : entre la décision et le coup, il passe devant de lui-même."}, {"q": "Un moniteur dit « bum, belly, beak, bang ». Comment traduire « bum » ?", "options": ["Par « queue »", "Par un mot grossier, littéralement", "Par « boum » (un bruit)", "En l'omettant complètement"], "answer": 0, "why": "Il désigne la queue du plateau ; le neutre « queue » garde le sens et le rythme du moyen mnémotechnique."}]}, {"id": "lead-pull-away", "minutes": 5, "title": "Le pull-away : dessus, avec lui, on décroche, on tire", "body": ["Dans le pull-away (en français parfois « départ sur le plateau » ou « partir du plateau »), les canons rejoignent d'abord le plateau, puis s'en détachent vers l'avant. C'est une méthode largement enseignée par les moniteurs britanniques modernes, souvent appelée aujourd'hui « CPSA method ».", "Comment cela se passe, étape par étape. 1) « On it » (dessus) : le fusil est épaulé sur le plateau ou sur son bord avant ; les canons le touchent sur sa ligne. 2) « With it » (avec lui) : les canons suivent le plateau un instant à sa vitesse, en épousant sa ligne et son allure. 3) « Pull away » (on décroche) : le fusil accélère en douceur vers l'avant jusqu'à ce que la bonne image d'avance apparaisse. 4) « Shoot » (on tire) : on appuie sur la détente pendant que le fusil accélère ou bouge encore. 5) Accompagnement : le fusil continue après le coup.", "Points forts : suivre d'abord le plateau permet au tireur d'évaluer sa vitesse, sa distance et sa ligne avant de s'engager ; la ligne est donc bonne. La méthode convient aux plateaux longs, en biais et montants. Grâce à l'accélération, l'avance perçue est plus petite qu'en avance maintenue.", "Points faibles : l'accélération nécessaire varie d'un plateau à l'autre, il faut donc de la pratique pour la sentir ; suivre trop longtemps devient du « riding the target » (plateau trop suivi), et interrompre la poussée donne un manqué derrière.", "Les moniteurs disent « touch it and go » (touchez-le et partez), « mount on it and push out » (épaulez dessus et poussez devant), ou le rythme en quatre temps « on it, with it, pull away, shoot ». Gardez ce rythme en quatre temps quand vous traduisez : il compte plus que les mots exacts."], "key_points": ["Les canons partent sur le plateau (ou sur son bord avant).", "On suit à sa vitesse, puis on accélère devant.", "Détente pendant que le fusil avance encore ; puis accompagnement.", "Bon contrôle de la ligne ; convient aux plateaux longs, en biais et montants.", "Gardez le rythme en quatre temps en traduisant."], "terms": ["pull-away", "insertion-point", "gun-speed", "perceived-lead", "quartering-away", "follow-through"], "sources": [{"title": "CPSA — How to hit series (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/how-to-hit-series-3"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "muzzle_start": "on-target", "gun_speed": "equal-then-faster", "trigger": "during-acceleration", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "On it, with it, pull away, shoot.", "meaning": "Rejoignez le plateau, suivez-le, accélérez devant, tirez.", "say": "Dessus, avec lui, on décroche, on tire."}, {"en": "Touch it and go.", "meaning": "Touchez le plateau avec les canons et commencez immédiatement à passer devant.", "say": "Touchez-le et partez."}, {"en": "You rode it too long.", "meaning": "Le tireur a suivi le plateau trop longtemps avant de décrocher et a perdu la ligne ou le moment.", "say": "Vous l'avez suivi trop longtemps."}, {"en": "Mount on it and push out a bit more.", "meaning": "Épaulez sur le plateau, puis passez un peu plus loin devant avant de tirer.", "say": "Épaulez dessus et poussez un peu plus devant."}], "quiz": [{"q": "Dans le pull-away, que se passe-t-il juste avant l'appui sur la détente ?", "options": ["Le fusil s'arrête sur le plateau", "Le fusil accélère devant le plateau", "Le fusil descend sous le plateau", "Le fusil attend au point de casse"], "answer": 1, "why": "Le pull-away lui-même est l'accélération vers l'avant ; le coup part pendant que le fusil avance encore."}, {"q": "Le moniteur dit « You rode it too long ». Qu'est-ce qui n'a pas marché ?", "options": ["Il est resté trop longtemps sur le poste avant d'appeler", "Il a épaulé beaucoup trop tôt", "Il l'a suivi trop longtemps avant de décrocher", "Le pulleur a lancé le plateau en retard"], "answer": 2, "why": "« Riding the target », c'est suivre le plateau trop longtemps : il ralentit, tombe ou s'échappe, et la ligne est perdue."}, {"q": "Par rapport à l'avance maintenue, l'avance perçue en pull-away est généralement…", "options": ["plus petite, car l'accélération ajoute de l'avance", "plus grande, car le fusil part sur le plateau", "toujours exactement double", "nulle sur tous les plateaux"], "answer": 0, "why": "La brève accélération emporte le fusil vers l'avant pendant le délai du coup : il faut donc voir moins d'écart."}]}, {"id": "lead-ambush-instinctive", "minutes": 5, "title": "L'embuscade et le tir instinctif", "body": ["L'embuscade (ambush, spot shooting ; en français on peut parler de « tir d'interception » ou dire « attendre le plateau ») est le contraire d'un swing. 1) Les canons sont placés en un point devant le plateau, sur sa ligne, près du point de casse. 2) Ils attendent, avec peu ou pas de mouvement. 3) On appuie sur la détente avant que le plateau arrive à cet endroit : la réaction du tireur et le trajet des plombs prennent du temps, et le plateau vole alors dans la gerbe. Tirer seulement quand le plateau arrive à cet endroit envoie la gerbe derrière lui.", "Comme habitude générale, typique des tireurs non formés, elle n'est pas fiable : le fusil est immobile et le timing doit être parfait. Mais une embuscade délibérée est parfois le bon choix : un plateau qu'il faut prendre très vite, ou un rabbit visible seulement dans une courte trouée entre des buissons. Un geste voisin, sur les battues vues par la tranche au sommet de leur vol, est le « collapse » : attendre très près du point de casse et faire un mouvement minimal. Le plateau doit toujours être cassé là où l'arbitre peut le voir.", "Le tir instinctif signifie aucune avance consciente. Le tireur garde un regard précis sur le plateau et laisse les mains suivre ; le swing et l'épaulé se font ensemble, et le coup part quand le fusil arrive au visage. L'école classique est celle associée à l'armurier anglais Robert Churchill, populaire au tir de chasse.", "Beaucoup de grands tireurs de Parcours de Chasse – Sporting™ mélangent les méthodes et choisissent selon le plateau. « Which method for this one? » (quelle méthode pour celui-ci ?) est une question normale à l'entraînement."], "key_points": ["Embuscade : canons immobiles en un point devant ; tirer avant que le plateau y arrive, pour qu'il vole dans la gerbe.", "Peu fiable comme habitude, utile délibérément (plateaux très rapides, courtes trouées).", "« Collapse » : mouvement minimal près du point de casse sur les battues vues par la tranche.", "Instinctif : aucune avance consciente, regard précis, épaulé et swing ensemble (école Churchill).", "Les bons tireurs choisissent la méthode selon le plateau."], "terms": ["ambush", "instinctive-shooting", "hard-focus", "break-point", "battue", "rabbit"], "sources": [{"title": "Wikipedia — Clay pigeon shooting (methods)", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}, {"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "Shotgun Life — Wingshooting schools of England", "url": "https://www.shotgunlife.com/travel/places-to-shoot/wingshooting-schools-of-england-3.html"}], "sim": {"type": "lead", "method": "ambush", "preset": "rabbit", "muzzle_start": "at-break-point", "gun_speed": "none-or-minimal", "trigger": "before-target-arrives", "follow_through": false}, "rule_refs": [{"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "You're ambushing it — keep the gun moving with the target.", "meaning": "Le tireur attend en un point ; le moniteur veut ici une méthode en mouvement.", "say": "Vous l'attendez en embuscade : gardez le fusil en mouvement avec le plateau."}, {"en": "Ambush this one in the gap.", "meaning": "Attendez délibérément à l'ouverture et tirez juste avant que le plateau atteigne votre point, pour qu'il vole dans la gerbe.", "say": "Celui-ci, attendez-le dans la trouée."}, {"en": "Don't think about the lead, just look at the bird and let the gun go to it.", "meaning": "Tirez d'instinct : concentrez-vous sur le plateau et laissez les mains suivre.", "say": "Ne pensez pas à l'avance, regardez simplement le plateau et laissez le fusil y aller."}, {"en": "Hold right on the break point and just collapse onto it.", "meaning": "Placez les canons presque au point de casse et ne faites qu'un tout petit mouvement quand la battue arrive.", "say": "Attendez juste sur le point de casse et laissez-vous simplement tomber dessus."}], "quiz": [{"q": "Qu'est-ce qui caractérise l'embuscade (spot shooting) ?", "options": ["Le fusil pivote plus vite que le plateau", "Le fusil attend en un point devant le plateau", "Le fusil suit le plateau, puis accélère", "Le fusil part derrière le plateau, sur sa ligne"], "answer": 1, "why": "L'embuscade, c'est peu ou pas de swing : les canons attendent sur la ligne et le plateau vole dans la gerbe."}, {"q": "Quand une embuscade délibérée peut-elle être un bon choix ?", "options": ["Sur chaque traversard long et régulier", "Jamais : le règlement l'interdit", "Seulement en Compak® Sporting, jamais en Sporting™", "Sur un rabbit visible seulement dans une courte trouée"], "answer": 3, "why": "Quand le plateau n'est visible que brièvement, il n'y a pas le temps de swinguer : attendre à la trouée peut fonctionner. Aucune règle n'interdit une méthode."}, {"q": "Qu'est-ce que le tir instinctif ?", "options": ["Un regard précis sur le plateau, sans avance consciente", "Tirer sans lunettes de protection", "Tirer à la hanche, sans épauler", "Attendre près du lanceur pour chaque plateau"], "answer": 0, "why": "Le tir instinctif repose sur la coordination œil-main ; il se pratique toujours fusil à l'épaule, comme l'exige le règlement."}]}, {"id": "lead-how-coaches-say-it", "minutes": 6, "title": "Comment les moniteurs expriment l'avance, et comment la traduire", "body": ["Les unités. Les moniteurs britanniques et américains parlent en pieds et en yards : « give it four foot » (anglais britannique pour quatre pieds), « two feet in front » (deux pieds devant). Les moniteurs européens utilisent les mètres. Un pied fait environ 30 cm, un yard environ 0,9 m. Mais un chiffre d'avance est l'image du moniteur, pas une mesure : gardez donc son chiffre et son unité. Ne convertissez jamais au milieu d'une consigne ; si le tireur le demande, expliquez approximativement entre deux plateaux. Les distances jusqu'à un plateau (« it's 30 yards ») peuvent se dire « environ 27 m ».", "Les largeurs de plateau : « half a bird » (un demi-plateau), « a bird's width » (la largeur d'un plateau), « a clay's length » (la longueur d'un plateau). « Bird » désigne le plateau, jamais un vrai oiseau : « un demi-plateau ». Les largeurs de canon : « a barrel's width », « two barrels » désignent l'écart vu à la bouche du canon. Attention : le « two barrels » d'un arbitre signifie que les deux coups sont partis ensemble.", "Les mots relatifs : « more », « less », « a touch more », « double it », « half that », « same lead » (plus, moins, un poil plus, doublez, la moitié, même avance). Gardez-les relatifs et n'inventez jamais de chiffre. « Same lead » est essentiel : le tireur ne doit pas ajouter d'avance.", "Les directions : « in front » (devant) et « behind » (derrière) se rapportent au sens de déplacement du plateau ; « over » et « high », « under » et « low » sont synonymes. Un cadran d'horloge décrit les positions : midi est en haut, trois heures à droite, tel que le tireur le voit. « You hit it at six » (vous l'avez touché à six heures) désigne le bord inférieur ; « it comes from eleven » (il vient de onze heures) donne une direction.", "La méthode : traduisez le chiffre, l'unité, la référence et la direction exactement, brièvement, au rythme du moniteur. Si ce n'est pas clair, posez-lui une question d'un mot : « Feet? » (des pieds ?). En compétition, le coaching est interdit."], "key_points": ["Gardez le chiffre et l'unité du moniteur ; ne convertissez jamais l'avance au milieu d'une consigne.", "Bird = plateau : « half a bird » = « un demi-plateau ».", "Les mots relatifs restent relatifs ; « same lead » doit être traduit.", "Cadran d'horloge : midi en haut, trois heures à droite, tel que le tireur le voit.", "Le « two barrels » d'un arbitre est une double décharge, pas une avance."], "terms": ["lead", "perceived-lead", "clock-face", "double-discharge", "coach"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "Shooting UK — The overhead clay from behind (clock-face pick-up)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-rl", "focus": "lead-units"}, "rule_refs": [{"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Give it four foot.", "meaning": "Donnez l'avance que le moniteur appelle « quatre pieds » ; elle décrit son image, gardez donc son chiffre et son unité.", "say": "Donnez-lui quatre pieds."}, {"en": "Half a bird more.", "meaning": "Ajoutez la moitié de la largeur d'un plateau à l'image d'avance.", "say": "Un demi-plateau de plus."}, {"en": "Double it.", "meaning": "Faites une image d'avance deux fois plus grande que la dernière fois.", "say": "Doublez."}, {"en": "Same lead, just keep it moving.", "meaning": "L'avance était juste ; le manqué vient de l'arrêt du fusil.", "say": "Même avance, gardez-le simplement en mouvement."}, {"en": "You were at two o'clock — a touch low and more in front.", "meaning": "La gerbe était au-dessus et à droite du plateau sur le cadran ; tirez un peu plus bas et donnez un peu plus d'avance.", "say": "Vous étiez à deux heures : un poil plus bas et plus devant."}, {"en": "A barrel's width in front.", "meaning": "Gardez devant le plateau un écart de la largeur du canon, vu à la bouche du canon.", "say": "Une largeur de canon devant."}], "quiz": [{"q": "Le moniteur dit « Give it four foot » à un tireur qui pense en mètres. Que dites-vous ?", "options": ["« Donnez 1,22 mètre »", "« Donnez environ un mètre »", "« Donnez quatre pieds »", "« Donnez quatre mètres »"], "answer": 2, "why": "Un chiffre d'avance est l'image du moniteur ; le convertir au milieu d'une consigne ajoute une fausse précision ou des erreurs, et « quatre mètres » change complètement le sens. Si le tireur le demande, expliquez approximativement entre deux plateaux."}, {"q": "Que signifie « half a bird » ?", "options": ["La moitié de la largeur d'un plateau", "Un plateau cassé", "Un petit oiseau qui vole près du lanceur", "La moitié de la série"], "answer": 0, "why": "Dans le tir sur plateaux, « bird » désigne le plateau : le moniteur demande donc une avance d'une demi-largeur de plateau."}, {"q": "Le moniteur dit « Same lead, keep it moving ». Pourquoi faut-il traduire « same lead » ?", "options": ["C'est une annonce qu'utilise l'arbitre", "Sinon le tireur risque d'ajouter de l'avance et de manquer", "C'est une formule de politesse entre tireurs", "Cela change l'ordre des plateaux"], "answer": 1, "why": "Après un manqué, la plupart des tireurs ajoutent d'eux-mêmes de l'avance ; « same lead » leur dit que la cause était le fusil arrêté, pas l'avance."}]}]}, {"id": "faults", "icon": "search", "title": "Les fautes et comment les moniteurs les diagnostiquent", "intro": "Quand un plateau est manqué, le moniteur nomme le manqué en un ou deux mots, puis la cause. Cette mission vous apprend les mots des manqués et des fautes, ce que chacun signifie vraiment, et comment transmettre le diagnostic du moniteur au tireur rapidement et avec exactitude.", "lessons": [{"id": "faults-behind-in-front", "minutes": 5, "title": "Derrière, devant, dessus, dessous, écorné", "body": ["Chaque manqué a une direction. Un moniteur qui observe derrière le tireur dit d'abord, en général, où est passée la gerbe par rapport au plateau, et seulement ensuite pourquoi. Transmettez-le immédiatement : le tireur se prépare déjà pour le plateau suivant.", "Behind (derrière) signifie que la gerbe est passée derrière un plateau en mouvement : pas assez d'avance, ou un fusil qui a ralenti. C'est le manqué le plus fréquent sur les traversards. In front (devant), c'est l'inverse : trop d'avance, souvent après une correction excessive du tireur. Beaucoup de moniteurs aiment un manqué devant : il montre que le fusil a continué de bouger.", "Over (également « high », « over the top » : dessus) et under (« low » : dessous) décrivent le manqué vertical. Dessus est fréquent sur les plateaux descendants, les rabbits et les rentrants, et souvent lié à la tête qui décolle de la crosse. Dessous est typique des plateaux montants qui grimpent encore au moment du tir.", "Chipped (écorné) signifie que seul un petit morceau s'est détaché. Pour le moniteur, c'est à moitié un compliment, à moitié une correction : le plateau était en bordure de gerbe. Pour l'arbitre, c'est un plateau bon, à condition que le morceau soit visible. Le piège, c'est la poussière : selon le règlement, un plateau qui ne dégage que de la poussière ou de la fumée, sans morceau visible, est perdu. Pourtant, « smoked it » dans l'argot des moniteurs désigne un tir parfait, bien centré (« pulvérisé »), et « dusted it » s'entend dans les deux sens : demandez en cas de doute.", "Respectez l'ordre du moniteur : direction, cause, correction. Si le moniteur dit « behind, you stopped » (derrière, vous vous êtes arrêté), c'est la cause qui compte le plus : un tireur qui n'entend que « derrière » ajoutera de l'avance, ce qui ne guérit pas un fusil arrêté."], "key_points": ["Transmettez d'abord la direction : derrière, devant, dessus, dessous.", "Derrière = trop peu d'avance ou un fusil qui ralentit ; devant = trop d'avance.", "Un éclat visible est un plateau bon pour l'arbitre ; poussière ou fumée seulement = perdu.", "« Smoked it » est un compliment du moniteur, pas la « fumée » du règlement : ne les confondez jamais.", "Respectez l'ordre du moniteur : direction, cause, correction."], "terms": ["lead", "crosser", "dropping-target", "visible-piece", "one", "zero", "miss-behind", "miss-in-front", "miss-over", "miss-under", "chip", "smoke-ball"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}], "coach_says": [{"en": "Behind, give it more.", "meaning": "La gerbe est passée derrière le plateau ; augmentez l'avance.", "say": "Derrière, donnez-lui plus."}, {"en": "Just over the top, it was already dropping.", "meaning": "La gerbe est passée au-dessus parce que le plateau descendait ; tirez plus bas et devant.", "say": "Juste au-dessus, il descendait déjà."}, {"en": "In front this time, good, now a touch less.", "meaning": "Trop d'avance, mais le fusil bougeait ; réduisez légèrement l'avance.", "say": "Devant cette fois, c'est bien ; maintenant, un poil moins."}, {"en": "You just chipped it, a little more in front.", "meaning": "Touché en bordure de gerbe ; un peu plus d'avance le centrera.", "say": "Vous l'avez juste écorné, un peu plus devant."}, {"en": "Smoked it! Same again.", "meaning": "Un tir parfait, bien centré (argot, pas la « fumée » du règlement) ; refaites exactement pareil.", "say": "Pulvérisé ! Pareil."}, {"en": "Behind, but you stopped, so don't just add lead.", "meaning": "La cause est un fusil arrêté ; ajouter de l'avance ne suffira pas.", "say": "Derrière, mais vous vous êtes arrêté : n'ajoutez pas seulement de l'avance."}], "quiz": [{"q": "Le moniteur annonce : « Behind, you stopped! ». Quelle est la partie la plus importante à traduire ?", "options": ["La cause : le fusil s'est arrêté", "Seulement la direction « derrière »", "Rien : le tireur a vu le manqué", "Une demande d'ajouter beaucoup plus d'avance"], "answer": 0, "why": "Ajouter de l'avance ne guérit pas un fusil arrêté ; c'est la cause que le tireur doit corriger."}, {"q": "Un petit morceau, mais bien visible, se détache du plateau. Le moniteur dit « just chipped it ». Comment l'arbitre le compte-t-il ?", "options": ["Perdu, car l'essentiel du plateau a continué sa course", "No bird", "Bon", "Bon seulement si le moniteur est d'accord"], "answer": 2, "why": "Au moins un morceau visible rend le plateau bon, en Sporting™ comme en Compak® Sporting ; l'arbitre décide seul."}, {"q": "Après un plateau cassé, le moniteur crie « Smoked it! ». Que veut-il dire ?", "options": ["Il n'y a eu que de la poussière, donc il est perdu", "Un tir parfait, bien centré", "C'était un plateau flash", "Le tireur devrait changer de cartouches"], "answer": 1, "why": "Dans l'argot des moniteurs, « smoked it » félicite un plateau réduit en poussière ; dans le règlement, poussière ou fumée sans morceau visible = manqué."}]}, {"id": "faults-head-lift-stopping", "minutes": 5, "title": "Tête levée, fusil arrêté, plateau trop suivi, tir visé", "body": ["Après la direction, le moniteur nomme la cause. Quatre causes reviennent à chaque séance d'entraînement, chacune avec son mot court. Apprenez-les par paires : la faute et le remède.", "Head lift (lever la tête) : la joue quitte la crosse au moment du tir ou juste avant, souvent parce que le tireur veut voir le plateau casser. L'œil fait office de hausse : le lever déplace l'image, et la gerbe passe généralement au-dessus. Remède : « head down » (la tête en bas), « cheek on the stock » (la joue sur la crosse), « stay in the gun » (restez dans le fusil).", "Stopping the gun (arrêter le fusil) : les canons s'immobilisent au moment du tir, généralement parce que le tireur vérifie l'avance sur le canon. La gerbe passe derrière. Une version plus légère est le checking : le swing hésite une fraction de seconde. Remède : « keep the gun moving » (gardez le fusil en mouvement), « follow through » (accompagnez), « finish the shot » (allez au bout du tir).", "Riding the target (suivre le plateau trop longtemps) : accompagner le plateau trop longtemps avant de tirer, si bien qu'il ralentit, tombe ou s'éloigne en courbe, et le tireur perd la ligne. Remède : « take it earlier » (prenez-le plus tôt), « commit to it » (engagez-vous). Poking (aussi « aiming », « measuring » : tirer en visant) : pointer lentement le fusil comme une carabine, les yeux sur le guidon au lieu du plateau. C'est typique d'un point de casse trop proche, ou d'une chandelle à son sommet. Remède : « eyes on the clay » (les yeux sur le plateau), « let the gun go » (laissez partir le fusil).", "Les moniteurs nomment souvent la cause avant même que le tireur ait baissé son fusil. Traduisez-la dans le même souffle et avec le même verbe : « you stopped » ne veut pas dire « vous avez manqué ». Un mot comme « aiming » (viser) est presque toujours une critique : n'en faites jamais un conseil du genre « visez mieux »."], "key_points": ["Tête levée : gerbe généralement dessus ; remède : tête en bas, restez dans le fusil.", "Fusil arrêté ou hésitant : gerbe derrière ; remède : gardez le fusil en mouvement, accompagnez.", "Plateau trop suivi : il ralentit ou tombe ; remède : prenez-le plus tôt, engagez-vous.", "Tir visé (poking, aiming) : pointage lent comme à la carabine ; remède : les yeux sur le plateau.", "Traduisez la cause immédiatement, avec le verbe du moniteur."], "terms": ["head-lift", "stopping-the-gun", "follow-through", "break-point", "teal", "checking", "riding-the-target", "poking"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "The Field — Improve your game and clay shooting: 20 top tips", "url": "https://www.thefield.co.uk/shooting/improve-your-game-and-clay-shooting-20-top-tips-45462"}, {"title": "Clay Target Nation — 5 major shooting mistakes", "url": "https://www.claytargetnation-digital.com/articles/5-major-shooting-mistakes"}], "sim": null, "rule_refs": [], "coach_says": [{"en": "You lifted your head, that's why it went over.", "meaning": "La joue a quitté la crosse, donc la gerbe est passée au-dessus du plateau.", "say": "Vous avez levé la tête, c'est pour ça qu'il est passé dessus."}, {"en": "Keep the gun moving, you stopped on it.", "meaning": "Le swing s'est arrêté au moment du tir ; continuez le mouvement à travers et après le tir.", "say": "Gardez le fusil en mouvement, vous vous êtes arrêté dessus."}, {"en": "You checked just before the shot, commit to it.", "meaning": "Une brève hésitation avant de tirer ; décidez et tirez sans ralentir.", "say": "Vous avez hésité juste avant le coup, engagez-vous."}, {"en": "Stop aiming, look at the bird and let the gun go.", "meaning": "Critique : le tireur pointe comme avec une carabine ; concentrez-vous sur le plateau et swinguez librement.", "say": "Arrêtez de viser, regardez le plateau et laissez partir le fusil."}, {"en": "You rode it too long, take it earlier.", "meaning": "Le tireur a suivi le plateau trop longtemps ; cassez-le plus tôt.", "say": "Vous l'avez suivi trop longtemps, prenez-le plus tôt."}, {"en": "Stay in the gun.", "meaning": "Gardez la joue sur la crosse jusqu'après le tir.", "say": "Restez dans le fusil."}], "quiz": [{"q": "Le moniteur dit « You lifted your head ». Où est très probablement passée la gerbe ?", "options": ["Derrière", "Au-dessus", "En dessous", "Devant"], "answer": 1, "why": "L'œil fait office de hausse : quand la tête se lève, la gerbe passe généralement au-dessus."}, {"q": "Un moniteur crie « Stop aiming! ». Que veut-il ?", "options": ["Ne pas pointer comme à la carabine : regarder le plateau et swinguer", "Viser plus précisément", "Cesser le feu immédiatement", "Baisser le fusil"], "answer": 0, "why": "Dans la bouche d'un moniteur, « aiming » est une faute (poking) ; le remède : les yeux sur le plateau et un swing libre."}, {"q": "« You rode it too long » signifie…", "options": ["Le tireur a tiré trop tôt", "Le lanceur était trop lent", "Le tireur est parti trop loin derrière", "Le tireur a suivi le plateau trop longtemps avant de tirer"], "answer": 3, "why": "Riding the target, c'est suivre le plateau trop longtemps : il ralentit ou tombe, et la ligne est perdue."}]}, {"id": "faults-mount-errors", "minutes": 5, "title": "Erreurs d'épaulé : tardif, visage au fusil, fusil penché", "body": ["Beaucoup de manqués commencent avant le swing, dans l'épaulé : le mouvement qui amène le fusil à la joue et à l'épaule. Les mots du moniteur pour cela sont courts et physiques.", "Late mount (épaulé tardif) : le fusil arrive à l'épaule après le moment où le coup aurait dû partir, si bien que le tireur se précipite ou tire avant que la joue soit en place. La faute inverse est un épaulé terminé trop tôt, après lequel le fusil attend, immobile et lourd. Remède : « move, mount, shoot » (bouger, épauler, tirer) : les canons partent avec le plateau et l'épaulé s'achève au moment du coup.", "Face to the gun (le visage au fusil) : au lieu de monter la crosse jusqu'au visage, le tireur baisse la tête pour aller la chercher. L'œil se retrouve chaque fois à un endroit différent, et le recul frappe la joue. Les moniteurs disent : « bring the gun to your face, not your face to the gun » (le fusil au visage, pas le visage au fusil). Une crosse qui se pose sur le bras au lieu du creux de l'épaule fait mal aussi.", "Canting (fusil penché) : le fusil est incliné sur le côté au moment du tir, et la gerbe dérive hors de la ligne. Cela s'accompagne souvent d'une épaule qui tombe. Remède : « keep the gun level » (gardez le fusil droit), « turn from the hips » (pivotez depuis les hanches).", "Dans les compétitions FITASC de Parcours de Chasse – Sporting™, le fusil ne peut pas être épaulé avant l'apparition du plateau : « pre-mount this one » (épaulez d'avance pour celui-ci) n'est donc qu'un exercice d'entraînement. Épauler trop tôt en compétition de Sporting™ vaut un avertissement et un carton jaune. En Compak® Sporting, le fusil peut déjà être à l'épaule à l'appel. Traduisez l'exercice comme un exercice et n'ajoutez rien de votre part."], "key_points": ["Épaulé tardif : un tir précipité ; remède : bouger, épauler, tirer.", "Visage au fusil : l'œil se déplace et le recul fait mal ; amenez le fusil au visage.", "Fusil penché : la gerbe dérive hors de la ligne ; gardez le fusil droit, pivotez depuis les hanches.", "L'épaulé d'avance est un exercice : interdit avant l'apparition du plateau en compétition de Sporting™, autorisé à l'appel en Compak® Sporting."], "terms": ["gun-mount", "ready-position", "recoil", "comb", "gun-fit", "dry-mounting", "late-mount", "canting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Bring the gun to your face, not your face to the gun.", "meaning": "Montez la crosse jusqu'à la joue ; ne baissez pas la tête vers la crosse.", "say": "Le fusil au visage, pas le visage au fusil."}, {"en": "Move, mount, shoot, all in one.", "meaning": "Commencez à bouger avec le plateau, terminez l'épaulé au moment du tir, en un seul geste fluide.", "say": "Bouger, épauler, tirer, tout en un."}, {"en": "You canted the gun, keep it level.", "meaning": "Le fusil était incliné sur le côté au moment du tir.", "say": "Vous avez penché le fusil, gardez-le droit."}, {"en": "Mount on the line.", "meaning": "Le fusil doit monter déjà sur la trajectoire du plateau.", "say": "Épaulez sur la ligne."}, {"en": "Pre-mount this one, just for practice.", "meaning": "Exercice d'entraînement avec le fusil déjà à l'épaule ; interdit en compétition de Sporting™.", "say": "Épaulez d'avance pour celui-ci, juste pour l'entraînement."}], "quiz": [{"q": "À l'entraînement, un moniteur dit à un tireur qui prépare une compétition FITASC de Sporting™ : « Pre-mount this one. » Qu'est-ce qui est vrai ?", "options": ["C'est autorisé dans toutes les compétitions FITASC", "L'interprète doit refuser de le traduire", "C'est un exercice d'entraînement ; en compétition de Sporting™, le fusil ne peut pas être épaulé avant l'apparition du plateau", "Cela signifie épauler après le tir"], "answer": 2, "why": "Le Sporting™ impose la position d'attente fusil bas jusqu'à l'apparition du plateau ; un épaulé d'avance en compétition vaut un avertissement avec carton jaune."}, {"q": "« You canted the gun » signifie…", "options": ["Le fusil était incliné sur le côté au moment du tir", "Le fusil a été épaulé trop tard", "Le fusil s'est arrêté", "Le cran de sûreté était mis"], "answer": 0, "why": "Le canting est une inclinaison latérale du fusil, qui fait dériver la gerbe hors de la ligne."}, {"q": "Quelle consigne corrige « face to the gun » ?", "options": ["Appuyer la tête plus fort vers le bas", "Amener le fusil au visage", "Fermer un œil", "Tenir le fusil plus bas sur le bras"], "answer": 1, "why": "La crosse doit monter jusqu'au visage, pour que l'œil soit chaque fois au même endroit."}]}, {"id": "faults-pairs-transition", "minutes": 5, "title": "Les doublés : le second plateau", "body": ["Sur un doublé (pair, double), beaucoup de tireurs cassent le premier plateau et manquent le second. Le moniteur parle alors de transition, le passage du premier plateau au second, et de récupération (recovery), la reprise du contrôle du fusil et de la tête après le premier coup.", "La règle d'or est « eyes first, then the gun » : les yeux d'abord, ensuite le fusil. Les yeux quittent le premier plateau cassé et trouvent le second ; le fusil suit. Un tireur qui regarde le premier plateau casser, ou qui fait pivoter le fusil avant d'avoir trouvé le second, perd du temps. Les moniteurs disent « eyes to the second » (les yeux sur le second) ou montrent simplement du doigt.", "La récupération : le recul relève les canons et parfois la tête. « Let the gun recover, then go » signifie : la joue de nouveau en place et le fusil de nouveau sur la ligne avant d'aller chercher le second plateau. Une bonne position, le poids vers l'avant, accélère la récupération.", "La préparation : en lisant le doublé, le moniteur décide quel plateau prendre en premier et où le casser pour que le second soit facile à prendre. Phrases typiques : « take the dropping one first » (prenez d'abord celui qui descend), « break the first early » (cassez le premier tôt), « stick to the plan » (tenez-vous au plan). Un tireur qui change l'ordre sur le poste « went for the wrong one » (est parti sur le mauvais).", "Le règlement compte ici. En Parcours de Chasse – Sporting™, la position du fusil est libre entre les deux plateaux de tout doublé, et le tireur dispose de deux cartouches pour un doublé, qui peuvent toutes deux être tirées sur le même plateau. En Compak® Sporting, une seule cartouche par plateau est autorisée dans un doublé. N'expliquez pas vous-même les pénalités : traduisez le moniteur et laissez les questions de règlement à l'arbitre."], "key_points": ["Les yeux d'abord, ensuite le fusil.", "Récupération : la joue de nouveau sur la crosse et le fusil sur la ligne avant le second plateau.", "Le moniteur prévoit l'ordre et les points de casse d'un doublé en le lisant.", "Sporting™ : position du fusil libre entre les plateaux, et les deux cartouches peuvent être tirées sur un même plateau ; Compak® Sporting : une cartouche par plateau."], "terms": ["double", "double-on-report", "simultaneous-double", "rafale-double", "recoil", "stance", "dropping-target", "transition", "recovery"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Eyes first to the second bird, then the gun.", "meaning": "Trouvez le second plateau avec les yeux avant de bouger le fusil.", "say": "Les yeux d'abord sur le second plateau, ensuite le fusil."}, {"en": "Let the gun recover, then go to the second.", "meaning": "Après le recul, replacez le fusil et la joue avant le second coup.", "say": "Laissez le fusil récupérer, puis allez sur le second."}, {"en": "Take the dropping one first.", "meaning": "Tirez d'abord le plateau qui va disparaître ou tomber le plus tôt.", "say": "Prenez d'abord celui qui descend."}, {"en": "Don't watch the first one break.", "meaning": "Passez immédiatement les yeux sur le second plateau.", "say": "Ne regardez pas casser le premier."}, {"en": "You went for the wrong one first, stick to the plan.", "meaning": "Le tireur a changé l'ordre prévu ; c'est une remarque technique, pas une infraction au règlement.", "say": "Vous êtes d'abord parti sur le mauvais, tenez-vous au plan."}], "quiz": [{"q": "Que signifie « eyes first, then the gun » sur un doublé ?", "options": ["Fermer les yeux après le premier coup", "Regarder le canon avant le second coup", "Épauler avant d'appeler le doublé", "Trouver le second plateau avec les yeux avant d'y amener le fusil"], "answer": 3, "why": "Dans une bonne transition, les yeux mènent et le fusil suit."}, {"q": "Dans un doublé de Compak® Sporting, le tireur manque le premier plateau et veut tirer aussi la deuxième cartouche sur lui. Est-ce autorisé ?", "options": ["Oui, comme en Sporting™", "Oui, mais seulement sur un doublé simultané", "Non : dans un doublé de Compak® Sporting, une seule cartouche par plateau est autorisée", "Seulement avec l'autorisation de l'arbitre"], "answer": 2, "why": "Le Compak® Sporting interdit de doubler le premier plateau d'un doublé ; le Sporting™ autorise les deux cartouches sur un même plateau."}, {"q": "Dans un doublé de Sporting™, le tireur peut-il baisser le fusil entre le premier et le second plateau ?", "options": ["Oui, la position du fusil est libre entre les deux plateaux", "Non, le fusil doit rester épaulé", "Seulement sur un doublé coup de fusil", "Seulement si l'arbitre l'autorise"], "answer": 0, "why": "La position libre s'applique entre les plateaux de tout doublé, mais pas avant le premier."}]}, {"id": "faults-reading-the-coach", "minutes": 5, "title": "Comprendre le moniteur : consignes courtes et signes", "body": ["Sur le poste, un moniteur parle par fragments : « Behind. » « Head. » « More. » « Again. » Il n'y a que quelques secondes entre les plateaux : la brièveté est voulue. Votre traduction doit être tout aussi courte ; une longue phrase arrive après l'appel suivant.", "Beaucoup de moniteurs interrogent avant d'expliquer : « Where did it go? » (Où est-il passé ?) ou « What did you see? » (Qu'avez-vous vu ?). C'est une question pédagogique, pas un test pour l'interprète. Traduisez la question, laissez le tireur répondre, et retraduisez sa réponse exactement, même si elle semble fausse. Le moniteur a besoin de savoir ce que le tireur a perçu.", "Les signes de la main en disent long. Les plus courants : les mains qui s'écartent ou se rapprochent pour plus ou moins d'avance, une main à plat qui descend pour « plus bas », une tape sur la joue pour « la tête en bas », un doigt qui trace la ligne du plateau, un pouce levé pour « pareil ». Les signes varient d'un moniteur à l'autre : mettez-vous d'accord avant la séance, et ne traduisez pas un geste que le tireur a déjà vu.", "Certains mots ne sont que rythme et encouragement : « commit » (engagez-vous), « trust it » (faites-vous confiance), « smooth » (en douceur), « good, same again » (bien, pareil). Gardez le ton. « Bad luck » (pas de chance) après un manqué est une gentillesse, pas un commentaire sur l'arbitre.", "En compétition, le coaching est interdit : l'arbitre donne un carton jaune au concurrent et fait sortir le moniteur de la zone de tir. Le règlement ne dit pas si un interprète peut relayer les conseils d'un moniteur pendant une compétition : c'est une question ouverte pour la FITASC. La pratique prudente : en compétition, n'interprétez que pour l'arbitre, le jury et l'organisateur."], "key_points": ["Les moniteurs parlent par fragments ; traduisez tout aussi brièvement.", "« Where did it go? » est une question pédagogique : traduisez exactement la réponse du tireur.", "Mettez-vous d'accord sur les signes de la main avant la séance.", "Pas de coaching en compétition ; n'interprétez que pour l'arbitre, le jury et l'organisateur."], "terms": ["coach", "referee", "jury", "yellow-card", "hand-signal"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Where did it go?", "meaning": "Le moniteur demande où le tireur pense que la gerbe est passée ; une question pédagogique.", "say": "Où est-il passé ?"}, {"en": "What did you see?", "meaning": "Décrivez l'image au moment du tir.", "say": "Qu'avez-vous vu ?"}, {"en": "More.", "meaning": "Dans le contexte, presque toujours « plus d'avance ».", "say": "Plus."}, {"en": "Good, same again.", "meaning": "Refaites exactement ce que vous venez de faire.", "say": "Bien, pareil."}, {"en": "Trust it, commit to it.", "meaning": "Arrêtez d'hésiter ; décidez et tirez.", "say": "Faites-vous confiance, engagez-vous."}, {"en": "Bad luck.", "meaning": "Marque de sympathie après un manqué ; pas une plainte contre l'arbitre.", "say": "Pas de chance."}], "quiz": [{"q": "Le moniteur demande au tireur « Where did it go? ». Que doit faire l'interprète ?", "options": ["Répondre à la place du tireur", "Traduire la question, puis la réponse du tireur exactement", "Expliquer le manqué avec ses propres mots", "Ne rien dire : c'est une question rhétorique"], "answer": 1, "why": "Le moniteur veut la perception du tireur lui-même : la réponse doit lui parvenir sans modification."}, {"q": "Pendant une compétition, le moniteur du tireur vous demande de transmettre : « Give the next one more lead. » Quelle est la pratique prudente ?", "options": ["Le transmettre discrètement", "Le transmettre seulement entre les postes", "Ne pas relayer de coaching en compétition ; n'interpréter que pour l'arbitre, le jury et l'organisateur", "Demander d'abord aux autres tireurs"], "answer": 2, "why": "Le coaching en compétition est interdit, et le règlement ne dit pas si un interprète peut le relayer ; rester en dehors protège le tireur."}, {"q": "Que se passe-t-il selon le règlement si l'arbitre estime qu'un concurrent reçoit du coaching ?", "options": ["Carton jaune pour le concurrent ; le moniteur est envoyé hors de la zone de tir", "Rien : le coaching est autorisé", "Le plateau est répété", "Toute la planche est disqualifiée"], "answer": 0, "why": "Les deux règlements donnent un carton jaune au concurrent, avec des pénalités plus lourdes en cas de récidive, et écartent le moniteur."}]}]}, {"id": "sporting", "icon": "flag", "title": "Le règlement du Parcours de Chasse – Sporting™", "intro": "Le Parcours de Chasse – Sporting™ est la discipline FITASC qui imite la chasse en terrain naturel. Cette mission vous guide dans son règlement tel que l'arbitre l'applique : séries et postes, départ fusil bas, plateaux simples et doublés, présentation des plateaux, incidents de tir et délais. Tout ce qui suit est une reformulation ; les références au règlement ouvrent le guide des règles de ClayArena.", "lessons": [{"id": "sporting-rounds-stands", "minutes": 5, "title": "Séries, postes et ordre de tir", "body": ["Une compétition de Parcours de Chasse – Sporting™ se compte en séries de 25 plateaux. Une épreuve internationale se tire sur 200 plateaux, soit huit séries ; chaque série se tire sur un parcours (un ensemble de postes de tir) ou une ligne.", "Chaque parcours donne 15 plateaux simples et 5 doublés. Le nombre de postes et de lanceurs dépend du système : l'ancien système utilise 5 lanceurs pour 3 postes, tandis que les lignes du nouveau système ont 4 ou 5 postes avec 3 ou 4 lanceurs chacun. Les lanceurs sont désignés par les lettres A, B, C, D de gauche à droite, vus depuis le poste. Le menu placé devant le poste les énumère dans l'ordre de tir, avec les éventuels plateaux spéciaux : 90, 70 ou 60 mm, battue, rabbit.", "Le poste lui-même est un carré de 1 m ou un cercle de 1 m de diamètre. Chaque trajectoire a une catégorie de difficulté : A (un tireur moyen en casse plus de 80 %), B (de 60 à 80 %) ou C (de 40 à 60 %).", "Les tireurs font le tour en planches de six au maximum, constituées par tirage au sort. À chaque poste, tout le monde tire d'abord les plateaux simples, puis les doublés, et l'ordre de tir tourne à chaque poste, puis de nouveau pour les doublés. Les autres attendent à proximité, sans déranger celui qui tire.", "L'arbitre, ou une personne placée sous son contrôle, tient la feuille de marque et note chaque plateau sous la lettre de son lanceur. En quittant chaque poste, chaque tireur vérifie son score ; un désaccord doit être soumis immédiatement à l'arbitre, dont la décision est définitive."], "key_points": ["Série = 25 plateaux sur un parcours : 15 simples + 5 doublés ; épreuve internationale = 200 plateaux.", "Lanceurs A, B, C, D de gauche à droite vus depuis le poste ; le menu donne l'ordre et les plateaux spéciaux.", "Planches de six au maximum ; d'abord les simples, puis les doublés ; l'ordre tourne.", "Vérifiez votre score en quittant chaque poste ; l'arbitre décide."], "terms": ["round", "layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "squad", "rotation", "score-sheet", "referee", "difficulty-class"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}], "coach_says": [{"en": "Singles first, then doubles.", "meaning": "L'ordre standard à chaque poste.", "say": "D'abord les simples, ensuite les doublés."}, {"en": "Read the menu: the traps go A, B, C.", "meaning": "Le panneau du menu énumère les lanceurs dans l'ordre où ils seront tirés.", "say": "Lisez le menu : les lanceurs vont A, B, C."}, {"en": "Next shooter.", "meaning": "L'arbitre appelle la personne suivante sur le poste.", "say": "Tireur suivant."}, {"en": "Check your score before you leave the stand.", "meaning": "Tout désaccord doit être soulevé maintenant, pas plus tard.", "say": "Vérifiez votre score avant de quitter le poste."}], "quiz": [{"q": "Combien de plateaux donne un parcours de Sporting™, et comment se répartissent-ils ?", "options": ["20 : 10 simples et 5 doublés", "25 : uniquement des simples", "25 : 15 simples et 5 doublés", "50 : 25 simples et 25 doublés"], "answer": 2, "why": "Tous les types de parcours donnent 15 simples plus 5 doublés, soit 25 plateaux."}, {"q": "Dans quel ordre une planche tire-t-elle à un poste ?", "options": ["D'abord les doublés, puis les simples", "Tout le monde tire d'abord les simples, puis les doublés, et l'ordre tourne", "Chaque tireur tire tout le parcours d'un coup", "Les tireurs choisissent librement"], "answer": 1, "why": "Les simples viennent d'abord, puis les doublés, à tour de rôle, sauf décision contraire du jury."}, {"q": "En quittant le poste, un tireur voit qu'un plateau touché a été noté comme manqué. Que doit-il faire ?", "options": ["Attendre la fin de la série et faire appel auprès du jury", "Corriger lui-même la feuille", "Demander à la planche de voter", "Le signaler immédiatement à l'arbitre ; l'arbitre décide"], "answer": 3, "why": "Les scores se vérifient en quittant chaque poste ; l'arbitre décide seul, et il n'y a pas d'appel ensuite."}]}, {"id": "sporting-gun-position", "minutes": 5, "title": "Le départ fusil bas", "body": ["La règle la plus visible du Parcours de Chasse – Sporting™ est le départ fusil bas. Avant d'appeler, le tireur se tient les deux pieds à l'intérieur du poste, le talon de la crosse touchant le corps et le point supérieur arrière de la crosse sous une ligne tracée sur le gilet. Cette position d'attente est maintenue jusqu'à ce que le plateau soit lancé et visible.", "La ligne est tracée sur le gilet ou la veste 25 cm sous l'axe des épaules, parallèlement à lui, d'une couleur contrastant avec le gilet pour que l'arbitre puisse la voir. La règle s'applique à tous les types de crosse, busc réglable compris.", "Le fusil ne peut monter qu'à l'apparition du plateau. Chaque plateau, rabbits compris, se tire fusil à l'épaule ; tirer à la hanche est interdit. Entre le premier et le second plateau de tout doublé, la position du fusil est libre, mais avant le premier plateau, la position d'attente s'applique.", "Pénalités : la première fois qu'un tireur appelle dans une mauvaise position ou épaule avant l'apparition du plateau, l'arbitre donne un avertissement verbal avec carton jaune. Toute nouvelle infraction sur le même parcours entraîne un carton rouge, et le plateau est compté zéro sur un simple, zéro et No bird sur un doublé coup de fusil, zéro et zéro sur un doublé simultané ou une rafale.", "Épauler et suivre la ligne imaginaire avant d'appeler (simulacre de tir) est également interdit : d'abord un avertissement, puis un zéro. Si un moniteur fait travailler un départ fusil épaulé avant une épreuve de Parcours de Chasse – Sporting™, traduisez aussi le mot « exercice »."], "key_points": ["Avant l'appel : les deux pieds dans le poste, crosse au contact du corps, haut de la crosse sous la ligne du gilet.", "La ligne du gilet est à 25 cm sous l'axe des épaules, d'une couleur contrastée.", "N'épauler qu'à l'apparition du plateau ; toujours tirer fusil à l'épaule ; position libre entre les plateaux d'un doublé.", "Première infraction : avertissement + carton jaune ; la suivante sur le même parcours : carton rouge et plateau compté selon le tableau."], "terms": ["ready-position", "gun-mount", "shooting-stand", "shooting-vest", "adjustable-comb", "mock-shooting", "yellow-card", "red-card", "jacket-line"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}], "coach_says": [{"en": "Gun down, please.", "meaning": "L'arbitre : ramenez la crosse sous la ligne du gilet avant d'appeler.", "say": "Fusil bas, s'il vous plaît."}, {"en": "Your stock was above the line. This is a warning.", "meaning": "Première infraction à la position du fusil : avertissement verbal avec carton jaune.", "say": "Votre crosse était au-dessus de la ligne. C'est un avertissement."}, {"en": "Don't mount before the target appears.", "meaning": "Le fusil ne peut monter qu'une fois le plateau visible.", "say": "N'épaulez pas avant l'apparition du plateau."}, {"en": "Red card, zero.", "meaning": "Une récidive sur le même parcours ; le plateau simple est perdu.", "say": "Carton rouge, zéro."}], "quiz": [{"q": "Premier poste. Un tireur appelle avec le fusil déjà à l'épaule. C'est sa première infraction sur ce parcours. Quelle est la décision de l'arbitre ?", "options": ["Le plateau est compté zéro", "Un avertissement verbal avec carton jaune", "No bird et rien d'autre", "Exclusion"], "answer": 1, "why": "La première infraction à la position du fusil est un avertissement verbal accompagné d'un carton jaune."}, {"q": "Même parcours, deux postes plus loin : le même tireur appelle un plateau simple avec la crosse au-dessus de la ligne du gilet. Décision ?", "options": ["Un nouveau carton jaune", "No bird", "Carton rouge, et le plateau est répété", "Carton rouge, et le plateau simple est compté zéro"], "answer": 3, "why": "Après l'avertissement, une nouvelle infraction sur le même parcours vaut un carton rouge : zéro sur un simple."}, {"q": "Doublé coup de fusil. Après avoir cassé le premier plateau, le tireur baisse légèrement le fusil avant le second. Décision ?", "options": ["Autorisé : la position du fusil est libre entre les deux plateaux", "Carton jaune", "Zéro sur le second plateau", "No bird"], "answer": 0, "why": "La position libre s'applique entre les plateaux de tout doublé ; la position d'attente n'est exigée qu'avant le premier."}]}, {"id": "sporting-singles-doubles", "minutes": 5, "title": "Plateaux simples et doublés", "body": ["Un plateau simple est un plateau issu d'un seul lanceur. En Parcours de Chasse – Sporting™, le tireur peut tirer deux cartouches dessus : un manqué au premier coup peut donc encore être rattrapé au second. Chaque plateau simple doit laisser le temps de tirer deux coups.", "Un doublé se compose de deux plateaux, et le tireur ne dispose que de deux cartouches pour lui ; les deux peuvent être tirées sur le même plateau. Il en existe trois types. Coup de fusil : le second plateau part de 0 à 3 secondes après le coup tiré sur le premier, déclenché par ce coup. Simultané : les deux partent au même instant, d'un ou deux lanceurs. Rafale : deux plateaux du même lanceur sur la même trajectoire, le second aussi vite que le lanceur se recharge. Dans les doublés simultanés et les rafales, les plateaux peuvent être tirés dans n'importe quel ordre. Les doublés n'utilisent que des plateaux déjà présentés en simples depuis le même poste.", "Décisions que l'arbitre doit souvent prendre : si un seul coup casse les deux plateaux d'un doublé, quel qu'il soit, les deux comptent, bon et bon. Si le tireur ne tire pas sur une rafale ou un doublé simultané sans motif valable, c'est zéro et zéro.", "Sur un doublé coup de fusil, un premier plateau irrégulier signifie que le doublé est répété ; si le premier plateau ou ses morceaux cassent le second avant le second coup, ou si le second est irrégulier, le doublé est répété et le premier résultat est conservé. Sur les doublés simultanés et les rafales, un plateau irrégulier signifie une répétition sans aucun résultat enregistré.", "Conseil : transmettez le résultat d'un doublé comme une paire, dans l'ordre de l'arbitre."], "key_points": ["Plateau simple : deux cartouches autorisées.", "Doublé : deux cartouches au total, les deux peuvent aller sur un même plateau ; types : coup de fusil, simultané, rafale.", "Un seul coup casse les deux plateaux : bon et bon.", "Ne pas tirer sur un doublé simultané ou une rafale sans motif : zéro et zéro."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "trap", "trajectory", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch2-trajectories-ethics", "label": "2 · Hunting ethics and shooting distances"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-target-doubles", "label": "6 · Target No Bird in doubles"}], "coach_says": [{"en": "Report pair: the second comes on your shot.", "meaning": "Le moniteur : le second plateau est déclenché par le coup tiré sur le premier.", "say": "Doublé coup de fusil : le second part sur votre coup."}, {"en": "On the rafale, take either one first.", "meaning": "L'ordre est libre dans une rafale.", "say": "Sur la rafale, prenez n'importe lequel en premier."}, {"en": "One and one.", "meaning": "L'arbitre : les deux plateaux du doublé sont bons.", "say": "Bon et bon."}, {"en": "No Bird, repeat the double.", "meaning": "Plateau irrégulier ; le doublé est relancé.", "say": "No bird, on répète le doublé."}], "quiz": [{"q": "Doublé simultané. Un seul coup casse les deux plateaux. Quelle est la décision de l'arbitre ?", "options": ["Bon et bon", "Bon et No bird", "No bird, le doublé est répété", "Bon et zéro"], "answer": 0, "why": "En Sporting™, deux plateaux cassés d'un seul coup dans n'importe quel doublé comptent bon et bon (le Compak® Sporting diffère)."}, {"q": "Doublé coup de fusil. Le tireur casse le premier plateau, et un morceau de celui-ci brise le second avant le second coup. Décision ?", "options": ["Bon et bon", "Le doublé est répété et le premier résultat est conservé", "Zéro sur le second plateau", "Bon et zéro"], "answer": 1, "why": "Quand le premier plateau ou ses morceaux cassent le second avant le second coup, le doublé est répété et le premier résultat est acquis."}, {"q": "Rafale. Les deux plateaux volent correctement, mais le tireur baisse le fusil et ne tire sur aucun, sans motif valable. Décision ?", "options": ["No bird", "Zéro et No bird", "Seulement un carton jaune", "Zéro et zéro"], "answer": 3, "why": "Un plateau régulier non tiré sans motif valable est perdu ; sur une rafale ou un doublé simultané, cela donne zéro et zéro."}]}, {"id": "sporting-viewing", "minutes": 5, "title": "La présentation des plateaux", "body": ["Avant qu'une planche ne tire sur un poste, l'arbitre fait présenter les plateaux. La présentation sert à lire les plateaux : ligne, vitesse, distance et comportement du plateau. Toutes les trajectoires sont présentées au premier tireur de la planche, qui doit se tenir prêt sur le poste.", "Le tireur au poste peut demander à l'arbitre de répéter la présentation, jusqu'à deux plateaux pour chaque plateau de la séquence du menu.", "Les doublés coup de fusil ne sont pas présentés, car le second plateau ne part qu'au bruit du coup de feu. Les doublés simultanés et les rafales sont présentés au premier tireur de chaque planche et, sur demande, répétés jusqu'à deux doublés présentés.", "Pendant la présentation, les fusils sont ouverts et déchargés, comme à chaque interruption, et ne se referment que lorsque l'arbitre l'autorise. Tirer ou faire un simulacre de tir pendant la présentation est interdit et sanctionné comme une infraction à la position du fusil : d'abord un avertissement, puis un carton rouge.", "Si un lanceur tombe en panne ou si le tir s'arrête plus de dix minutes, l'arbitre présente de nouveau les plateaux de ce poste. Avant l'épreuve, personne ne peut s'entraîner sur les parcours de la compétition.", "À l'entraînement, la présentation est le moment préféré du moniteur : « watch where it turns » (regardez où il tourne). En compétition, la présentation fait partie de l'épreuve, et l'interdiction du coaching s'y applique aussi : restez silencieux, sauf si l'arbitre ou le tireur a besoin d'une traduction de procédure."], "key_points": ["Toutes les trajectoires sont présentées au premier tireur, prêt sur le poste.", "Répétitions sur demande : jusqu'à deux par plateau du menu.", "Les doublés coup de fusil ne sont jamais présentés ; les simultanés et les rafales le sont.", "Fusils ouverts pendant la présentation ; ni tir ni simulacre de tir.", "Interruption de plus de 10 minutes : plateaux présentés de nouveau."], "terms": ["target-presentation", "target-menu", "double-on-report", "simultaneous-double", "rafale-double", "mock-shooting", "practice", "red-card"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch16-long-interruption", "label": "16 · Interruption over 10 minutes"}, {"book": "sporting", "id": "ch15-no-practice", "label": "15 · No practice on competition layouts"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}], "coach_says": [{"en": "Show me the targets, please.", "meaning": "Le tireur à l'arbitre : commencez la présentation.", "say": "Montrez-moi les plateaux, s'il vous plaît."}, {"en": "Again, please, B only.", "meaning": "Demande de répétition d'un plateau du menu.", "say": "Encore, s'il vous plaît, seulement le B."}, {"en": "Guns open during the show.", "meaning": "L'arbitre : ouvrez et déchargez jusqu'à ce qu'il autorise la fermeture.", "say": "Fusils ouverts pendant la présentation."}, {"en": "Watch where it turns.", "meaning": "Le moniteur à l'entraînement : repérez l'endroit où le plateau change de direction ou de forme.", "say": "Regardez où il tourne."}], "quiz": [{"q": "Quels doublés ne sont PAS présentés ?", "options": ["Les simultanés", "Les rafales", "Les coups de fusil", "Aucun : tous sont présentés"], "answer": 2, "why": "Le second plateau d'un doublé coup de fusil ne part qu'au coup de feu : ces doublés ne sont donc pas présentés."}, {"q": "Combien de répétitions d'un plateau le tireur au poste peut-il demander ?", "options": ["Aucune", "Jusqu'à deux pour chaque plateau du menu", "Autant que nécessaire", "Une par poste"], "answer": 1, "why": "Sur demande, l'arbitre répète la présentation, jusqu'à deux plateaux pour chaque plateau de la séquence du menu."}, {"q": "Pendant la présentation, un tireur ferme son fusil et suit la ligne d'un plateau. Qu'est-ce qui s'applique ?", "options": ["C'est interdit : les pénalités de la position du fusil s'appliquent, un avertissement puis un carton rouge", "Rien : la présentation est libre", "Le plateau est présenté de nouveau", "Seul le moniteur reçoit un avertissement"], "answer": 0, "why": "Les fusils restent ouverts pendant la présentation, et le tir ou le simulacre de tir est sanctionné selon les règles de l'avertissement et du carton rouge."}]}, {"id": "sporting-malfunctions", "minutes": 5, "title": "Mauvais fonctionnements de l'arme et des cartouches", "body": ["Un mauvais fonctionnement est une défaillance de l'arme ou de la cartouche : un raté, un second canon qui ne part pas, ou les deux coups qui partent ensemble (double décharge). En Parcours de Chasse – Sporting™, les incidents se comptent par série de 25 plateaux.", "D'abord, ce que le tireur doit faire : rester en place, fusil dirigé vers la zone de tir, sans l'ouvrir ni toucher à la sûreté tant que l'arbitre ne l'a pas examiné. Ouvrir le fusil ou toucher à la sûreté avant cela signifie que le ou les plateaux sont comptés zéro.", "Le premier incident dans une série est un No bird avec avertissement, et le plateau est répété. À partir du deuxième incident dans la même série, le plateau n'est plus répété mais compté zéro.", "Détails d'un premier incident : si le premier coup ne part pas, un simple ou tout doublé est répété, mais si le tireur tire quand même le second coup, ce résultat est acquis. Si le second coup ne part pas sur un simple, le plateau est répété et ne peut alors être cassé qu'au second coup ; une casse au premier coup compte zéro. Sur un doublé coup de fusil, le premier résultat est conservé et le doublé répété. Une double décharge sur un simple, ou sur le premier plateau de tout doublé, est un No bird sans rien enregistrer.", "Si le fusil est réparé avant que la planche n'ait terminé le poste, le tireur peut tirer en dernier avec l'autorisation de l'arbitre ; sinon, il peut continuer immédiatement avec un autre fusil, ou terminer dans une autre planche avec l'accord du jury. Le fusil, le choke ou le canon ne peuvent pas être changés une fois qu'il est sur le poste."], "key_points": ["Après une défaillance : rester en place, fusil vers la zone de tir, ne pas l'ouvrir ni toucher à la sûreté.", "Premier incident dans une série : No bird + avertissement, plateau répété.", "Deuxième incident dans la même série : zéro, pas de répétition.", "Défaut du second coup sur un simple : lors de la répétition, seule une casse au second coup compte."], "terms": ["malfunction", "double-discharge", "no-bird", "zero", "safety-catch", "round", "choke", "barrel"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}, {"book": "sporting", "id": "ch6-malfunction-first-shot", "label": "6 · Malfunction on the first shot"}, {"book": "sporting", "id": "ch6-malfunction-second-shot", "label": "6 · Malfunction on the second shot"}, {"book": "sporting", "id": "ch6-second-malfunction", "label": "6 · Second malfunction in the same round"}, {"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch7-double-discharge", "label": "7 · Double discharge due to a gun fault"}, {"book": "sporting", "id": "ch7-malfunction-procedure", "label": "7 · What happens after a gun malfunction"}, {"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}], "coach_says": [{"en": "Stay there, don't open the gun.", "meaning": "L'arbitre : attendez l'examen ; ouvrir avant coûte le plateau.", "say": "Restez là, n'ouvrez pas le fusil."}, {"en": "Let me see the gun.", "meaning": "L'arbitre examine le fusil ou la cartouche.", "say": "Montrez-moi le fusil."}, {"en": "Malfunction. No Bird, first warning.", "meaning": "Premier incident dans la série : le plateau est répété.", "say": "Incident de tir. No bird, premier avertissement."}, {"en": "Second malfunction this round. Zero.", "meaning": "Pas de répétition cette fois ; le plateau est perdu.", "say": "Deuxième incident dans cette série. Zéro."}], "quiz": [{"q": "Premier problème d'arme de la série : sur un simple, la première cartouche fait long feu. Le tireur attend l'arbitre, fusil vers la zone de tir. Décision ?", "options": ["Zéro", "No bird avec avertissement ; le plateau est répété", "Bon", "Carton jaune et zéro"], "answer": 1, "why": "Le premier incident d'arme ou de munition dans une série est un No bird avec avertissement, et le plateau simple est répété."}, {"q": "La cartouche ne part pas, et le tireur, agacé, ouvre son fusil pour regarder l'amorce avant l'arrivée de l'arbitre. Décision ?", "options": ["No bird", "Le plateau est répété après un avertissement", "Zéro", "Carton rouge, et le plateau est répété"], "answer": 2, "why": "Ouvrir le fusil ou toucher à la sûreté avant le contrôle de l'arbitre signifie que le plateau est compté zéro."}, {"q": "Plateau simple, premier incident : le premier coup manque et la seconde cartouche ne part pas, le plateau est donc répété. Lors de la répétition, le tireur le casse au premier coup. Décision ?", "options": ["Bon", "De nouveau No bird", "Bon, avec un avertissement", "Zéro : lors de cette répétition, seule une casse au second coup compte"], "answer": 3, "why": "Après un défaut du second coup, le plateau simple répété ne peut être cassé qu'au second coup : le premier coup doit donc être un manqué volontaire."}]}, {"id": "sporting-time-and-lateness", "minutes": 5, "title": "Délais et retards", "body": ["Le Parcours de Chasse – Sporting™ suit un rythme serré, et plusieurs règles le protègent. Quand le tireur appelle « pull » ou « prêt », l'arbitre transmet l'appel au pulleur par un signal sonore, et le plateau doit partir dans les trois secondes ; un plateau plus tardif est un No bird.", "Entre les plateaux simples, ou entre les doublés, le tireur dispose au maximum de 15 secondes. La première fois que ce délai est dépassé, l'arbitre donne un avertissement ; ensuite, les pénalités du carton rouge s'appliquent. Après une décision définitive sur une réclamation, le tireur doit reprendre dans les 15 secondes, sinon c'est un refus d'obtempérer ; l'obstruction délibérée est traitée de la même façon.", "Le retard : quand un tireur manque, l'arbitre appelle son nom et son numéro trois fois en l'espace d'une minute. Arriver avant son tour sur les plateaux simples du premier poste ne coûte rien. Ensuite, chaque plateau non tiré est zéro ; rejoindre la planche à un poste ultérieur signifie que tous les plateaux des postes précédents sont zéro. Un parcours dont des postes ont été manqués ne peut jamais être retiré dans une autre planche.", "Un tireur en retard pour des raisons indépendantes de sa volonté ne doit pas rejoindre la planche dans cette série, mais faire appel par écrit auprès du jury. Si le jury accepte, la série est tirée dans une autre planche ; sinon, 25 zéros pour chaque parcours non tiré.", "Monter sur le poste sans protections auditives ou lunettes de protection équivaut à une absence. Pour un barrage non programmé, les tireurs doivent être prêts dans les 15 minutes suivant leur appel.", "Pour vous : ne retardez jamais la planche par une longue traduction. Court maintenant, les détails après le poste."], "key_points": ["Plateau dans les 3 secondes suivant le signal de l'arbitre, sinon No bird.", "15 secondes au maximum entre les simples ou les doublés : avertissement, puis carton rouge.", "Reprendre dans les 15 secondes après une décision définitive, sinon c'est un refus d'obtempérer.", "Retard : nom et numéro appelés trois fois en une minute ; les plateaux manqués sont zéro."], "terms": ["call", "trapper", "no-bird", "firing-time", "red-card", "jury", "hearing-protection", "safety-glasses", "shoot-off"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch10-deliberate-delay", "label": "10 · Deliberate delay or unfair behaviour"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch16-late-excuse", "label": "16 · Lateness beyond the shooter's control"}, {"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}], "coach_says": [{"en": "Shooter number twenty-three!", "meaning": "L'arbitre appelle un tireur absent (trois fois en l'espace d'une minute).", "say": "Tireur numéro vingt-trois !"}, {"en": "Watch your time.", "meaning": "Rappel du délai de 15 secondes entre les plateaux.", "say": "Attention au temps."}, {"en": "Over fifteen seconds. This is a warning.", "meaning": "Premier dépassement du délai : avertissement ; la prochaine fois, une pénalité.", "say": "Plus de quinze secondes. C'est un avertissement."}, {"en": "Glasses on, or you can't shoot.", "meaning": "Sans protection des yeux, le tireur est considéré comme absent.", "say": "Mettez vos lunettes, sinon vous ne pouvez pas tirer."}], "quiz": [{"q": "Le tireur appelle, l'arbitre transmet le signal, mais le plateau part environ cinq secondes plus tard. Le tireur tire et manque. Décision ?", "options": ["Zéro", "No bird", "Bon", "Un avertissement pour le tireur"], "answer": 1, "why": "Un plateau lancé plus de trois secondes après le signal de l'arbitre est un No bird."}, {"q": "Un tireur arrive pendant que sa planche tire encore les simples du poste 1, avant que son tour soit venu. Que se passe-t-il ?", "options": ["Il rejoint la planche sans pénalité", "25 zéros", "Zéro sur tous les simples du poste 1", "Il doit tirer avec une autre planche"], "answer": 0, "why": "Arriver avant d'avoir manqué son tour sur les simples du premier poste n'entraîne aucune pénalité."}, {"q": "Entre deux plateaux simples, un tireur met environ 25 secondes, pour la première fois aujourd'hui. Décision ?", "options": ["Zéro sur le plateau suivant", "Carton rouge", "Aucune conséquence", "Un avertissement de l'arbitre"], "answer": 3, "why": "La limite est de 15 secondes ; la première fois qu'elle est dépassée, l'arbitre avertit, et ce n'est qu'ensuite que viennent les pénalités."}]}]}, {"id": "compak", "icon": "grid", "title": "Le règlement du Compak® Sporting", "intro": "Le Compak® Sporting concentre la variété du Parcours de Chasse – Sporting™ sur un petit terrain : cinq pas de tir alignés, six lanceurs et un rectangle fixe que les plateaux doivent survoler. Beaucoup de règles se ressemblent, mais la position du fusil, les délais, les doublés et les pénalités diffèrent. Un interprète qui confond les deux disciplines donne au tireur de fausses informations.", "lessons": [{"id": "compak-layout-rotation", "minutes": 5, "title": "Parcours, menu et rotation", "body": ["Un parcours de Compak® Sporting est compact par conception. Les plateaux doivent survoler un rectangle balisé de 35 à 40 m de large et de 25 m de profondeur, avec un drapeau ou un repère à chaque angle. Face à lui se trouvent cinq pas de tir, chacun un carré de 1 m, alignés de 4 à 8 m en retrait du côté avant ; le pas de tir 3 est au milieu.", "Il y a six lanceurs, désignés par les lettres A à F de gauche à droite, chacun avec un panneau. Chaque Compak® doit comporter un traversard de gauche à droite, un traversard de droite à gauche et un fuyant ; les autres trajectoires sont au choix de l'organisateur. Chaque pas de tir a un limiteur d'angle de tir, un cadre qui empêche le fusil de pivoter trop loin et maintient le tireur dans le pas de tir.", "Une série compte 25 plateaux, cinq à chaque pas de tir : cinq plateaux simples, trois simples et un doublé, ou un simple et deux doublés. Sur un même Compak®, le type de doublé est le même à tous les pas de tir. Le menu, l'ordre des plateaux, est affiché à chaque pas de tir, et le premier plateau de chaque doublé est le dernier plateau tiré au pas de tir précédent.", "Rotation dans une planche de six tireurs au maximum : c'est toujours le pas de tir 1 qui commence, et le sixième tireur attend derrière lui. Quand le tireur du pas de tir 5 a terminé, il va attendre derrière le pas de tir 1, tout le monde se décale d'un pas de tir vers la droite et le tireur qui attendait entre au pas de tir 1. On change de pas de tir fusil ouvert et déchargé, sans gêner ceux qui tirent encore.", "Le Compak® en ligne fonctionne autrement : chaque tireur d'un groupe passe du pas de tir 1 au pas de tir 5."], "key_points": ["Rectangle de 35–40 m × 25 m ; cinq pas de tir de 1 m ; six lanceurs A–F.", "Obligatoires : traversard gauche-droite, traversard droite-gauche, fuyant.", "Série = 25 plateaux, 5 par pas de tir ; un seul type de doublé par Compak®.", "Chaque doublé commence par le dernier plateau du pas de tir précédent.", "Après le pas de tir 5 : attendre derrière le pas de tir 1 ; tout le monde se décale d'un pas vers la droite."], "terms": ["trap", "target-menu", "round", "squad", "rotation", "crosser", "going-away", "shooting-stand", "double", "fly-over-rectangle", "firing-angle-limiter", "waiting-position"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch3-free-trajectories", "label": "3 · Free trajectories"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-squads-groups", "label": "17 · Size of squads and groups"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Move one station to the right.", "meaning": "Rotation après que le tireur du pas de tir 5 a terminé.", "say": "Décalez-vous d'un pas de tir vers la droite."}, {"en": "Gun open when you change stations.", "meaning": "Entre les pas de tir, le fusil est ouvert et déchargé.", "say": "Fusil ouvert quand vous changez de pas de tir."}, {"en": "Your double starts with the last target of the previous station.", "meaning": "La règle d'enchaînement du menu de Compak®.", "say": "Votre doublé commence par le dernier plateau du pas de tir précédent."}, {"en": "You're waiting behind one.", "meaning": "Le sixième tireur se tient derrière le pas de tir 1.", "say": "Vous attendez derrière le 1."}], "quiz": [{"q": "Combien de lanceurs et de pas de tir compte un parcours de Compak® Sporting ?", "options": ["4 lanceurs, 3 pas de tir", "6 lanceurs, 5 pas de tir", "5 lanceurs, 5 pas de tir", "8 lanceurs, 6 pas de tir"], "answer": 1, "why": "Un Compak® utilise six lanceurs, de A à F, et cinq pas de tir."}, {"q": "Le tireur du pas de tir 5 a terminé son menu. Où va-t-il ?", "options": ["Au pas de tir 1", "Il reste au pas de tir 5", "Derrière le pas de tir 1, pour attendre", "Chez l'arbitre pour signer la feuille"], "answer": 2, "why": "Il devient le tireur en attente derrière le pas de tir 1, pendant que tous les autres se décalent d'un pas vers la droite."}, {"q": "Sur un Compak®, le premier plateau de chaque doublé est…", "options": ["n'importe quel plateau choisi par le tireur", "toujours le lanceur A", "un plateau montré seulement sur demande", "le dernier plateau tiré au pas de tir précédent"], "answer": 3, "why": "Le menu enchaîne les pas de tir : chaque doublé commence par le plateau qui a terminé le pas de tir précédent."}]}, {"id": "compak-gun-and-call", "minutes": 5, "title": "Position du fusil, appel du plateau et délais", "body": ["C'est ici que le Compak® Sporting se distingue le plus visiblement du Parcours de Chasse – Sporting™. À l'appel, la position du fusil est libre : le fusil peut déjà être à l'épaule, ou non. Il n'y a ni départ fusil bas, ni ligne sur le gilet. Chaque plateau se tire néanmoins fusil à l'épaule.", "Déclenchement : les lanceurs sont déclenchés à la main, par télécommande ou par sonopull (déclenchement à la voix). En déclenchement manuel, le plateau doit partir de 0 à 3 secondes après l'appel ; un sonopull a un délai fixe de 0,5 seconde. Les épreuves internationales en ligne utilisent uniquement le sonopull. Un plateau lancé plus de 3 secondes après l'appel, ou un plateau que le tireur n'a pas demandé, est un No bird.", "Délai : le tireur dispose au maximum de 10 secondes pour appeler après que le plateau du pas de tir précédent a été tiré, soit moins que les 15 secondes du Sporting™. La première fois, l'arbitre note un avertissement sur la feuille de marque ; si cela se reproduit dans la même série, c'est un carton rouge et les plateaux sont comptés ainsi : plateau simple zéro, doublé coup de fusil zéro et No bird, doublé simultané zéro et zéro.", "Présentation : en tir par planches, les plateaux sont montrés une seule fois le matin, à la première planche. Le tireur du pas de tir 1 appelle chaque plateau simple, de A à F ; puis l'arbitre montre les doublés simultanés et annonce « start » ou « competition » (début de l'épreuve). Après une interruption de plus de 10 minutes, les six plateaux simples sont montrés de nouveau.", "Chargement : uniquement à votre propre pas de tir, fusil ouvert et pointé vers la zone de tir à l'intérieur du limiteur d'angle ; on ne le ferme que lorsque c'est son tour."], "key_points": ["Position du fusil libre à l'appel ; on tire toujours fusil à l'épaule.", "Déclenchement manuel 0–3 s après l'appel ; sonopull fixe 0,5 s ; au-delà de 3 s = No bird.", "10 secondes au maximum pour appeler : avertissement noté, puis plateaux comptés zéro.", "Les plateaux sont montrés une fois le matin à la première planche ; de nouveau après une pause de plus de 10 minutes."], "terms": ["ready-position", "call", "sonopull", "no-bird", "firing-time", "score-sheet", "target-presentation", "loading"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}], "coach_says": [{"en": "Start! / Competition!", "meaning": "L'arbitre : la présentation est terminée et le tir compté commence.", "say": "Début de l'épreuve !"}, {"en": "Gun up or down, your choice here.", "meaning": "Le moniteur : en Compak®, la position du fusil à l'appel est libre.", "say": "Fusil épaulé ou non, ici c'est vous qui choisissez."}, {"en": "Ten seconds, call your target.", "meaning": "Rappel du délai de 10 secondes pour appeler.", "say": "Dix secondes, appelez votre plateau."}, {"en": "Warning: time.", "meaning": "Premier dépassement des 10 secondes ; noté sur la feuille de marque.", "say": "Avertissement : délai."}], "quiz": [{"q": "En Compak® Sporting, un tireur appelle le plateau avec le fusil déjà épaulé. Quelle est la décision de l'arbitre ?", "options": ["Carton jaune", "Autorisé : la position du fusil à l'appel est libre", "Zéro", "Autorisé seulement sur les doublés"], "answer": 1, "why": "Le Compak® Sporting n'a ni départ fusil bas, ni ligne sur le gilet ; seul le tir lui-même doit être effectué fusil à l'épaule."}, {"q": "Déclenchement manuel. Le plateau part environ quatre secondes après l'appel et le tireur le manque. Décision ?", "options": ["Zéro", "Bon", "Un avertissement pour le pulleur seulement, le zéro est maintenu", "No bird"], "answer": 3, "why": "Un plateau lancé plus de 3 secondes après l'appel est un No bird et il est relancé."}, {"q": "Pour la deuxième fois dans la même série, un tireur met plus de 10 secondes à appeler. Le plateau est un simple. Décision ?", "options": ["Zéro", "Un nouvel avertissement seulement", "No bird", "Exclusion"], "answer": 0, "why": "Après le premier avertissement, une récidive dans la même série est sanctionnée selon le tableau : un plateau simple est compté zéro."}]}, {"id": "compak-singles-doubles", "minutes": 5, "title": "Plateaux simples et doublés en Compak®", "body": ["Le Compak® Sporting emploie les mêmes mots que le Parcours de Chasse – Sporting™, mais ses doublés suivent d'autres règles. Un interprète qui transpose les règles du Sporting™ donnera de fausses réponses.", "Plateaux simples : chaque plateau simple doit permettre de tirer deux coups depuis chacun des cinq pas de tir ; le deuxième coup est donc une seconde chance légitime.", "Le règlement du Compak® définit deux types de doublé : le doublé coup de fusil (l'appel lance le premier plateau, le coup de feu lance le second ; un ou deux lanceurs) et le doublé simultané (deux plateaux sur un seul appel, toujours issus de deux lanceurs différents, tirés dans l'ordre que l'on veut). Il n'y a pas de rafale.", "La différence essentielle : dans un doublé de Compak®, on ne peut tirer qu'une seule cartouche sur chaque plateau. Tirer les deux coups sur le premier plateau est interdit, et le guide rapide des arbitres compte un double tir délibéré sur un même plateau zéro et zéro. En Sporting™, les deux cartouches peuvent être tirées sur un même plateau.", "Deux plateaux d'un seul coup : sur un doublé coup de fusil, le premier résultat est acquis, le second est un No bird et le doublé est retiré. Sur un doublé simultané, c'est un No bird sans rien compter et le doublé est répété ; de même la deuxième fois ; la troisième fois, c'est zéro et zéro. En Sporting™, le même coup compte simplement bon et bon.", "Plateaux irréguliers : si le premier plateau d'un doublé coup de fusil, ou l'un des deux plateaux d'un doublé simultané, est irrégulier, un nouveau doublé est lancé. Si le second plateau d'un doublé coup de fusil est irrégulier ou cassé par le premier, le premier résultat est acquis et le doublé est répété."], "key_points": ["Deux types de doublé seulement : coup de fusil et simultané ; pas de rafale.", "Une cartouche par plateau dans un doublé ; les deux sur un même plateau = zéro et zéro (guide rapide).", "Doublé coup de fusil, deux plateaux d'un seul coup : premier résultat acquis, second No bird, doublé répété.", "Simultané, deux plateaux d'un seul coup : No bird deux fois, zéro et zéro la troisième fois."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch3-two-with-one-report", "label": "3 · Double on report: both targets broken with one shot"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}, {"book": "compak", "id": "ch20-target-no-bird-actions", "label": "20 · What happens after a target NO BIRD"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}], "coach_says": [{"en": "One shot per bird on the pairs here.", "meaning": "Le moniteur : en Compak®, chaque plateau d'un doublé n'a droit qu'à une seule cartouche.", "say": "Ici, sur les doublés, un seul coup par plateau."}, {"en": "Both with one shot. No Bird, shoot the double again.", "meaning": "L'arbitre sur un doublé simultané : rien n'est compté, on répète.", "say": "Les deux d'un seul coup. No bird, retirez le doublé."}, {"en": "Choose your order on the show.", "meaning": "Le moniteur : décidez quel plateau du simultané prendre en premier en regardant la présentation.", "say": "Choisissez votre ordre pendant la présentation."}, {"en": "Zero, zero.", "meaning": "L'arbitre : aucun des deux plateaux du doublé n'est compté bon.", "say": "Zéro, zéro."}], "quiz": [{"q": "Doublé simultané en Compak®. Un seul coup casse les deux plateaux ; c'est la première fois que cela arrive. Décision ?", "options": ["Bon et bon", "No bird, rien n'est compté, le doublé est répété", "Bon et No bird", "Zéro et zéro"], "answer": 1, "why": "En Compak®, un doublé simultané cassé d'un seul coup est un No bird la première et la deuxième fois, et zéro et zéro la troisième fois."}, {"q": "Doublé coup de fusil en Compak®. Un seul coup casse les deux plateaux. Décision ?", "options": ["Bon et bon", "Zéro et zéro", "Le premier résultat est acquis, le second est un No bird et le doublé est répété", "No bird, rien n'est compté"], "answer": 2, "why": "Sur un doublé coup de fusil, le résultat du premier plateau est enregistré et le doublé est retiré pour compter le second."}, {"q": "Dans un doublé de Compak®, un tireur manque le premier plateau et tire délibérément la deuxième cartouche sur lui aussi. Comment le guide rapide des arbitres le compte-t-il ?", "options": ["Zéro et zéro", "C'est autorisé, comme en Sporting™", "Le doublé est répété", "Seul le second coup compte"], "answer": 0, "why": "Dans un doublé de Compak®, une seule cartouche par plateau est autorisée ; un double tir délibéré sur un même plateau donne zéro et zéro."}]}, {"id": "compak-malfunctions", "minutes": 5, "title": "Les incidents de tir en Compak®", "body": ["En Compak® Sporting, comme en Parcours de Chasse – Sporting™, les mauvais fonctionnements de l'arme et des cartouches se comptent par série de 25 plateaux : le premier incident donne un No bird et un carton jaune ; au deuxième incident du même type, les plateaux non tirés sont comptés zéro, avec un carton rouge.", "Ce que le tireur doit faire : rester en place, le fusil pointé vers la zone de tir, sans l'ouvrir ni toucher au cran de sûreté tant que l'arbitre ne l'a pas examiné. L'ouvrir avant lui coûte le ou les plateaux : zéro.", "Premier incident, quand les deux coups partent ensemble ou que la première cartouche fait défaut : un plateau simple est relancé, un doublé coup de fusil ou un doublé simultané est relancé, et rien n'est compté de la tentative ratée. Quand c'est la deuxième cartouche qui fait défaut : sur un plateau simple, le plateau est relancé, mais seul le deuxième coup peut compter, et le premier doit donc être un manqué volontaire ; sur un doublé coup de fusil, le premier résultat est acquis et le doublé est répété pour le second ; sur un doublé simultané, nouveau doublé.", "Après un incident, le tireur dispose de deux minutes pour réparer ou remplacer son fusil. Exceptionnellement, il peut emprunter le fusil d'un tireur qui n'est pas dans sa planche, avec l'accord du propriétaire et de l'arbitre. Sans fusil en état de marche, les plateaux restants sont comptés zéro. Sinon, aucun fusil, choke ou canon ne peut être changé au cours d'une série.", "La même logique s'applique à un rabbit manqué au premier coup qui se casse avant le second : No bird, et lors de la répétition seul le second coup compte."], "key_points": ["Premier incident dans une série : No bird + carton jaune ; deuxième du même type : zéro + carton rouge.", "Ne pas ouvrir le fusil ni toucher à la sûreté avant l'examen par l'arbitre.", "Défaut de la deuxième cartouche sur un simple : lors de la répétition, seul le deuxième coup compte.", "Deux minutes pour réparer ou remplacer ; emprunt uniquement hors de sa planche, avec l'accord du propriétaire et de l'arbitre."], "terms": ["malfunction", "double-discharge", "safety-catch", "no-bird", "zero", "yellow-card", "red-card", "rabbit", "choke"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch20-gun-failure-principle", "label": "20 · Gun or cartridge failures: first and second incident"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-malfunction", "label": "21 · Malfunction: inspection, 2 minutes, replacement gun"}, {"book": "compak", "id": "ch20-gun-failure-first-shot", "label": "20 · Both barrels fire together or the first cartridge fails"}, {"book": "compak", "id": "ch20-gun-failure-second-shot", "label": "20 · The second cartridge fails"}, {"book": "compak", "id": "ch12-borrowing", "label": "12 · Borrowing a gun after a breakdown"}, {"book": "compak", "id": "ch13-shared-gun", "label": "13 · No sharing a gun within a group"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}], "coach_says": [{"en": "Don't move, keep the gun closed.", "meaning": "L'arbitre : attendez l'examen après un incident.", "say": "Ne bougez pas, gardez le fusil fermé."}, {"en": "First malfunction. Yellow card, No Bird.", "meaning": "Premier incident de ce type dans la série ; le plateau est relancé.", "say": "Premier incident. Carton jaune, No bird."}, {"en": "You have two minutes.", "meaning": "Temps accordé pour réparer ou remplacer le fusil.", "say": "Vous avez deux minutes."}, {"en": "Only the second shot counts on this one.", "meaning": "Répétition après un défaut de la deuxième cartouche : manquez volontairement au premier coup.", "say": "Sur celui-ci, seul le deuxième coup compte."}], "quiz": [{"q": "Premier incident de la série en Compak® : la première cartouche fait défaut sur un plateau simple. Le tireur attend correctement. Décision ?", "options": ["No bird avec carton jaune ; un nouveau plateau est lancé", "Zéro", "Carton rouge et zéro", "Bon"], "answer": 0, "why": "Le premier incident d'arme ou de cartouche dans une série est un No bird, avec un premier avertissement signalé par un carton jaune."}, {"q": "Le fusil d'un tireur tombe en panne. Il veut emprunter le fusil d'un tireur de sa planche. Est-ce autorisé ?", "options": ["Oui, avec l'accord du propriétaire", "Oui, si l'arbitre est d'accord", "Oui, sans conditions", "Non : le prêteur doit être hors de sa planche, et le propriétaire comme l'arbitre doivent être d'accord"], "answer": 3, "why": "Le Compak® interdit de partager un fusil au sein d'un groupe ; l'emprunt exceptionnel ne se fait qu'en dehors, avec les deux accords."}, {"q": "Deuxième incident d'arme du même type dans cette série, sur un plateau simple que le tireur n'a pas pu tirer. Décision ?", "options": ["De nouveau No bird", "No bird et un avertissement", "Zéro, avec carton rouge", "Le plateau est montré de nouveau"], "answer": 2, "why": "À partir du deuxième incident du même type, les plateaux non tirés sont comptés zéro."}]}, {"id": "compak-dress-and-conduct", "minutes": 5, "title": "Tenue et comportement", "body": ["Les épreuves de Compak® Sporting sont publiques : la tenue doit donc être correcte et pratique. Les shorts courts sont interdits, mais les bermudas qui s'arrêtent au plus 5 cm au-dessus du genou sont acceptés. Le haut doit avoir au moins des manches courtes et monter jusqu'au cou ; un T-shirt convient, mais pas un torse nu sous le gilet. Les sandales sont interdites à l'entraînement comme en compétition. Le dossard se porte dans le dos, entièrement visible ; un premier manquement vaut un avertissement, puis des sanctions.", "Les protections auditives et les lunettes de protection sont obligatoires. Se présenter au pas de tir sans elles équivaut à une absence : pas de tir.", "Ponctualité : présentez-vous à l'arbitre à temps. En tir par planches, arriver après que le premier tireur de la planche a appelé le premier plateau coûte 25 zéros pour la série ; un recours se fait par écrit auprès du jury le jour même.", "Comportement : le coaching pendant la compétition est interdit ; le concurrent reçoit un carton jaune et le moniteur est écarté de la zone de tir. Contester une décision définitive après la reprise du tir, ou critiquer ouvertement une décision en tant que tireur ou spectateur, constitue une tentative d'influencer l'arbitre et peut entraîner une exclusion. À la fin de chaque série, le tireur signe la feuille de marque ; refuser de signer fait perdre le droit de réclamer.", "Près du poste, vous faites partie du public : portez vos protections, restez silencieux pendant l'appel, ne commentez jamais une décision. La question de savoir si vous pouvez relayer les paroles d'un moniteur en compétition reste ouverte pour la FITASC ; la pratique prudente consiste à n'interpréter que pour l'arbitre, le jury et l'organisateur."], "key_points": ["Pas de shorts courts, pas de torse nu sous le gilet, pas de sandales (même à l'entraînement) ; dossard dans le dos.", "Sans protections auditives ou lunettes au pas de tir = absent, pas de tir.", "En retard après le premier appel de la planche : 25 zéros ; recours écrit possible le jour même.", "Pas de coaching ; pas de critique publique des décisions ; signer la feuille de marque."], "terms": ["dress-code", "competitor-number", "hearing-protection", "safety-glasses", "conduct", "yellow-card", "score-sheet", "protest", "quiet-on-stand"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-late-appeal", "label": "9 · Appealing a lateness penalty"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}], "coach_says": [{"en": "Number on your back, please.", "meaning": "L'arbitre : le dossard doit être entièrement visible dans le dos.", "say": "Le dossard dans le dos, s'il vous plaît."}, {"en": "Ears and eyes on.", "meaning": "Mettez les protections auditives et les lunettes avant d'aller au pas de tir.", "say": "Casque et lunettes, s'il vous plaît."}, {"en": "Sign the sheet, please.", "meaning": "Fin de série : le tireur signe la feuille de marque.", "say": "Signez la feuille, s'il vous plaît."}, {"en": "No coaching on the stand.", "meaning": "Avertissement de l'arbitre : le coaching est interdit en compétition.", "say": "Pas de coaching sur le poste."}], "quiz": [{"q": "Un tireur se présente au pas de tir en sandales pour une série d'entraînement. Est-ce autorisé ?", "options": ["Oui, seulement à l'entraînement", "Non : les sandales sont interdites à l'entraînement et en compétition", "Oui, avec des chaussettes", "Seulement avec l'autorisation de l'arbitre"], "answer": 1, "why": "Le code vestimentaire du Compak® interdit les sandales pour des raisons de sécurité, à l'entraînement comme en compétition."}, {"q": "Tir par planches. Un tireur arrive juste après que le premier tireur de sa planche a appelé le premier plateau. Résultat ?", "options": ["Aucune pénalité", "Zéro sur le premier plateau seulement", "Il tire à la fin de la planche", "25 zéros pour la série ; un recours écrit auprès du jury est possible le jour même"], "answer": 3, "why": "La limite est le premier appel de la planche ; après lui, le retardataire reçoit 25 zéros, sauf si le jury accepte un motif valable."}, {"q": "Après la série, un tireur refuse de signer la feuille de marque parce qu'il conteste une décision. Quelle en est la conséquence ?", "options": ["Il perd le droit de faire toute réclamation", "L'arbitre doit modifier le résultat", "La série est retirée", "Il ne se passe rien"], "answer": 0, "why": "Signer la feuille à la fin de chaque série est obligatoire ; refuser de signer rend toute réclamation irrecevable."}]}]}, {"id": "referee", "icon": "whistle", "title": "Arbitre, comptage et pénalités", "intro": "En compétition, l'arbitre est la personne dont vous traduirez les paroles le plus souvent et avec le plus de soin. Cette mission vous donne les annonces orales, la feuille de marque, les cartons et pénalités, la procédure de réclamation et les catégories d'âge, pour que chaque décision parvienne à votre tireur exactement telle qu'elle a été prise.", "lessons": [{"id": "referee-calls", "minutes": 5, "title": "Ce que dit l'arbitre sur le poste", "body": ["Un poste a son propre langage, très bref. Le tireur appelle le plateau quand il est prêt, généralement « Pull! » ou « Prêt ! ». En Parcours de Chasse – Sporting™, l'arbitre transmet cet appel au pulleur par un signal sonore, et le plateau doit partir dans les trois secondes ; un plateau plus tardif est un No bird. En Compak® Sporting, un déclenchement manuel doit aussi intervenir dans les trois secondes suivant l'appel, et un déclenchement à la voix (sonopull) a un délai fixe d'une demi-seconde.", "Avant que quiconque tire, l'arbitre contrôle les armes. Le chargement n'est autorisé que sur le poste, fusil dirigé vers la zone de tir, une fois que l'arbitre a annoncé que le tir peut commencer. Pendant la présentation des plateaux, et chaque fois que le tir s'arrête, les fusils sont ouverts et vides et ne se referment que sur ordre de l'arbitre. En Compak®, l'arbitre lance la série par « Start » ou « Competition ».", "Après chaque plateau, le règlement connaît trois résultats : « bon » (one, plateau touché), « zéro » (perdu) et « No bird » (le plateau ne compte pas et il est relancé). Dans le monde, vous entendrez aussi « dead », « good », « lost », ou simplement le silence pour un plateau touché. En Compak®, l'arbitre doit annoncer chaque zéro à voix haute ou par un signal sonore, pour qu'un tireur en désaccord puisse réclamer immédiatement.", "Le tireur a lui aussi un mot officiel : le bras levé, « Réclamation ! » (« Protest! » ou « Appeal! »). Quand vous interprétez, gardez ces annonces courtes et identiques à chaque fois. Convenez avec votre tireur, avant la série, des mots que vous emploierez, et n'ajoutez jamais rien de votre cru entre l'appel et le tir."], "key_points": ["Le tireur appelle « Pull! » ou « Prêt ! » ; le plateau doit partir dans les 3 secondes", "On ne charge que sur le poste et seulement quand l'arbitre l'autorise ; fusils ouverts pendant la présentation et les arrêts", "Mots du règlement : bon = touché, zéro = perdu, No bird = relancé", "Compak® : chaque zéro est annoncé à voix haute ou par un signal sonore", "Réclamation = bras levé + « Réclamation ! » (« Protest! » / « Appeal! »)"], "terms": ["call", "referee", "trapper", "sonopull", "one", "zero", "no-bird", "loading", "target-presentation", "protest"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch5-referee-oath", "label": "5 · Referee's commitments"}, {"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}], "coach_says": [{"en": "You may load.", "meaning": "L'arbitre autorise le début du tir : chargez maintenant, fusil dirigé vers la zone de tir.", "say": "Vous pouvez charger."}, {"en": "No bird!", "meaning": "Ce plateau ne compte pas ; ne tirez pas dessus. Il sera relancé.", "say": "No bird !"}, {"en": "Lost.", "meaning": "L'arbitre a compté le plateau comme manqué (zéro).", "say": "Zéro."}, {"en": "Dead. / Good.", "meaning": "Le plateau est touché (bon).", "say": "Bon."}, {"en": "Guns open, please — we’re showing the targets.", "meaning": "Tout le monde ouvre et décharge ; l'arbitre va lancer les plateaux pour la présentation.", "say": "Fusils ouverts, s'il vous plaît : on présente les plateaux."}, {"en": "Start. / Competition.", "meaning": "Compak® : la présentation est terminée, la série compte à partir de maintenant.", "say": "Début de l'épreuve."}], "quiz": [{"q": "En Parcours de Chasse – Sporting™, le plateau part cinq secondes après le signal de l'arbitre. Quelle est la décision ?", "options": ["Il compte normalement", "No bird", "Zéro, car le tireur a appelé trop tôt", "Un avertissement pour le pulleur seulement"], "answer": 1, "why": "Un plateau doit partir dans les trois secondes suivant le signal de l'arbitre ; un plateau plus tardif est un No bird et il est relancé."}, {"q": "Quand un tireur peut-il charger son fusil ?", "options": ["En marchant vers le poste", "Derrière le poste, en attendant", "Sur le poste, fusil dirigé vers la zone de tir, après que l'arbitre a autorisé le tir", "Chaque fois que le moniteur le dit"], "answer": 2, "why": "Le chargement n'est autorisé que sur le poste, vers la zone de tir, et seulement une fois que l'arbitre a autorisé le début."}, {"q": "Quel mot ouvre une réclamation officielle sur le poste ?", "options": ["« Réclamation ! » (« Protest! » ou « Appeal! ») le bras levé", "« Pull! »", "« No bird! »", "« Arbitre, regardez ! »"], "answer": 0, "why": "Les deux règlements prévoient « réclamation » (« protest » ou « appeal ») le bras levé ; « No bird » appartient à l'arbitre seul."}]}, {"id": "referee-scoring", "minutes": 5, "title": "Feuilles de marque, résultats et égalités", "body": ["Chaque plateau finit sur une feuille de marque. En Parcours de Chasse – Sporting™, c'est l'arbitre qui tient la feuille, ou une personne placée sous son contrôle. Le modèle FITASC indique la lettre du lanceur de chaque plateau, avec X pour un plateau touché et O pour un manqué, un total et une colonne pour la signature. Avant que la planche ne reparte, l'arbitre photographie la feuille.", "Les tireurs doivent vérifier leur score en quittant chaque poste. Un désaccord est soumis immédiatement à l'arbitre ; l'arbitre décide, éventuellement après avoir consulté d'autres personnes, et ensuite il n'y a pas d'appel. En Compak® Sporting, le tireur signe la feuille de marque à la fin de la série, et un tireur qui refuse de signer perd le droit de réclamer. Traduisez « check your card » comme une consigne urgente, pas comme une remarque polie.", "Une épreuve internationale se tire sur 200 plateaux, en séries de 25. Quand des tireurs sont à égalité pour les trois premières places, ils disputent un barrage de 25 plateaux ; s'ils sont encore à égalité, on passe à la mort subite, où le premier zéro élimine. En dessous de la troisième place, il n'y a pas de barrage : les tireurs à égalité partagent la place et sont départagés en remontant les parcours, du dernier (le huitième) parcours ou Compak® jusqu'au premier. Les équipes ne font jamais de barrage.", "Les barrages réservent un piège de plus à l'interprète. Si aucune heure n'a été fixée, les tireurs doivent être prêts dans les quinze minutes suivant l'appel. Un tireur absent est « disqualifié » selon le règlement du Sporting™ et « considéré comme ayant abandonné » selon celui du Compak®. Employez le mot de la discipline où vous êtes."], "key_points": ["X = touché, O = manqué sur les feuilles de marque FITASC", "Sporting™ : vérifier son score en quittant chaque poste ; Compak® : signer la feuille ou perdre le droit de réclamer", "Égalité pour les places 1–3 : barrage de 25 plateaux, puis mort subite", "En dessous de la 3e place : départage en remontant depuis le 8e parcours ou Compak® ; pas de barrage par équipes", "Être prêt dans les 15 minutes suivant l'appel au barrage"], "terms": ["score-sheet", "round", "one", "zero", "shoot-off", "countback", "team", "referee"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}, {"book": "sporting", "id": "ch18-team-ties", "label": "18 · Team ties"}, {"book": "compak", "id": "ch15-who-keeps", "label": "15 · Who keeps the score sheet"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}, {"book": "compak", "id": "ch14-shootoff-availability", "label": "14 · Staying available for a shoot-off"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}, {"book": "compak", "id": "ch14-team-ties", "label": "14 · Ties between national teams"}], "coach_says": [{"en": "Check your card before you leave the stand.", "meaning": "Regardez vos marques maintenant ; les contestations ultérieures ne sont pas acceptées.", "say": "Vérifiez votre feuille avant de quitter le poste."}, {"en": "Sign here, please.", "meaning": "Compak® : signer confirme le score ; refuser, c'est perdre le droit de réclamer.", "say": "Signez ici, s'il vous plaît."}, {"en": "Twenty-three — you dropped two.", "meaning": "Score de 23 sur 25 ; deux plateaux ont été manqués.", "say": "Vingt-trois : vous en avez manqué deux."}, {"en": "There’s a tie for third — shoot-off in fifteen minutes.", "meaning": "Soyez au parcours indiqué et prêt à tirer dans les quinze minutes.", "say": "Il y a égalité pour la troisième place : barrage dans quinze minutes."}, {"en": "Sudden death: first zero is out.", "meaning": "Après le barrage de 25 plateaux, le premier tireur qui manque (à nombre égal de plateaux tirés) est éliminé.", "say": "Mort subite : le premier zéro est éliminé."}], "quiz": [{"q": "Sur une feuille de marque FITASC, que signifie O ?", "options": ["Un plateau touché", "Un No bird", "Un manqué", "Un poste vide"], "answer": 2, "why": "Le modèle FITASC marque un plateau touché par X et un manqué par O."}, {"q": "Deux tireurs sont à égalité pour la 7e place. Que se passe-t-il ?", "options": ["Un barrage de 25 plateaux", "La mort subite immédiatement", "Un tirage à pile ou face par le jury", "Ils partagent la place et sont départagés en remontant les parcours"], "answer": 3, "why": "Les barrages ne concernent que les places 1–3 ; en dessous, les tireurs à égalité sont classés en remontant depuis le huitième parcours ou Compak®."}, {"q": "En Compak® Sporting, votre tireur refuse de signer la feuille de marque. Quelle en est la conséquence ?", "options": ["Il perd le droit de faire toute réclamation", "La série est retirée", "L'arbitre signe et rien ne change", "Il reçoit automatiquement 25 zéros"], "answer": 0, "why": "Le règlement du Compak® précise qu'un tireur qui refuse de signer perd le droit de réclamer."}]}, {"id": "referee-cards", "minutes": 5, "title": "Avertissements, cartons et pénalités", "body": ["Les pénalités FITASC suivent une échelle. En s'inscrivant à une compétition, le tireur accepte le règlement et les sanctions. La première infraction à une règle entraîne normalement un avertissement, signalé par un carton jaune. En Parcours de Chasse – Sporting™, l'exemple classique est la position du fusil : une crosse au-dessus de la ligne du gilet, ou un fusil épaulé avant l'apparition du plateau, vaut un avertissement verbal et un carton jaune.", "Une récidive sur le même parcours (ou le même Compak®) entraîne un carton rouge, et le plateau est compté selon un tableau : zéro sur un plateau simple, zéro et No bird sur un doublé coup de fusil, zéro et zéro sur un doublé simultané ou une rafale. La même échelle s'applique au tir sur un No bird annoncé et, en Sporting™, au dépassement des quinze secondes entre les plateaux. En Compak® Sporting, la limite est de dix secondes pour appeler.", "Le coaching pendant une compétition est également sanctionné : le tireur reçoit un carton jaune, les récidives entraînent d'autres sanctions, et l'arbitre fait sortir de la zone de tir la personne qui a donné les conseils. Pour un interprète, c'est le carton le plus important du règlement.", "En cas de récidive, de refus d'obtempérer ou de tentative d'influencer un arbitre, le jury peut retirer un plateau, une série entière de 25, ou exclure le tireur. Jeter son fusil, les insultes ou la violence, et tirer délibérément sur des animaux vivants peuvent entraîner une exclusion immédiate. Une exclusion est enregistrée par la FITASC pendant cinq ans et ne donne lieu à aucun remboursement. Traduisez « warning », « yellow card » et « red card » littéralement, calmement et immédiatement : avertissement, carton jaune, carton rouge."], "key_points": ["Première infraction : avertissement avec carton jaune", "Récidive sur le même parcours ou Compak® : carton rouge + plateau compté selon le tableau", "Coaching en compétition : carton jaune pour le tireur, moniteur écarté", "Échelle du jury : un plateau, une série ou l'exclusion", "Exclusion : enregistrée 5 ans, sans remboursement"], "terms": ["yellow-card", "red-card", "penalty", "ready-position", "firing-time", "jury", "conduct"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch13-acceptance", "label": "13 · Acceptance of rules; first breach = warning"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch12-shooting-nobird", "label": "12 · Shooting at a declared No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch13-jury-penalties", "label": "13 · Jury penalty scale"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "sporting", "id": "ch13-immediate-expulsion", "label": "13 · Immediate expulsion"}, {"book": "sporting", "id": "ch13-expulsion-record", "label": "13 · Expulsion record and lifetime ban"}, {"book": "sporting", "id": "ch13-no-refund", "label": "13 · No refund after expulsion"}, {"book": "compak", "id": "ch23-yellow-card", "label": "23 · Accepting the rules; first a yellow card"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch23-exclusion-record", "label": "23 · Exclusions: record, repeat, no refund"}], "coach_says": [{"en": "Warning — your stock was above the line.", "meaning": "Sporting™ : le fusil était trop haut avant l'apparition du plateau ; la prochaine fois sur ce parcours, cela coûtera le plateau.", "say": "Avertissement : votre crosse était au-dessus de la ligne."}, {"en": "That’s a yellow card.", "meaning": "Un premier avertissement officiel ; il est enregistré.", "say": "C'est un carton jaune."}, {"en": "Red card — the target is zero.", "meaning": "Une récidive : le plateau est compté perdu.", "say": "Carton rouge : le plateau est zéro."}, {"en": "You’re over time.", "meaning": "Le tireur a mis plus de temps que permis (15 s en Sporting™, 10 s pour appeler en Compak®).", "say": "Vous avez dépassé le temps imparti."}, {"en": "Sir, please leave the shooting area.", "meaning": "L'arbitre écarte quelqu'un, par exemple une personne prise en train de donner des conseils.", "say": "Monsieur, veuillez quitter la zone de tir."}], "quiz": [{"q": "Sporting™ : après un carton jaune pour fusil épaulé, le tireur épaule de nouveau trop tôt sur le même parcours, sur un plateau simple. Quel est le résultat ?", "options": ["Un nouvel avertissement", "Carton rouge et le plateau est zéro", "No bird", "Exclusion immédiate"], "answer": 1, "why": "Après le premier avertissement, une nouvelle infraction sur le même parcours entraîne un carton rouge ; sur un plateau simple, le plateau est zéro."}, {"q": "L'arbitre voit un moniteur donner des conseils à un tireur pendant une compétition. Que dit le règlement ?", "options": ["Rien, le coaching est autorisé entre les postes", "Le moniteur reçoit un carton rouge", "Le tireur reçoit un carton jaune et le moniteur est écarté de la zone de tir", "La série est annulée"], "answer": 2, "why": "Les deux règlements donnent un carton jaune au concurrent et font sortir par l'arbitre la personne qui donne les conseils de la zone de tir."}, {"q": "Laquelle de ces sanctions le jury ne peut-il PAS infliger selon l'échelle des pénalités ?", "options": ["La perte d'un plateau", "La perte d'une série de 25", "L'exclusion", "Une amende en espèces versée à l'arbitre"], "answer": 3, "why": "L'échelle du jury comprend la perte d'un plateau, la perte d'une série ou l'exclusion ; il n'y a pas d'amende versée à l'arbitre."}]}, {"id": "referee-appeals", "minutes": 5, "title": "Réclamations, cautions et jury", "body": ["Une réclamation doit se faire sur-le-champ. Le tireur lève le bras et dit « Réclamation ! » (« Protest! » ou « Appeal! ») sur le poste, avant d'appeler le plateau suivant (en Compak® Sporting, avant que le tireur suivant appelle). L'arbitre arrête le tir et écoute le motif. En appelant le plateau suivant, le tireur accepte la décision précédente : en tant qu'interprète, vous devez donc être rapide ici.", "Si l'arbitre est sûr de lui, la décision est confirmée et devient définitive. En cas de doute, l'arbitre peut consulter un autre arbitre, le pulleur ou les tireurs de la planche, uniquement pour avis, puis il décide seul. Les tireurs ne peuvent jamais aller sur le terrain ni ramasser un plateau pour le vérifier, et un plateau cassé derrière un obstacle naturel ou au-delà d'une limite de tir relève de la décision de l'arbitre.", "Certaines décisions ne peuvent jamais être portées devant le jury : le fait qu'un plateau soit bon ou zéro, un No bird, et la régularité d'une trajectoire. D'autres décisions peuvent faire l'objet d'un appel écrit auprès du jury, avec une caution : en Parcours de Chasse – Sporting™, elle s'élève à 40 % du montant de l'engagement ; en Compak®, c'est le montant en vigueur le jour même, et seulement pour des incidents de la même journée. Si l'appel aboutit, la caution est restituée.", "Après la décision définitive, le tireur doit reprendre le tir dans les quinze secondes en Sporting™ et dans les dix secondes en Compak® ; sinon, c'est un refus d'obtempérer. Continuer à discuter, défier l'arbitre pour la galerie, ou d'autres personnes critiquant ouvertement une décision, tout cela constitue une tentative d'influencer l'arbitre. Votre travail consiste à traduire la réclamation et la réponse avec exactitude, pas à plaider la cause."], "key_points": ["Réclamer immédiatement, sur le poste, bras levé : « Réclamation ! » (« Protest! » / « Appeal! »)", "Appeler le plateau suivant = accepter la décision précédente", "Jamais susceptibles d'appel : bon/zéro, No bird, régularité de la trajectoire", "Appel écrit au jury avec caution (Sporting™ : 40 % de l'engagement)", "Reprendre dans les 15 s (Sporting™) ou 10 s (Compak®) ; continuer à discuter = influencer l'arbitre"], "terms": ["protest", "appeal", "jury", "referee", "entry-fee", "no-bird", "trajectory"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "sporting", "id": "ch9-consultation", "label": "9 · Referee in doubt: consultation"}, {"book": "sporting", "id": "ch9-jury-appeal", "label": "9 · What can go to the jury and the 40% deposit"}, {"book": "sporting", "id": "ch9-deposit-outcome", "label": "9 · Outcome of a jury appeal"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch15-appeal-jury", "label": "15 · Appeal jury"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}, {"book": "compak", "id": "ch19-consultation", "label": "19 · Referee in doubt: who may be consulted"}, {"book": "compak", "id": "ch4-complaint-limits", "label": "4 · What you cannot complain about"}, {"book": "compak", "id": "ch4-complaint-procedure", "label": "4 · How to lodge a complaint and the deposit"}, {"book": "compak", "id": "ch21-refusal-to-comply", "label": "21 · Refusal to comply: 10 seconds to resume"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Protest! The target was broken before I fired.", "meaning": "Le tireur conteste officiellement la décision et en donne le motif (ici : un plateau cassé a été lancé).", "say": "Réclamation ! Le plateau était cassé avant que je tire."}, {"en": "I’m certain — the decision stands.", "meaning": "L'arbitre confirme ; la décision est définitive.", "say": "J'en suis certain : la décision est maintenue."}, {"en": "Did anyone see a piece come off?", "meaning": "L'arbitre a un doute et demande l'avis de la planche, à titre consultatif seulement ; c'est toujours lui qui décide.", "say": "Quelqu'un a-t-il vu un morceau se détacher ?"}, {"en": "You can take it to the jury in writing, with the deposit.", "meaning": "Cette décision est susceptible d'appel ; il faut un appel écrit et une caution.", "say": "Vous pouvez faire appel par écrit auprès du jury, avec la caution."}, {"en": "Please carry on shooting.", "meaning": "La décision est définitive ; reprenez maintenant, sinon c'est un refus d'obtempérer.", "say": "Veuillez reprendre le tir, s'il vous plaît."}], "quiz": [{"q": "Votre tireur pense qu'un plateau compté zéro était touché, mais il a déjà appelé le plateau suivant. Peut-il encore contester cette décision ?", "options": ["Oui, à la fin de la série", "Oui, par écrit auprès du jury", "Non : appeler le plateau suivant revient à accepter la décision précédente", "Oui, si la planche est d'accord"], "answer": 2, "why": "En appelant le plateau suivant, le tireur accepte la décision précédente, et de toute façon les décisions bon/zéro ne vont jamais devant le jury."}, {"q": "Quelle décision PEUT faire l'objet d'un appel auprès du jury ?", "options": ["Le fait qu'un plateau soit bon ou zéro", "Un No bird", "La régularité d'une trajectoire", "Une autre décision de l'arbitre, comme une pénalité de retard"], "answer": 3, "why": "Les décisions bon/zéro, No bird et de trajectoire sont définitives ; les autres décisions de l'arbitre peuvent aller devant le jury par écrit, avec une caution."}, {"q": "En Parcours de Chasse – Sporting™, quel est le montant de la caution pour un appel écrit auprès du jury ?", "options": ["40 % du montant de l'engagement", "Le montant total de l'engagement", "50 euros forfaitaires", "Aucune caution n'est nécessaire"], "answer": 0, "why": "Le règlement du Sporting™ fixe la caution à 40 % du montant de l'engagement ; elle est restituée si le jury donne raison au tireur."}]}, {"id": "referee-categories", "minutes": 5, "title": "Catégories : Junior, Dame, Homme, Senior, Vétéran, Master", "body": ["Outre le classement scratch (général), où tout le monde concourt ensemble, les épreuves FITASC classent les tireurs par catégories selon l'âge et le sexe. À partir du 1er janvier 2027, le tableau international du Parcours de Chasse – Sporting™ et du Compak® Sporting compte six catégories : Junior (13–20 ans), Dame (à partir de 13 ans), Homme (21–55 ans), Senior (56–65 ans), Vétéran (66–72 ans) et Master (à partir de 73 ans, hommes et femmes). Pour les épreuves antérieures à cette date, consultez le tableau alors en vigueur sur le site de la FITASC.", "C'est l'année de naissance qui compte, pas la date d'anniversaire. Un tireur passe dans une nouvelle catégorie le 1er janvier de l'année où il atteint l'âge requis. Pour la saison 2027, cela donne : Junior nés en 2007–2014, Homme nés en 1972–2006, Senior 1962–1971, Vétéran 1955–1961, Master nés avant 1955. Les limites avancent d'un an à chaque saison.", "Le plus grand piège pour l'interprète est « Senior ». Dans le langage courant, et dans beaucoup de sports, il évoque les « adultes », mais à la FITASC, Senior désigne la tranche d'âge 56–65 ans ; la principale catégorie adulte est Homme. Ne le traduisez pas par « adultes ». « Master » est un autre piège : la catégorie d'âge FITASC à partir de 73 ans n'a rien à voir avec la « Master class » de la NSCA, qui est un niveau de compétence.", "Les équipes ont leurs propres règles : en général trois tireurs, mais l'équipe Homme en Sporting™ en compte quatre. Un junior placé dans l'équipe Homme, ou une junior dans l'équipe Dame, doit aussi s'inscrire individuellement dans cette catégorie. Les fédérations nationales et les clubs peuvent utiliser leurs propres catégories : vérifiez donc toujours le programme de la compétition et, lors des barrages, rappelez-vous que les catégories ont leur propre podium."], "key_points": ["Six catégories FITASC à partir de 2027 : Junior, Dame, Homme, Senior, Vétéran, Master", "L'année de naissance décide ; la nouvelle catégorie commence le 1er janvier", "Senior = 56–65 ans, pas « adultes » ; la principale catégorie adulte est Homme", "Master FITASC (73 ans et plus) ≠ Master class de la NSCA", "Équipes de 3 ; équipe Homme en Sporting™ = 4 ; les programmes nationaux peuvent différer"], "terms": ["category", "veteran", "team", "shoot-off", "entry"], "sources": [{"title": "FITASC — Categories", "url": "https://www.fitasc.com/competitions/categories"}], "sim": null, "rule_refs": [{"book": "categories", "id": "junior", "label": "Junior"}, {"book": "categories", "id": "lady", "label": "Lady"}, {"book": "categories", "id": "men", "label": "Men"}, {"book": "categories", "id": "senior", "label": "Senior"}, {"book": "categories", "id": "veteran", "label": "Veteran"}, {"book": "categories", "id": "master", "label": "Master"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}], "coach_says": [{"en": "Which category are you shooting in?", "meaning": "Question posée à l'inscription : Junior, Dame, Homme, Senior, Vétéran ou Master.", "say": "Dans quelle catégorie tirez-vous ?"}, {"en": "He’s a Senior now.", "meaning": "Il est dans la tranche 56–65 ans cette saison.", "say": "Il est Senior maintenant."}, {"en": "She won the Lady category and was fourth overall.", "meaning": "Première chez les dames, quatrième au classement scratch.", "say": "Elle a gagné la catégorie Dame et elle est quatrième au général."}, {"en": "There’s a shoot-off for Veteran bronze.", "meaning": "Deux Vétérans ou plus sont à égalité pour la troisième place de leur catégorie.", "say": "Il y a un barrage pour le bronze Vétéran."}], "quiz": [{"q": "Un tireur né en 1971 s'inscrit à une compétition FITASC en 2027. Quelle catégorie ?", "options": ["Homme", "Senior", "Vétéran", "Master"], "answer": 1, "why": "Il a 56 ans en 2027 : il est donc Senior dès le 1er janvier, quelle que soit sa date d'anniversaire."}, {"q": "Comment traduire pour un client la catégorie FITASC « Senior » ?", "options": ["« Adultes »", "« Tireurs expérimentés »", "« Haut niveau »", "« La tranche d'âge 56–65 ans »"], "answer": 3, "why": "À la FITASC, Senior est une tranche d'âge de 56 à 65 ans ; la principale catégorie adulte est Homme."}, {"q": "Combien de tireurs compte une équipe Homme en Parcours de Chasse – Sporting™ ?", "options": ["Quatre", "Trois", "Six", "Cinq"], "answer": 0, "why": "Les équipes comptent généralement trois tireurs, mais l'équipe Homme en Sporting™ en compte quatre."}]}]}, {"id": "etiquette", "icon": "shield", "title": "Sécurité et étiquette", "intro": "Sur un stand de tir, la sécurité passe avant toute traduction, et les bonnes manières gardent la planche calme et concentrée. Cette mission montre comment on manipule les fusils, comment on se comporte autour du poste et dans une planche, et ce que chacun, vous compris, doit porter.", "lessons": [{"id": "etiquette-gun-safety", "minutes": 5, "title": "Sécurité des armes : ouvert, vide, canons dans une direction sûre", "body": ["Tout fusil est considéré comme dangereux, même vide. Hors du poste, il se porte ouvert : un superposé cassé sur l'avant-bras, un semi-automatique culasse ouverte, les canons dirigés droit vers le haut ou droit vers le bas. Les bretelles sont interdites. Quand personne ne l'utilise, le fusil est posé debout dans un râtelier. Personne ne touche le fusil d'un autre tireur sans sa permission.", "Les cartouches n'entrent dans le fusil que sur le poste, canons dirigés vers la zone de tir, et seulement quand l'arbitre ou le moniteur l'autorise. Un semi-automatique n'en contient pas plus de deux. Avant de se retourner sur le poste, le tireur ouvre le fusil et retire toutes les cartouches, tirées ou non. Pendant la présentation des plateaux et pendant tout arrêt, les fusils restent ouverts.", "Si le coup ne part pas, le tireur reste en place, le fusil dirigé vers la zone de tir, et ne l'ouvre pas ni ne touche à la sûreté tant que l'arbitre ne l'a pas vérifié. C'est à la fois une règle de sécurité et une règle de comptage : ouvrir trop tôt coûte le plateau. Épauler et suivre un plateau imaginaire hors du poste, ou pendant que quelqu'un d'autre tire, est également interdit, et les fusils ne s'essaient qu'à un poste d'essai, jamais sur le poste de compétition.", "Quand quelqu'un crie « Stop! » ou « Cease fire! » (cessez-le-feu), tout le monde s'arrête immédiatement et ouvre son fusil. Ne traduisez pas cela par une phrase : répétez « Stop ! » à voix haute dans la langue de vos invités et vérifiez que leurs fusils sont ouverts. Si un invité se tourne vers vous avec un fusil pour vous demander quelque chose, faites-lui d'abord signe de baisser les canons, et traduisez ensuite."], "key_points": ["Hors du poste : fusil ouvert, vide, canons vers le haut ou vers le bas, pas de bretelle", "On ne charge que sur le poste, vers la zone de tir, avec autorisation ; semi-automatique 2 cartouches max.", "Ouvrir et décharger avant de se retourner ; fusils ouverts pendant la présentation et les arrêts", "Après un raté : rester en place, ne pas ouvrir, attendre l'arbitre", "« Stop ! » se répète, il ne s'explique pas"], "terms": ["safety", "gun-handling", "muzzle", "gun-rack", "loading", "malfunction", "mock-shooting", "gun-test", "cease-fire", "semi-automatic"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "sporting", "id": "ch7-touching-sharing", "label": "7 · Other shooters' guns; sharing a gun"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "sporting", "id": "ch3-testing-guns", "label": "3 · No test shots on the stand"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-open-gun", "label": "21 · Keep the gun open: turning round, target viewing, interruptions"}, {"book": "compak", "id": "ch11-testing-guns", "label": "11 · Where to test your gun"}], "coach_says": [{"en": "Guns open and empty between stands, please.", "meaning": "Pour aller au poste suivant, le fusil est cassé et ne contient aucune cartouche.", "say": "Fusils ouverts et vides entre les postes, s'il vous plaît."}, {"en": "Break your gun and show me it’s clear.", "meaning": "Ouvrez le fusil (on dit aussi « cassez » le fusil, sans l'abîmer !) pour que je voie que les chambres sont vides.", "say": "Cassez votre fusil et montrez-moi qu'il est vide."}, {"en": "Don’t load until you’re on the stand and I say so.", "meaning": "Aucune cartouche dans le fusil pendant que l'on marche ou que l'on attend.", "say": "Ne chargez pas avant d'être sur le poste et que je vous le dise."}, {"en": "Muzzles down when you turn round.", "meaning": "Ne laissez jamais les canons se diriger vers des personnes, même fusil ouvert.", "say": "Les canons vers le bas quand vous vous retournez."}, {"en": "Stop! Stop! Guns open!", "meaning": "Arrêt d'urgence : cessez de tirer, ouvrez le fusil, attendez.", "say": "Stop ! Stop ! Fusils ouverts !"}], "quiz": [{"q": "Comment porte-t-on un semi-automatique entre les postes ?", "options": ["Fermé, sûreté mise", "Culasse ouverte, canon dirigé droit vers le haut ou vers le bas", "À la bretelle sur l'épaule", "Chargé d'une cartouche"], "answer": 1, "why": "Les fusils se portent ouverts, les semi-automatiques culasse ouverte, canons droit vers le haut ou vers le bas ; les bretelles sont interdites."}, {"q": "Le fusil fait clic mais le coup ne part pas. Que doit faire le tireur ?", "options": ["L'ouvrir aussitôt pour regarder", "Se retourner pour le montrer au moniteur", "Rester en place, fusil vers la zone de tir, sans l'ouvrir ni toucher à la sûreté jusqu'à la vérification par l'arbitre", "Mettre la sûreté et appeler de nouveau"], "answer": 2, "why": "Les deux règlements imposent au tireur de rester en place jusqu'à l'examen par l'arbitre ; ouvrir ou toucher à la sûreté avant donne zéro."}, {"q": "Quelqu'un crie « Cease fire! ». Quelle est la première tâche de l'interprète ?", "options": ["Répéter « Stop ! » à voix haute et vérifier que les invités ouvrent leurs fusils", "Expliquer pourquoi le tir s'est arrêté", "Demander au moniteur ce qui s'est passé", "Attendre que l'invité pose la question"], "answer": 0, "why": "Un arrêt d'urgence se répète immédiatement ; les explications ne viennent que lorsque tous les fusils sont ouverts."}]}, {"id": "etiquette-on-the-stand", "minutes": 5, "title": "Autour du poste : silence, distance, immobilité", "body": ["Un tireur sur le poste a besoin d'une concentration totale, du chargement jusqu'à l'ouverture du fusil après le dernier coup. Le règlement place les zones d'attente près du poste, mais précise qu'elles ne doivent pas déranger le tireur. En pratique, cela signifie : voix basse ou silence, aucun mouvement brusque dans le champ de vision du tireur, fusils ouverts, téléphones en silencieux et dans la poche. Le règlement ne parle pas des téléphones, mais tous les stands attendent cette politesse.", "Restez derrière le tireur, jamais à côté du poste ni devant. En Compak® Sporting, un cadre limiteur d'angle de tir limite le swing de chaque tireur ; en Parcours de Chasse – Sporting™, les postes de nombreux stands sont équipés d'une cage. Tous les autres attendent derrière, hors de toute ligne possible des canons. En Compak®, le tireur en attente se tient derrière le pas de tir 1, et un tireur qui a terminé attend sans gêner le suivant.", "Gêner un tireur a des conséquences réglementaires. Si l'arbitre constate qu'un tireur a été manifestement gêné, le plateau est un No bird et il est relancé. Le simulacre de tir pendant qu'un membre de la planche tire est interdit. Seul le tireur dont c'est le tour tire, et seulement sur son propre plateau.", "Pour vous, cette leçon est pratique. Arrêtez de parler quand votre invité monte sur le poste, même au milieu d'une phrase. Ne répondez pas aux questions tant que le fusil est fermé. Ne reprenez la parole que lorsque le fusil est ouvert : entre les plateaux, entre les doublés ou après le poste. Un conseil manqué coûte moins cher qu'un doublé gâché par votre voix."], "key_points": ["Silence, immobilité, fusils ouverts, téléphones muets derrière le tireur", "Se tenir derrière le poste, la cage ou le L.A.T., jamais à côté ni devant", "Un tireur manifestement gêné obtient un No bird", "Pas de simulacre de tir pendant qu'un autre tire", "Interprète : parler seulement quand le fusil est ouvert"], "terms": ["quiet-on-stand", "shooting-stand", "conduct", "no-bird", "mock-shooting", "rotation"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch8-own-turn-live-animals", "label": "8 · Shoot only in turn; not at others' targets or animals"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}], "coach_says": [{"en": "Quiet behind, please — she’s on.", "meaning": "La tireuse est sur le poste ; tout le monde arrête de parler.", "say": "Silence derrière, s'il vous plaît : elle est au poste."}, {"en": "Wait until he’s opened his gun.", "meaning": "Personne ne parle ni ne bouge tant que le tireur n'a pas terminé et ouvert son fusil.", "say": "Attendez qu'il ait ouvert son fusil."}, {"en": "Stand right behind me so you can see what I see.", "meaning": "À l'entraînement, le moniteur veut que vous soyez juste derrière lui, hors du swing.", "say": "Mettez-vous juste derrière moi pour voir ce que je vois."}, {"en": "Keep out of his line, please.", "meaning": "Vous êtes dans le champ de vision du tireur ou près de la trajectoire des canons ; reculez.", "say": "Sortez de sa ligne, s'il vous plaît."}], "quiz": [{"q": "Où se tient l'interprète pendant que son invité tire ?", "options": ["À côté du tireur, pour voir son visage", "Devant le poste, pour voir le plateau", "Derrière le poste, hors de toute ligne des canons", "Là où l'arbitre ne peut pas le voir"], "answer": 2, "why": "Tout le monde attend derrière le poste ou la cage ; à côté du tireur est l'endroit le plus dangereux."}, {"q": "Une conversation téléphonique bruyante derrière le poste gêne manifestement le tireur au moment du tir. Que peut décider l'arbitre ?", "options": ["No bird : le plateau est relancé", "Zéro pour le tireur", "Rien, les téléphones ne figurent pas dans le règlement", "Carton jaune pour le tireur"], "answer": 0, "why": "Si l'arbitre constate que le tireur a été manifestement gêné, le plateau est un No bird."}, {"q": "Quel est le bon moment pour transmettre la remarque du moniteur ?", "options": ["Pendant que le tireur appelle le plateau", "Entre l'appel et le tir", "Dès que le moniteur a fini de parler", "Quand le fusil est ouvert : entre les plateaux, les doublés ou après le poste"], "answer": 3, "why": "La routine du tireur ne doit pas être interrompue ; ne parlez qu'une fois le fusil ouvert."}]}, {"id": "etiquette-squad", "minutes": 5, "title": "Les bonnes manières dans une planche", "body": ["Une planche (squad) regroupe jusqu'à six tireurs tirés au sort qui tirent ensemble. La ponctualité est la première des politesses, et c'est aussi une règle. En Parcours de Chasse – Sporting™, un tireur absent est appelé trois fois en l'espace d'une minute, et les plateaux non tirés sont comptés zéro. En Compak® Sporting, un tireur qui arrive après que le premier tireur de la planche a appelé reçoit 25 zéros pour la série, et il est obligatoire de se présenter à l'arbitre au préalable.", "L'ordre compte. En Sporting™, l'ordre tourne à chaque poste et pour les doublés ; en Compak®, les tireurs se décalent d'un pas de tir vers la droite après chaque passage. Personne ne monte sur le poste tant que le tireur précédent ne l'a pas quitté. Quand il est appelé, le tireur est prêt immédiatement, avec assez de cartouches pour toute la série.", "L'arbitre décide seul. Les membres de la planche ne donnent pas leur avis sur un plateau touché ou non, sauf si l'arbitre le leur demande. Une critique ouverte d'une décision, de la part de tireurs ou de spectateurs, est considérée comme une tentative d'influencer l'arbitre. Une perte de sang-froid, comme jeter son fusil ou insulter quelqu'un, est portée devant le jury et peut entraîner l'exclusion.", "Au-delà du règlement, il y a les usages. Les tireurs saluent généralement l'arbitre et la planche au début, disent « bien tiré » ou « joli coup » après un bon poste, et « pas de chance » après un manqué, mais ne commentent jamais la technique d'un inconnu. Un mot de remerciement au pulleur et à l'arbitre à la fin, une poignée de main et du calme à l'affichage des résultats sont courants sur de nombreux stands. Traduisez ces politesses avec chaleur : elles comptent."], "key_points": ["Être à l'heure et se présenter à l'arbitre ; un retard coûte des zéros", "Respecter la rotation ; ne monter que lorsque le poste est libre", "Seul l'arbitre décide ; pas de commentaires sur les plateaux touchés", "Une perte de sang-froid peut entraîner l'exclusion", "Usages : saluer, « bien tiré », remercier le pulleur et l'arbitre"], "terms": ["squad", "rotation", "referee", "trapper", "conduct", "round"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-ready", "label": "9 · Be ready with a full round of equipment and ammunition"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch21-loss-of-control", "label": "21 · Loss of self-control"}], "coach_says": [{"en": "Number twelve — last call!", "meaning": "L'arbitre appelle un tireur absent ; s'il ne vient pas, ses plateaux seront comptés zéro.", "say": "Dossard douze, dernier appel !"}, {"en": "You’re next — get ready.", "meaning": "Préparez-vous maintenant : lunettes, protections auditives, cartouches, mais ne montez pas avant que le poste soit libre.", "say": "Vous êtes le suivant, préparez-vous."}, {"en": "Well shot!", "meaning": "Un compliment sincère après un bon plateau ou un bon poste.", "say": "Bien tiré !"}, {"en": "Bad luck.", "meaning": "Une marque de sympathie amicale après un manqué, pas une critique.", "say": "Pas de chance."}, {"en": "Thanks, ref — thanks for pulling.", "meaning": "Remercier l'arbitre et le pulleur à la fin de la série.", "say": "Merci, l'arbitre, et merci pour le lancer."}], "quiz": [{"q": "Compak® Sporting, tir par planches : votre invité arrive après que le premier tireur de sa planche a appelé le premier plateau. Que se passe-t-il ?", "options": ["Il rejoint la planche au pas de tir suivant", "Il reçoit 25 zéros pour cette série", "Il tire en dernier sans pénalité", "La série recommence"], "answer": 1, "why": "En Compak® par planches, la limite est le premier appel de la planche ; après lui, le retardataire reçoit 25 zéros (un recours auprès du jury est possible)."}, {"q": "Un coéquipier de la planche dit à voix haute à l'arbitre qu'il se trompe sur un plateau. Comment le règlement considère-t-il cela ?", "options": ["Comme une information utile", "Comme une réclamation officielle", "Comme une tentative d'influencer l'arbitre", "Comme rien du tout"], "answer": 2, "why": "Les autres personnes qui critiquent ouvertement une décision sans y être invitées par l'arbitre commettent une tentative d'influence ; seul le tireur concerné peut réclamer."}, {"q": "En Parcours de Chasse – Sporting™, comment fonctionne l'ordre de tir dans une planche ?", "options": ["Il tourne à chaque poste et pour les doublés", "Il est fixe pour toute la journée", "Le meilleur tireur commence toujours", "L'arbitre le choisit librement"], "answer": 0, "why": "Les planches de six sont tirées au sort, et l'ordre tourne à chaque poste et aussi pour les doublés."}]}, {"id": "etiquette-protection-and-dress", "minutes": 5, "title": "Oreilles, yeux et tenue : les vôtres aussi", "body": ["Les protections auditives sont obligatoires pour toute personne sur un parcours ou à proximité : tireurs, arbitres, personnel et spectateurs. En Parcours de Chasse – Sporting™, les lunettes de protection sont obligatoires, sans exception, pour les tireurs, les arbitres, le personnel et toute personne proche d'un poste. En Compak® Sporting, la règle sur les lunettes cite les concurrents, les arbitres et le personnel. Un tireur qui monte sur le poste sans l'une ou l'autre est considéré comme absent.", "Cela vous concerne aussi. Debout derrière le poste, vous êtes « à proximité d'un parcours ». Le casque anti-bruit électronique est le meilleur outil de l'interprète : il atténue la détonation mais laisse passer les voix, si bien que vous entendez le moniteur et l'arbitre. Des lunettes de tir claires ou teintées vous protègent aussi des éclats de plateaux qui retombent ; une casquette aide également.", "Le code vestimentaire est une question de sécurité et de respect. Pas de shorts courts : seulement des shorts longs de type bermuda, qui s'arrêtent au plus 5 cm au-dessus du genou. Les chemises doivent avoir au moins des manches courtes et un col ou une encolure ronde de type T-shirt ; un gilet sur un torse nu est interdit. Les sandales sont interdites, et en Compak® cela vaut à l'entraînement comme en compétition. Le dossard se porte dans le dos, entre les épaules et la taille, entièrement visible, ni plié ni découpé.", "Un premier manquement aux règles de tenue ou de dossard vaut un avertissement ; s'il n'est pas corrigé, des pénalités suivent, jusqu'à l'exclusion par le jury. Lors des cérémonies, les membres des équipes portent la tenue de l'équipe nationale ou un pantalon habillé et un blazer, et tous les lauréats doivent assister à la remise des prix. Habillez-vous comme un professionnel discret : chaussures fermées, vêtements neutres, rien qui flotte ou qui brille dans les yeux du tireur."], "key_points": ["Protections auditives pour tous près d'un parcours, spectateurs et interprètes compris", "Lunettes : Sporting™ — toute personne proche d'un poste ; Compak® — concurrents, arbitres, personnel", "Sans elles, un tireur est considéré comme absent", "Bermuda au plus 5 cm au-dessus du genou, manches, pas de torse nu sous le gilet, pas de sandales", "Dossard dans le dos, entièrement visible ; premier manquement = avertissement"], "terms": ["hearing-protection", "electronic-ear-muffs", "earplugs", "safety-glasses", "dress-code", "competitor-number", "shooting-vest", "prize-giving"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "sporting", "id": "ch17-ceremonies", "label": "17 · Dress at the opening and closing ceremonies"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch7-ceremonies", "label": "7 · Dress for opening and closing ceremonies"}], "coach_says": [{"en": "Eyes and ears on before you leave the clubhouse.", "meaning": "Mettez les lunettes et les protections auditives avant de partir vers les parcours.", "say": "Lunettes et casque avant de quitter le club-house."}, {"en": "Where are your ears?", "meaning": "« Ears » = les protections auditives, pas les oreilles elles-mêmes.", "say": "Où sont vos protections auditives ?"}, {"en": "You can’t shoot in sandals here.", "meaning": "Des chaussures fermées sont exigées pour des raisons de sécurité.", "say": "Ici, on ne tire pas en sandales."}, {"en": "Your number’s folded — it has to be fully visible.", "meaning": "Le dossard dans le dos doit être complet et visible ; sinon, avertissement.", "say": "Votre dossard est plié : il doit être entièrement visible."}], "quiz": [{"q": "Votre tireur monte sur le poste sans lunettes de protection. Comment le règlement le traite-t-il ?", "options": ["Il reçoit un avertissement et peut tirer", "Il peut tirer si le moniteur est d'accord", "Il perd un plateau", "Il est considéré comme absent"], "answer": 3, "why": "Dans les deux disciplines, un tireur sans protection des yeux ou des oreilles sur le poste est considéré comme absent."}, {"q": "Quels shorts sont autorisés ?", "options": ["N'importe quel short de sport", "Les shorts de type bermuda qui s'arrêtent au plus 5 cm au-dessus du genou", "Les shorts seulement en Compak®", "Aucun short"], "answer": 1, "why": "Les shorts courts sont interdits ; les shorts longs de type bermuda, pas plus haut que 5 cm au-dessus du genou, sont acceptés."}, {"q": "Pourquoi le casque anti-bruit électronique est-il un bon choix pour un interprète ?", "options": ["Il atténue la détonation mais laisse passer les voix", "Il n'est pas obligatoire pour les interprètes", "Il bloque complètement tous les sons", "Il enregistre le moniteur"], "answer": 0, "why": "Les protections auditives sont obligatoires près d'un parcours, et un casque électronique vous permet d'entendre le moniteur et l'arbitre."}]}]}, {"id": "interpreter", "icon": "speech", "title": "L'interprète au travail", "intro": "Tout ce que vous avez appris se rejoint ici : ce que vous pouvez dire ou non, où vous placer, les mots qui piègent même les linguistes expérimentés, les nombres et les unités, le vocabulaire britannique et américain, et enfin une séance d'entraînement complète, du premier « bonjour » au débriefing.", "lessons": [{"id": "interpreter-role", "minutes": 5, "title": "Votre rôle : entraînement ou compétition", "body": ["À l'entraînement, vous êtes la voix du moniteur. Rendez chaque consigne intégralement, dans l'ordre et sur le ton du moniteur : ferme quand il s'agit de sécurité, chaleureux quand c'est un compliment. N'adoucissez pas les critiques, n'ajoutez pas de raisons que le moniteur n'a pas données, et n'ajoutez jamais de conseils techniques de votre cru, même quand vous connaissez la réponse. Si vous n'avez pas entendu un mot, demandez avant de traduire.", "Une compétition, c'est autre chose. Le coaching d'un concurrent pendant la compétition est interdit en Parcours de Chasse – Sporting™ comme en Compak® Sporting : le tireur reçoit un carton jaune, les récidives entraînent d'autres sanctions, et l'arbitre écarte de la zone de tir la personne qui donnait les conseils. L'arbitre décide en outre seul : personne dans la planche ne commente les plateaux touchés, et une critique ouverte d'une décision est considérée comme une tentative d'influencer l'arbitre.", "Voici la partie honnête. Les règlements FITASC ne mentionnent pas du tout les interprètes. Le fait de transmettre mot pour mot les conseils d'un moniteur pendant une compétition constitue-t-il du coaching, et où un interprète peut-il se placer ? Le règlement ne le dit pas. C'est une question ouverte pour la FITASC, et vous ne devez présenter aucune réponse comme officielle.", "En attendant la réponse de la FITASC, appliquez la pratique prudente. En compétition, n'interprétez que la communication avec l'arbitre, le jury et l'organisateur : annonces, décisions, avertissements, réclamations, horaires et planches. Avant l'épreuve, présentez-vous à l'arbitre ou à l'organisateur et convenez de l'endroit où vous vous tiendrez. Si un moniteur vous demande de transmettre un conseil pendant la compétition, refusez poliment et expliquez pourquoi. Cela protège votre tireur d'un carton jaune."], "key_points": ["Entraînement : la voix du moniteur — intégralement, sur le même ton, rien de votre cru", "Compétition : le coaching est interdit (carton jaune, moniteur écarté)", "Question ouverte pour la FITASC : les règlements ne mentionnent pas les interprètes", "Pratique prudente : en compétition, n'interpréter que la communication avec l'arbitre, le jury et l'organisateur", "Présentez-vous à l'arbitre et convenez de l'endroit où vous vous tenez"], "terms": ["coach", "referee", "jury", "yellow-card", "conduct", "interpreter", "coaching"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Tell her she’s lifting her head on the second bird.", "meaning": "Entraînement : transmettez-le intégralement quand le fusil est ouvert.", "say": "Dites-lui qu'elle lève la tête sur le second plateau."}, {"en": "Quick — tell him to give the crosser more.", "meaning": "Compétition : c'est du coaching. Refusez poliment ; ne le transmettez pas.", "say": "Vite, dites-lui de donner plus au traversard."}, {"en": "Who are you with?", "meaning": "L'arbitre demande pourquoi vous êtes près du poste ; présentez-vous et indiquez votre rôle.", "say": "Vous êtes avec qui ?"}, {"en": "Ask the referee if I can still change chokes.", "meaning": "Une question de procédure adressée à l'arbitre : vous pouvez l'interpréter.", "say": "Demandez à l'arbitre si je peux encore changer de chokes."}], "quiz": [{"q": "Pendant une série de compétition, le moniteur vous demande de dire au tireur « more lead on the crosser ». Que faites-vous ?", "options": ["Je le chuchote rapidement", "Je le traduis après le plateau suivant", "Je refuse poliment : ce serait du coaching, qui est interdit", "Je demande à l'arbitre de le transmettre"], "answer": 2, "why": "Le coaching en compétition est interdit et le tireur recevrait un carton jaune ; le règlement ne dit pas si relayer un conseil est autorisé, donc restez prudent."}, {"q": "Que disent les règlements FITASC sur les interprètes ?", "options": ["Ils peuvent se tenir sur le poste", "Ils ont besoin d'une licence d'arbitre", "Ils sont considérés comme des moniteurs", "Rien : c'est une question ouverte"], "answer": 3, "why": "Les règlements ne mentionnent pas les interprètes : leur place exacte en compétition est donc une question ouverte pour la FITASC."}, {"q": "À l'entraînement, le moniteur dit « Not bad, but you stopped the gun. » Comment traduisez-vous ?", "options": ["Intégralement et sur le même ton, les deux parties", "Seulement le compliment, pour garder l'invité de bonne humeur", "Seulement la faute, pour gagner du temps", "En ajoutant votre propre conseil pour corriger"], "answer": 0, "why": "Vous n'adoucissez ni n'amplifiez : tout le message, sur le ton du moniteur, sans rien de votre cru."}]}, {"id": "interpreter-position", "minutes": 5, "title": "Où se placer et quand parler", "body": ["À l'entraînement, placez-vous juste derrière le tireur, à côté du moniteur, derrière le poste ou la cage et hors de toute ligne des canons. De là, vous voyez ce que voit le moniteur, le plateau et les canons en même temps, et le moniteur peut vous parler à voix basse. À côté du tireur est l'endroit le plus dangereux ; devant le poste, c'est hors de question.", "Choisissez le mode selon le moment. L'interprétation consécutive (le moniteur parle, fait une pause, vous parlez) convient au briefing de sécurité, au trajet entre les postes et au débriefing. L'interprétation chuchotée, ou chuchotage, permet au moniteur de continuer à parler pendant que vous chuchotez à l'oreille du tireur, derrière lui ; c'est fatigant, alors alternez les deux. Convenez d'un signe « pause, je traduis », par exemple une paume levée.", "Tout est question de timing. La routine du tireur va de la fermeture du fusil jusqu'au coup. Ne parlez que lorsque le fusil est ouvert : entre les plateaux, entre les doublés, après le poste. Entre les doublés, reprenez les consignes courtes du moniteur, « plus devant », « la tête en bas », « pareil », et gardez les longues explications pour plus tard. Pensez au chronomètre : en Parcours de Chasse – Sporting™, un tireur dispose au maximum de 15 secondes entre les plateaux ou les doublés, et en Compak® Sporting de 10 secondes pour appeler. Vos paroles utilisent aussi ce temps.", "En compétition, attendez là où attend la planche, près du poste mais sans jamais déranger le tireur : un tireur manifestement gêné obtient un No bird, et personne ne veut en être la cause. Apprenez les signes de la main du moniteur au début et traduisez-les une fois pour vos invités ; ensuite, ils auront moins besoin de vous, et c'est bon signe."], "key_points": ["Entraînement : juste derrière le tireur, à côté du moniteur, hors de la ligne des canons", "Consécutive pour les briefings et débriefings ; chuchotage sur le poste ; alterner", "Ne parler que lorsque le fusil est ouvert", "Consignes courtes entre les doublés ; délais de 15 s (Sporting™) et 10 s (Compak®)", "Compétition : attendre avec la planche, ne jamais déranger"], "terms": ["quiet-on-stand", "shooting-stand", "coach", "firing-time", "no-bird", "chuchotage", "consecutive-interpreting", "hand-signals"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Stand right behind me.", "meaning": "Derrière le moniteur et le tireur, hors du swing.", "say": "Mettez-vous juste derrière moi."}, {"en": "Head on the stock — just whisper it to him, I’ll keep going.", "meaning": "Passez au chuchotage et transmettez la consigne à voix basse ; le moniteur ne fera pas de pause.", "say": "La tête sur la crosse : chuchotez-le-lui, je continue."}, {"en": "When I do this — hands apart — it means more in front.", "meaning": "Le moniteur explique un signe de la main ; traduisez-le une fois pour le groupe.", "say": "Quand je fais ça, les mains écartées, ça veut dire plus devant."}, {"en": "Wait — let him finish the pair.", "meaning": "Gardez le conseil jusqu'à ce que le fusil soit de nouveau ouvert.", "say": "Attendez, laissez-le finir le doublé."}, {"en": "Sorry — did you say “under it” or “on it”?", "meaning": "Faites répéter en proposant les deux options entendues ; plus rapide que « répétez, s'il vous plaît ».", "say": "Pardon, vous avez dit « dessous » ou « dessus » ?"}], "quiz": [{"q": "Où devez-vous vous placer pendant une séance d'entraînement sur un poste de Sporting™ ?", "options": ["À côté du tireur, pour voir ses yeux", "Derrière le tireur, à côté du moniteur, hors de la ligne des canons", "Devant la cage, face au tireur", "À côté du lanceur"], "answer": 1, "why": "De derrière, vous voyez ce que voit le moniteur et vous restez en sécurité ; à côté ou devant, c'est dangereux."}, {"q": "Qu'est-ce que le chuchotage ?", "options": ["Interpréter après la pause de l'orateur", "La traduction écrite du règlement", "La traduction des signes de la main", "L'interprétation simultanée chuchotée à l'oreille de l'auditeur"], "answer": 3, "why": "Le chuchotage est une interprétation simultanée chuchotée ; la consécutive est le mode « pause, puis parole »."}, {"q": "En Compak® Sporting, de combien de temps dispose un tireur pour appeler après que le plateau du pas de tir précédent a été tiré ?", "options": ["10 secondes", "15 secondes", "30 secondes", "Pas de limite"], "answer": 0, "why": "Le Compak® accorde au maximum 10 secondes pour appeler ; le Sporting™ accorde 15 secondes entre les plateaux ou les doublés."}]}, {"id": "interpreter-false-friends", "minutes": 6, "title": "Les faux amis du stand de tir", "body": ["Le pire piège, c'est la fumée. Le « Smoked it! » d'un moniteur (ou « inked it », « powdered it ») signifie un tir parfait : le plateau s'est volatilisé dans un nuage. Mais selon le règlement, un plateau qui ne dégage que de la poussière ou de la fumée, sans morceau visible, est un zéro. Un « chip », un petit morceau visible, est un plateau bon. Traduisez donc le « smoked it » du moniteur par « pulvérisé », et le « only dust » de l'arbitre par « seulement de la poussière : zéro ».", "Les mots du comptage ne sont pas littéraux. « Dead » et « kill » signifient un plateau touché (« bon », « cassé »), jamais « mort » ou « tué ». « Lost » est un manqué (« zéro », « manqué » ; « perdu » au sens du règlement), pas un objet égaré. « Dropped two » signifie deux plateaux manqués. « Straight » dans « 25 straight » signifie un sans-faute, pas « tout droit ».", "Les mots du matériel et des lieux. Un « trap » est la machine qui lance (le lanceur), pas un « piège » (Trap est aussi une discipline olympique). Un « stand » est une position de tir, un poste, et non le « stand de tir » français, qui désigne tout le terrain ; un « peg » est l'emplacement marqué, pas un piquet ; un « broken gun » est un fusil ouvert. « Pull! » est l'appel du plateau, « pull-away » une méthode d'avance, « length of pull » une longueur de crosse. Une « card » est une feuille de marque ou un carton jaune ou rouge. « On report » signifie au bruit du coup de feu. Un « squad » est la planche FITASC de six tireurs au maximum ; dans ClayAway, ce mot désigne aussi un sous-groupe d'un tour.", "D'autres langues ajoutent des pièges. La « chandelle » française est un plateau presque vertical (un teal anglais), pas la chandelle anglaise. Le français « en battue » et l'italien « in battuta » désignent le gibier rabattu, pas le plateau battue ; en portugais, « batida » est le plateau battue, et « de batida » veut dire rabattu. Pour un plateau touché, un arbitre français dit « Bon », un italien « Buono » ; celui qui lance les plateaux est un « pulleur » ou « puller ». Le règlement italien emploie des mots différents pour la planche : batteria en Parcours de Chasse – Sporting™, squadra di tiro en Compak®."], "key_points": ["« Smoked it » du moniteur = tir parfait ; « only dust or smoke » du règlement = zéro", "Dead / kill = bon ; lost / dropped = manqué ; straight = sans-faute", "Trap = lanceur ; stand = un poste ; peg = l'emplacement ; broken gun = fusil ouvert", "Pull, card, report et squad ont chacun plusieurs sens", "La chandelle française et « en battue » diffèrent des mots anglais"], "terms": ["one", "zero", "visible-piece", "trap", "shooting-stand", "squad", "call", "double-on-report", "pull-away", "length-of-pull", "yellow-card", "score-sheet", "battue", "teal", "false-friend", "peg", "smoked-it"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Smoked it!", "meaning": "Tir parfait, le plateau est réduit en poussière. Ce n'est pas la « fumée seulement » du règlement.", "say": "Pulvérisé !"}, {"en": "Only dust — zero.", "meaning": "L'arbitre : aucun morceau visible ne s'est détaché, c'est donc un manqué.", "say": "Seulement de la poussière : zéro."}, {"en": "Just a chip, but it’s dead.", "meaning": "Un petit morceau visible s'est détaché : il compte comme bon.", "say": "Juste un éclat, mais il est bon."}, {"en": "Break your gun.", "meaning": "Ouvrez le fusil. Rien à voir avec le fait de l'abîmer.", "say": "Cassez votre fusil."}, {"en": "Step into the peg.", "meaning": "Placez-vous sur l'emplacement de tir marqué.", "say": "Mettez-vous sur le poste."}, {"en": "The second one’s on report.", "meaning": "Le second plateau est lancé au bruit de votre premier coup.", "say": "Le second part au coup de fusil."}], "quiz": [{"q": "Le moniteur crie « Smoked it! » après un tir. Que s'est-il passé ?", "options": ["Il n'y a eu que de la fumée : un zéro", "Le plateau a été détruit : un tir parfait", "La cartouche a fait long feu", "C'était un plateau flash"], "answer": 1, "why": "Dans l'argot des moniteurs, « smoked it » est un tir parfait ; dans le règlement, « seulement de la poussière ou de la fumée » est un zéro : des sens opposés."}, {"q": "Meilleure traduction française du « Lost. » de l'arbitre ?", "options": ["« Égaré »", "« Temps perdu »", "« Zéro »", "« Le plateau a disparu »"], "answer": 2, "why": "« Lost » est le mot du comptage pour un manqué (zéro), pas quelque chose d'égaré."}, {"q": "Un invité français dit qu'il adore tirer « en battue ». Que veut-il dire ?", "options": ["Le gibier rabattu (oiseaux poussés vers les tireurs)", "Le plateau battue, plat", "Un plateau lancé en doublé", "Un plateau cassé"], "answer": 0, "why": "Le français « en battue » (l'italien « in battuta ») désigne le gibier rabattu ; le plateau battue est une autre chose."}]}, {"id": "interpreter-numbers-and-units", "minutes": 5, "title": "Nombres et unités : pieds, yards, calibres, numéros de plomb", "body": ["Les moniteurs britanniques et américains mesurent l'avance en pieds : « give it three feet » (trois pieds), « a yard in front » (un yard devant), « half a bird » (un demi-plateau), « a barrel's width » (la largeur d'un canon). C'est une image, pas une mesure. Traduisez l'unité telle qu'elle est dite, « trois pieds », et ne la convertissez pas au milieu d'une consigne : 0,9 m sonne précis et change le sens. Expliquez une fois, avant la séance, que les pieds du moniteur sont une impression, et gardez « more », « less », « double it » (plus, moins, doublez) exactement comme ils sont dits.", "Les distances jusqu'aux plateaux, c'est autre chose. « It's about thirty yards » peut se rendre en mètres avec « environ » (« environ 27 mètres »), car un yard fait un peu moins d'un mètre. Les directions sont souvent données sur un cadran d'horloge : droit devant, c'est midi, donc « pick it up at eleven o'clock » (prenez-le à onze heures) est légèrement à gauche. Gardez l'horloge ; ne la transformez pas en degrés.", "Le calibre fonctionne à l'envers. Un « 12-bore » ou « 12 gauge » ne fait pas 12 mm ; plus le nombre est petit, plus le canon est large, donc un calibre 20 est plus étroit. Les deux règlements FITASC autorisent au maximum le calibre 12, avec des canons d'au moins 66 cm (26 pouces). La ligne du gilet en Parcours de Chasse – Sporting™ est à 25 cm, ce que les tireurs britanniques peuvent appeler un peu moins de dix pouces.", "Les cartouches : la FITASC autorise au maximum 28 g de plomb, proche de la « one-ounce load » (charge d'une once) dont parlent les tireurs britanniques, avec des plombs de 2,0 à 2,5 mm. Les numéros de plomb ne sont pas les mêmes dans tous les pays : un n° 9 fait environ 2 mm presque partout, mais d'autres numéros peuvent varier légèrement entre les systèmes britannique, américain et continental. Quand cela compte, demandez les millimètres. Les chokes peuvent être exprimés par des noms, des fractions ou en « thou » (millièmes de pouce) ; traduisez le système qu'a employé le moniteur."], "key_points": ["L'avance en pieds est une image : gardez l'unité, ne convertissez jamais au milieu d'une consigne", "Distance du plateau : les yards peuvent devenir « environ … mètres »", "Cadran d'horloge pour les directions : midi = droit devant", "12 gauge ≠ 12 mm ; FITASC : calibre 12 au maximum, canons ≥ 66 cm (26 pouces)", "28 g ≈ une once ; plombs de 2,0–2,5 mm ; les numéros de plomb varient selon les pays : demandez les mm"], "terms": ["lead", "gauge", "barrel-length", "shot-size", "load-weight", "choke", "cartridge", "clock-face"], "sources": [{"title": "Shotgun Life — Does barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}], "coach_says": [{"en": "Give it three feet.", "meaning": "L'image d'avance que veut le moniteur ; un écart perçu, pas une distance mesurée.", "say": "Donnez-lui trois pieds."}, {"en": "Half that.", "meaning": "Prenez la moitié de l'avance précédente.", "say": "La moitié."}, {"en": "Pick it up at eleven o’clock.", "meaning": "Cherchez le plateau légèrement à gauche de droit devant.", "say": "Prenez-le à onze heures."}, {"en": "It’s about forty yards out.", "meaning": "Le plateau est à environ 37 mètres.", "say": "Il est à une quarantaine de yards, environ 37 mètres."}, {"en": "Put a nine in the bottom barrel.", "meaning": "Mettez une cartouche de plomb n° 9 (environ 2 mm) dans le canon du dessous, qui part généralement en premier.", "say": "Mettez une 9 dans le canon du dessous."}], "quiz": [{"q": "Le moniteur dit « Give it four feet. » Quelle est la meilleure interprétation ?", "options": ["« Avance : environ 1,22 mètre »", "« Avance : quatre pieds »", "« Tirez quatre mètres plus loin »", "« Quatre plateaux devant »"], "answer": 1, "why": "L'avance en pieds est une image ; la convertir au milieu d'une consigne ajoute une fausse précision et change le message."}, {"q": "Quel est le plus gros calibre autorisé en Sporting™ et en Compak® FITASC ?", "options": ["10", "16", "20", "12"], "answer": 3, "why": "Les deux règlements autorisent au maximum le calibre 12 ; un nombre plus petit signifie une âme plus large, donc le 10 n'est pas autorisé."}, {"q": "Un invité britannique demande si ses cartouches « one-ounce » sont réglementaires à une épreuve FITASC. Que savez-vous ?", "options": ["La limite FITASC est de 28 g de plomb (+2 %), soit environ une once", "La FITASC autorise 36 g", "Toute charge est autorisée", "Seuls 24 g sont autorisés"], "answer": 0, "why": "Le règlement autorise jusqu'à 28 g de plomb avec une tolérance de +2 % ; une once fait environ 28 g. La taille des plombs (2,0–2,5 mm) doit aussi convenir."}]}, {"id": "interpreter-english-sporting-vs-fitasc", "minutes": 5, "title": "Vocabulaire britannique et américain face à la FITASC", "body": ["Beaucoup des moniteurs avec qui vous travaillerez ont grandi avec l'English Sporting, régi en Angleterre par la CPSA, ou avec le Sporting Clays américain de la NSCA. Les mots ressemblent à ceux de la FITASC, mais les règles qui sont derrière, non, et la plus grande différence est la position du fusil.", "En English Sporting et à la NSCA, un tireur peut partir « gun up », fusil déjà épaulé, avant d'appeler. En Parcours de Chasse – Sporting™, ce n'est pas autorisé : la crosse reste sous la ligne du gilet jusqu'à l'apparition du plateau, et chaque plateau se tire fusil à l'épaule. Le Compak® Sporting est entre les deux : la position du fusil à l'appel est libre. Ainsi, « pre-mount this one » est un exercice à l'entraînement, mais un carton jaune dans une compétition FITASC de Sporting™. Traduisez-le, et si l'invité doit bientôt concourir, demandez au moniteur s'il faut mentionner la règle.", "Les doublés ont des noms différents. Une « true pair » (anglaise et américaine) est un doublé simultané FITASC. Une « report pair » est un doublé coup de fusil. Une « following pair » est une rafale FITASC. Une « show pair » est la présentation des plateaux avant le tir. Un « peg » est le poste de tir, « station » est le mot américain pour un poste, et une « cage » est le cadre qui l'entoure.", "Le vocabulaire des résultats diffère aussi. « HOA », High Over All, désigne le vainqueur au classement général. Les classes comme AA, A, B ou C sont des niveaux nationaux établis d'après les moyennes, ni des catégories d'âge FITASC, ni les catégories de difficulté A, B et C de la FITASC, qui classent les trajectoires. Même au sein de la FITASC, les doublés diffèrent : en Sporting™, les deux cartouches peuvent être tirées sur un même plateau d'un doublé, en Compak® une seule cartouche par plateau. Demandez-vous toujours à quel règlement pense celui qui parle."], "key_points": ["Gun up : autorisé en English Sporting et à la NSCA, interdit en Sporting™ FITASC, libre en Compak®", "True pair = simultané ; report pair = coup de fusil ; following pair = rafale", "Peg = emplacement de tir ; station = poste (US) ; cage = cadre de protection", "HOA = vainqueur au général ; les classes AA/A/B/C ne sont ni des catégories FITASC ni des catégories de difficulté", "Sporting™ : deux coups autorisés sur un même plateau ; Compak® : un par plateau"], "terms": ["ready-position", "gun-mount", "simultaneous-double", "double-on-report", "rafale-double", "target-presentation", "shooting-stand", "english-sporting", "nsca", "cpsa", "gun-up", "true-pair", "peg", "cage", "hoa", "shooter-class"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "CPSA — English Sporting", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Pre-mount this one for now.", "meaning": "Exercice d'entraînement : partir avec le fusil à l'épaule. Interdit en compétition FITASC de Sporting™.", "say": "Pour l'instant, épaulez d'avance sur celui-ci."}, {"en": "It’s a true pair.", "meaning": "Les deux plateaux partent en même temps (FITASC : doublé simultané).", "say": "C'est un doublé simultané."}, {"en": "Following pair off the left trap.", "meaning": "Deux plateaux du même lanceur, l'un après l'autre (FITASC : rafale).", "say": "Rafale du lanceur de gauche."}, {"en": "Let’s see a show pair.", "meaning": "Lancez le doublé une fois pour que tout le monde le voie avant de tirer.", "say": "Montrez-nous le doublé."}, {"en": "He’s AA class and won HOA last year.", "meaning": "Une classe nationale de haut niveau, et le vainqueur au classement général de l'épreuve.", "say": "Il est en classe AA et il a gagné le classement général l'an dernier."}], "quiz": [{"q": "Un moniteur britannique dit « It's a true pair. » Quel est le terme FITASC ?", "options": ["Un doublé coup de fusil", "Un doublé rafale", "Un doublé simultané", "Un doublé régulier"], "answer": 2, "why": "« True pair » est le nom anglais et américain de deux plateaux lancés ensemble, un doublé simultané FITASC."}, {"q": "Dans quelle discipline un départ « gun up » n'est-il PAS autorisé ?", "options": ["Parcours de Chasse – Sporting™ (FITASC)", "Compak® Sporting", "English Sporting (CPSA)", "Sporting Clays (NSCA)"], "answer": 0, "why": "Le Sporting™ FITASC exige la crosse sous la ligne du gilet jusqu'à l'apparition du plateau ; le Compak® laisse la position du fusil libre."}, {"q": "Un invité lit « Class C » dans des résultats britanniques. De quoi s'agit-il ?", "options": ["D'une catégorie d'âge FITASC", "D'un niveau national établi d'après les moyennes", "De la catégorie de trajectoire FITASC la plus difficile", "D'un type de cartouche"], "answer": 1, "why": "Dans les résultats britanniques et américains, les classes sont des niveaux ; la FITASC n'utilise A/B/C que pour la difficulté des trajectoires et a, à la place, des catégories d'âge."}]}, {"id": "interpreter-session-script", "minutes": 8, "title": "Une séance d'entraînement complète, étape par étape", "body": ["Avant la séance, rencontrez le moniteur pendant cinq minutes. Convenez d'un signe de pause, demandez quelle méthode il enseigne et quels mots il emploie pour l'avance, et apprenez ses signes de la main. Ensuite, le groupe se réunit pour le briefing de sécurité : interprétez-le en consécutive, phrase par phrase, avec fermeté et intégralement.", "Sur le premier poste, le moniteur commence généralement sans cartouches : un test de l'œil directeur, puis la position et la position d'attente. En Parcours de Chasse – Sporting™, le fusil part bas, sous la ligne du gilet ; en Compak® Sporting, la position du fusil à l'appel est libre. Chuchotez ses corrections depuis l'arrière pendant qu'il place les pieds et les mains.", "Vient ensuite la lecture du plateau. Le moniteur le fait voir, demande où le tireur le voit nettement pour la première fois, et fixe le point de prise, le point d'attente et le point de casse. Gardez ces trois termes identiques toute la journée, « point de prise », « point d'attente », « point de casse », pour que l'invité les retienne.", "Place au tir. Entre les plateaux, le moniteur donne des consignes de deux à cinq mots ; vous les reprenez, même longueur, même ordre, pendant que le fusil est ouvert. Quand un manqué est diagnostiqué, « behind », « over the top », « you stopped », traduisez le diagnostic et la correction ensemble. Les compliments se traduisent avec la même énergie.", "Puis les doublés : quel plateau en premier, « les yeux d'abord, ensuite le fusil », le second coup. Enfin le débriefing, de nouveau en consécutive, où le moniteur résume deux ou trois points. Notez-les dans les deux langues et remettez la note à l'invité. Ci-dessous, un enchaînement réel de phrases dans l'ordre où vous les entendrez."], "key_points": ["Avant : signe de pause, méthode, mots de l'avance, signes de la main", "Briefing de sécurité : en consécutive, ferme, intégral", "Les trois mêmes termes toute la journée : point de prise, d'attente, de casse", "Consignes entre les plateaux : même longueur, fusil ouvert ; diagnostic + correction ensemble", "Débriefing : notez les points clés dans les deux langues"], "terms": ["coach", "safety", "eye-dominance", "master-eye", "stance", "ready-position", "gun-mount", "pick-up-point", "hold-point", "break-point", "lead", "maintained-lead", "pull-away", "head-lift", "stopping-the-gun", "follow-through", "double-on-report", "crosser", "rabbit", "choke"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "NSSA-NSCA — Foot position (Ask the instructor)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}], "coach_says": [{"en": "Morning, everyone. Before we load anything, a quick safety briefing.", "meaning": "Début de la séance ; interprétez le briefing en consécutive et intégralement.", "say": "Bonjour à tous. Avant de charger quoi que ce soit, un petit briefing de sécurité."}, {"en": "Guns stay open until you’re on the stand and I say “load”.", "meaning": "Aucun fusil fermé hors du poste ; on ne charge que sur l'ordre du moniteur.", "say": "Les fusils restent ouverts jusqu'à ce que vous soyez sur le poste et que je dise « chargez »."}, {"en": "Point at my nose, both eyes open. Now close your left eye.", "meaning": "Test de l'œil directeur : si le doigt saute, l'œil droit n'est pas l'œil directeur.", "say": "Pointez mon nez, les deux yeux ouverts. Maintenant, fermez l'œil gauche."}, {"en": "Front foot pointing at the break point, weight forward.", "meaning": "Position : placez les pieds pour l'endroit où le plateau sera cassé ; penchez-vous légèrement vers l'avant.", "say": "Le pied avant vers le point de casse, le poids vers l'avant."}, {"en": "Gun down, stock under the line. Mount only when you see it.", "meaning": "Position d'attente du Sporting™ : le fusil ne monte qu'après l'apparition du plateau ; en Compak® Sporting, la position à l'appel est libre.", "say": "Fusil bas, crosse sous la ligne. Épaulez seulement quand vous le voyez."}, {"en": "Watch this one. Where do you first see it clearly?", "meaning": "Le moniteur fixe le point de prise.", "say": "Regardez celui-ci. Où le voyez-vous nettement pour la première fois ?"}, {"en": "Hold your muzzles about halfway back, just under the line.", "meaning": "Point d'attente entre le point de prise et le point de casse, légèrement sous la trajectoire du plateau.", "say": "Tenez vos canons à peu près à mi-chemin en arrière, juste sous la ligne."}, {"en": "Behind it. Give it more.", "meaning": "La gerbe est passée derrière le plateau : plus d'avance.", "say": "Derrière. Donnez-lui plus."}, {"en": "Call it three feet — that’s the picture you want.", "meaning": "L'image d'avance à voir au moment du tir ; les pieds comme impression, gardez l'unité.", "say": "Disons trois pieds : c'est l'image que vous voulez."}, {"en": "Over the top. You lifted your head — stay in the gun.", "meaning": "Manqué au-dessus, parce que la joue a quitté la crosse.", "say": "Au-dessus. Vous avez levé la tête : restez dans le fusil."}, {"en": "Smoked it! Same again.", "meaning": "Tir parfait ; refaites exactement la même chose.", "say": "Pulvérisé ! Pareil."}, {"en": "You stopped the gun. Keep it moving through the shot.", "meaning": "Manqué derrière parce que le swing s'est arrêté ; accompagnez.", "say": "Vous avez arrêté le fusil. Gardez-le en mouvement pendant le tir."}, {"en": "Next is a report pair: crosser first, then the rabbit.", "meaning": "Le rabbit est lancé au bruit du coup tiré sur le traversard.", "say": "Ensuite, un doublé coup de fusil : le traversard d'abord, puis le rabbit."}, {"en": "Eyes first, then the gun.", "meaning": "Sur le second plateau, trouvez-le avec les yeux avant de bouger les canons.", "say": "Les yeux d'abord, ensuite le fusil."}, {"en": "Keep the muzzles under the rabbit.", "meaning": "Restez bas sur un plateau qui roule, pour qu'un saut rencontre quand même la gerbe.", "say": "Gardez les canons sous le rabbit."}, {"en": "Change to quarter and half for this stand.", "meaning": "Montez des chokes 1/4 et 1/2 (ouvert, puis un peu plus serré).", "say": "Passez en quart et demi pour ce poste."}, {"en": "Let’s call it a day. Three things for tomorrow: feet, head, follow-through.", "meaning": "Fin de séance ; le moniteur résume : notez ces points pour l'invité.", "say": "On s'arrête là pour aujourd'hui. Trois choses pour demain : les pieds, la tête, l'accompagnement."}], "quiz": [{"q": "Quand et comment interprète-t-on le briefing de sécurité ?", "options": ["Brièvement en chuchotage pendant que les invités chargent", "Au début, en consécutive, phrase par phrase et intégralement", "Seulement si un invité le demande", "Après le premier poste"], "answer": 1, "why": "La sécurité passe en premier et ne doit pas être abrégée ; la consécutive permet à chaque règle d'être bien comprise."}, {"q": "Le moniteur dit « Behind it. Give it more. » Quelle est la meilleure traduction courte entre deux plateaux ?", "options": ["« Vous êtes un peu en retard, réessayez, peut-être plus vite »", "« Derrière. Plus d'avance. »", "« Tirez plus tôt »", "« Bien, pareil »"], "answer": 1, "why": "Reprenez le moniteur : même longueur, même ordre, diagnostic plus correction, rien d'ajouté."}, {"q": "Pourquoi garder les mêmes mots français pour « pick-up point », « hold point » et « break point » toute la journée ?", "options": ["Le règlement l'exige", "Pour que le moniteur comprenne le français", "Pour que l'invité retienne trois notions stables et ne les confonde pas", "Cela n'a pas d'importance"], "answer": 2, "why": "Des termes constants construisent la carte mentale du poste chez l'invité ; changer de mots fait passer trois notions pour six."}]}]}]};
